# ---------------------------------------------------------------------------
#  Logging (console + lore.log, so auto-start runs are debuggable)
# ---------------------------------------------------------------------------
def _here():
    # When bundled by PyInstaller, files live next to the .exe (the install
    # folder); in dev they live next to this .py. The BUNDLED, read-only files
    # (ffmpeg, lore.ico) are found relative to this.
    if getattr(sys, "frozen", False):
        return os.path.dirname(sys.executable)
    return os.path.dirname(os.path.abspath(__file__))


def _data_dir():
    """User-writable folder for settings, log, games list and lock/IPC files.
    The app itself can live in a read-only place (e.g. C:\\Program Files), so these
    must NOT be written next to the .exe or saving fails with a permission error."""
    base = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA")
    d = os.path.join(base, "Lore") if base else _here()
    try:
        os.makedirs(d, exist_ok=True)
        return d
    except Exception:
        return _here()


_JOB = [None]


def _job_object():
    """ONE Windows Job Object with KILL_ON_JOB_CLOSE: every child bound to
    it dies when this process dies - however it dies. Tonight's orphaned
    model servers (15 GB of VRAM surviving the app, then silently adopted
    by the next run) are impossible once children live here."""
    if _JOB[0] is not None or os.name != "nt":
        return _JOB[0]
    try:
        import ctypes
        import ctypes.wintypes as wt

        class _IOC(ctypes.Structure):
            _fields_ = [("ReadOperationCount", ctypes.c_ulonglong),
                        ("WriteOperationCount", ctypes.c_ulonglong),
                        ("OtherOperationCount", ctypes.c_ulonglong),
                        ("ReadTransferCount", ctypes.c_ulonglong),
                        ("WriteTransferCount", ctypes.c_ulonglong),
                        ("OtherTransferCount", ctypes.c_ulonglong)]

        class _BASIC(ctypes.Structure):
            _fields_ = [("PerProcessUserTimeLimit", wt.LARGE_INTEGER),
                        ("PerJobUserTimeLimit", wt.LARGE_INTEGER),
                        ("LimitFlags", wt.DWORD),
                        ("MinimumWorkingSetSize", ctypes.c_size_t),
                        ("MaximumWorkingSetSize", ctypes.c_size_t),
                        ("ActiveProcessLimit", wt.DWORD),
                        ("Affinity", ctypes.POINTER(wt.ULONG)),
                        ("PriorityClass", wt.DWORD),
                        ("SchedulingClass", wt.DWORD)]

        class _EXT(ctypes.Structure):
            _fields_ = [("BasicLimitInformation", _BASIC),
                        ("IoInfo", _IOC),
                        ("ProcessMemoryLimit", ctypes.c_size_t),
                        ("JobMemoryLimit", ctypes.c_size_t),
                        ("PeakProcessMemoryUsed", ctypes.c_size_t),
                        ("PeakJobMemoryUsed", ctypes.c_size_t)]

        k32 = ctypes.windll.kernel32
        h = k32.CreateJobObjectW(None, None)
        info = _EXT()
        info.BasicLimitInformation.LimitFlags = 0x2000  # KILL_ON_JOB_CLOSE
        if h and k32.SetInformationJobObject(h, 9, ctypes.byref(info),
                                             ctypes.sizeof(info)):
            _JOB[0] = h
        else:
            _JOB[0] = 0
    except Exception:
        _JOB[0] = 0
    return _JOB[0]


_ERRMODE_SET = [False]


def _popen(*a, **k):
    """subprocess.Popen + bind the child to the kill-on-close job.

    SEM_NOGPFAULTERRORBOX first, once: children inherit the parent's
    error mode, and without it a model server that dies on the graphics
    driver throws a Windows crash dialog onto HIS SCREEN mid-game. The
    crash still logs and still retries - it just stops shouting."""
    if os.name == "nt" and not _ERRMODE_SET[0]:
        try:
            import ctypes
            ctypes.windll.kernel32.SetErrorMode(0x8003)
            _ERRMODE_SET[0] = True
        except Exception:
            pass
    pr = subprocess.Popen(*a, **k)
    try:
        j = _job_object()
        if j:
            import ctypes
            ctypes.windll.kernel32.AssignProcessToJobObject(
                j, int(pr._handle))
    except Exception:
        pass
    return pr


_LOG_WHY = [False, False]      # each fallback names its cause ONCE


def log(msg):
    line = f"[{_dt.datetime.now():%H:%M:%S}] {msg}"
    try:
        print(line, flush=True)        # no-op in the windowed build (no console)
    except Exception:
        pass
    try:
        lp = os.path.join(_data_dir(), "lore.log")
        try:
            if os.path.getsize(lp) > 4_000_000:   # keep one past life
                os.replace(lp, lp + ".1")
        except OSError:
            pass
        with open(lp, "a", encoding="utf-8") as fh:
            fh.write(line + "\n")
    except Exception as e_log:
        # THE BEACON. The 4:04 instance of 2.93 ran for hours writing
        # opened.json into this very folder while lore.log gained not one
        # line - and every recorder mystery since (the Bazaar's self-stop
        # included) has been undiagnosable for it. If the main log write
        # fails, the line goes to a second file instead of nowhere, and
        # the failure itself is written down once.
        wrote = False
        try:
            lb = os.path.join(_data_dir(), "lore.log.b")
            with open(lb, "a", encoding="utf-8") as fh:
                if not _LOG_WHY[0]:
                    _LOG_WHY[0] = True
                    fh.write("[the main log failed: %r]\n" % (e_log,))
                fh.write(line + "\n")
            wrote = True
        except Exception:
            pass
        if not wrote:
            # THE THIRD CHANNEL. 3.01's main instance lost every line
            # with BOTH channels above failing together (same folder,
            # same invisible cause) - while its sidecar writes to the
            # Records volume never missed. The last resort lives where
            # the writes provably work, and it writes down WHY the
            # healthy channels failed - the fact every dead-log hunt
            # has been missing. Engages only on double failure; a
            # healthy install never creates this file.
            try:
                d3 = _thumb_dir(SETTINGS.get("output_dir", ""))
                with open(os.path.join(d3, "lore.log.c"), "a",
                          encoding="utf-8") as fh:
                    if not _LOG_WHY[1]:
                        _LOG_WHY[1] = True
                        fh.write("[log AND beacon failed: %r]\n"
                                 % (e_log,))
                    fh.write(line + "\n")
            except Exception:
                pass


# ---------------------------------------------------------------------------
#  Single-instance lock + "show the window" IPC
#  (stops "Start" from launching a second recorder on top of the first, and lets a
#   second launch pop the running instance's window instead of starting a new copy)
# ---------------------------------------------------------------------------
def _lock_path():
    return os.path.join(_data_dir(), "lore.lock")


def _show_flag_path():
    return os.path.join(_data_dir(), "show.flag")


def _watcher_running_pid():
    """PID of a live OTHER Lore instance, or None.

    Critically, we confirm the PID belongs to an ACTUAL Lore process - not just
    that *some* process has that number. After a freeze/crash or a reboot the lock
    file can be left behind pointing at an old PID, and the OS routinely reuses that
    PID for an unrelated program. The old check only asked 'does any process with
    this PID exist?', so a reused PID made Lore think a copy was already running
    and refuse to start (double-click did nothing). Matching the executable fixes
    that, and a stale lock simply gets reclaimed."""
    try:
        with open(_lock_path()) as fh:
            pid = int(fh.read().strip())
    except Exception:
        return None
    if pid == os.getpid():
        return None
    try:
        if not psutil.pid_exists(pid):
            return None
        p = psutil.Process(pid)
        pname = (p.name() or "").lower()
        # Frozen build: the process is Lore.exe. Exact-match on the name -
        # a substring test would false-positive on e.g. explorer.exe ('lore').
        if pname == "lore.exe" or pname.startswith("lore."):
            return pid
        # Running from source: same interpreter (python/pythonw) - only count it if
        # it's actually running our script, otherwise an unrelated python is not us.
        me_name = (psutil.Process(os.getpid()).name() or "").lower()
        if pname == me_name:
            try:
                cl = " ".join(p.cmdline()).lower()
                if "lore.py" in cl:
                    return pid
            except Exception:
                return pid    # can't read its command line; assume same-name is us
        return None           # PID reused by something unrelated -> stale lock
    except Exception:
        return None


def _signal_show():
    """Ask an already-running tray instance to pop its settings window."""
    try:
        open(_show_flag_path(), "w").close()
    except Exception:
        pass


_SINGLETON_MUTEX = None
_MUTEX_NAME = "Lore_SingleInstance_Gate"   # must match installer.iss AppMutex


def _hold_singleton_mutex():
    """Create/hold a named Windows mutex for our whole lifetime AND report whether
    we are the FIRST instance. This is the authoritative, OS-atomic singleton gate:
    the lock file alone has a check-then-write race where two launches fired within
    a few milliseconds (a common double-click) both read 'no lock' and both start,
    ending up with two recorders writing into the same folder. CreateMutexW is
    atomic in the kernel, so exactly one launch wins. The installer declares the
    same name via AppMutex to detect a running copy during an update.

    Returns True if we are the first instance (also True off-Windows, or on any
    error - we never block startup on a mutex hiccup). Idempotent: a second call in
    the SAME process (e.g. tray -> console fallback) returns True."""
    global _SINGLETON_MUTEX
    if os.name != "nt":
        return True
    if _SINGLETON_MUTEX:
        return True                       # already acquired by us this process
    try:
        import ctypes
        ERROR_ALREADY_EXISTS = 183
        k32 = ctypes.WinDLL("kernel32", use_last_error=True)
        h = k32.CreateMutexW(None, False, _MUTEX_NAME)
        err = ctypes.get_last_error()
        _SINGLETON_MUTEX = h
        if not h:
            return True                   # couldn't create it; don't block on that
        return err != ERROR_ALREADY_EXISTS
    except Exception:
        _SINGLETON_MUTEX = None
        return True


# ---------------------------------------------------------------------------
#  Settings
# ---------------------------------------------------------------------------
def _settings_path():
    return os.path.join(_data_dir(), "settings.json")


def _migrate_legacy_data():
    """One-time: inherit everything Records (LORE's previous incarnation) knew,
    so the tome opens already filled - settings, the games/ignore lists, the
    file-ownership manifest (the storage cap keeps managing old recordings)
    and any pending HDR->SDR conversions. Best-effort, silent, and it never
    overwrites anything LORE has already written."""
    newp = _settings_path()
    if os.path.exists(newp):
        return
    base = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA") or ""
    candidates = [os.path.join(base, "Records") if base else "", _here()]
    for old in candidates:
        try:
            if not (old and os.path.isfile(os.path.join(old, "settings.json"))):
                continue
            for name in ("settings.json", "games.txt", "ignore.txt",
                         "created_files.json", "finish_queue.json"):
                src = os.path.join(old, name)
                dst = os.path.join(_data_dir(), name)
                if os.path.isfile(src) and not os.path.exists(dst):
                    shutil.copy2(src, dst)
            log(f"Inherited existing setup from {old}")
            return
        except Exception:
            pass


def _migrate_settings_shape():
    """Bring older settings.json shapes up to date in memory (saved back on the
    next Save). Best-effort and silent: never raises, never overwrites a value the
    user has clearly set on the new shape."""
    s = SETTINGS
    # hdr_mode history: checkbox (bool) -> auto|on|off -> auto|tonemap|off ->
    # auto|off (1.24: the live tone-map path is gone - the 8/10-bit sources it
    # read were proven clipped at capture, so it could never look right). Any
    # legacy value that meant "handle HDR" maps to auto; only "off" stays off.
    hm = s.get("hdr_mode")
    if isinstance(hm, bool):
        s["hdr_mode"] = "auto"
    elif isinstance(hm, str):
        if hm.lower() not in ("auto", "off"):
            s["hdr_mode"] = "auto"
    # retired with the live tone-map path (1.24)
    s.pop("hdr_input", None)
    s.pop("hdr_peak_nits", None)
    # Start and Stop used to be two separate hotkeys; they are now one record
    # toggle. If the new key isn't present, inherit the old Start key so nobody's
    # muscle memory breaks.
    if not s.get("hotkey_record"):
        legacy = (s.get("hotkey_start") or "").strip()
        s["hotkey_record"] = legacy or DEFAULTS["hotkey_record"]
    # Drop the retired keys so they don't linger in settings.json.
    s.pop("hotkey_start", None)
    s.pop("hotkey_stop", None)


def _sanitize_settings(d):
    """Coerce/clamp values loaded from settings.json so a corrupt or hand-edited file
    can't feed a bad value (e.g. framerate 0, bitrate -5) straight into ffmpeg. Each
    numeric key falls back to its DEFAULT on a bad type/range; a few small enums fall
    back if not in their allowed set. 'encoder' is deliberately NOT whitelisted - a
    power user may hand-set one the GUI doesn't list, and resolve_encoder already
    validates it by probing. hdr_mode is left for _migrate_settings_shape (it maps a
    legacy boolean)."""
    INT_BOUNDS = {
        "framerate": (1, 1000), "bitrate_mbps": (1, 1000), "monitor_index": (-1, 64),
        "poll_interval": (1, 60), "segment_seconds": (2, 60), "replay_seconds": (1, 3600),
        "min_keep_seconds": (0, 3600),
        "audio_offset_ms": (-60000, 60000),
        "max_storage_gb": (0, 1000000), "sfx_volume": (0, 100),
        "clip_hotkey_seconds": (1, 3600), "discord_max_mb": (1, 1000),
        "discord_clip_seconds": (1, 3600), "discord_quality_mbps": (1, 1000),
        "sdr_finish_max_min": (1, 600), "afk_minutes": (1, 120),
        "afk_ai_minutes": (1, 240),
    }
    for k, (lo, hi) in INT_BOUNDS.items():
        try:
            d[k] = max(lo, min(hi, int(d.get(k, DEFAULTS.get(k, lo)))))
        except Exception:
            d[k] = DEFAULTS.get(k, lo)
    ENUMS = {
        "amf_quality": ("speed", "balanced", "quality"),
        "audio_mode": ("mix", "separate"),
        "detection_mode": ("auto", "list"),
        "popup_style": ("slide", "rise", "pop", "glow", "sweep", "off"),
        "popup_size": ("small", "medium", "large", "huge"),
        "capture_scope": ("screen", "window"),
        "capture_backend": ("auto", "ddagrab"),
        "seek_step": ("frame", "1", "5", "10"),
    }
    # (hdr_mode is normalised by _migrate_settings_shape, which also maps legacy values)
    for k, allowed in ENUMS.items():
        v = d.get(k)
        d[k] = v.lower() if (isinstance(v, str) and v.lower() in allowed) else DEFAULTS[k]
    # vault pins: a list of chapter keys; anything malformed collapses to []
    try:
        d["cap_pinned_games"] = [str(x).strip().lower()
                                 for x in (d.get("cap_pinned_games") or [])
                                 if str(x).strip()][:500]
    except Exception:
        d["cap_pinned_games"] = []
    # 3.31 sources: a hand-edited settings.json must not feed a non-list
    # into the tap resolver; the .exe rule mirrors load_game_list. A
    # string is not a list of apps - it collapses to the default list.
    try:
        raw = d.get("voice_apps")
        if raw is None:
            raw = DEFAULTS["voice_apps"]
        if not isinstance(raw, (list, tuple)):
            raise TypeError("voice_apps is not a list")
        d["voice_apps"] = [str(x).strip().lower() for x in raw
                           if str(x).strip()][:20]
        d["voice_apps"] = [x if x.endswith(".exe") else x + ".exe"
                           for x in d["voice_apps"]]
    except Exception:
        d["voice_apps"] = list(DEFAULTS["voice_apps"])
    d["capture_by_source"] = bool(d.get("capture_by_source",
                                        DEFAULTS["capture_by_source"]))
    d["read_game_lines"] = bool(d.get("read_game_lines",
                                      DEFAULTS["read_game_lines"]))
    d["black_guard"] = bool(d.get("black_guard", DEFAULTS["black_guard"]))


def load_settings():
    global SETTINGS
    with _SETTINGS_LOCK:
        _migrate_legacy_data()
        new = dict(DEFAULTS)
        if os.path.isfile(_settings_path()):
            try:
                with open(_settings_path(), encoding="utf-8") as fh:
                    new.update(json.load(fh))
            except Exception as e:
                log(f"Could not read settings.json ({e}); using defaults.")
        _sanitize_settings(new)
        # Single rebind: a concurrent reader (the watcher) never sees a half-built
        # dict that's momentarily back at DEFAULTS.
        SETTINGS = new
        _migrate_settings_shape()
        _resolve_ffmpeg_paths()
        return SETTINGS


def _resolve_ffmpeg_paths():
    """Prefer a bundled ffmpeg (so friends don't install anything). An explicit
    path is respected ONLY while it actually exists: settings inherited from
    Records carry Records' bundled path, and the moment Records is uninstalled
    that path dies - which used to greet every launch with 'can't find its
    video tool' even though LORE ships its own copy right next to the exe.
    A dead explicit path now heals itself: bundled -> old Records installs ->
    PATH, and the fix is persisted so it never has to heal twice."""
    exp = SETTINGS.get("ffmpeg_path", "ffmpeg")
    explicit = exp not in ("ffmpeg", "", None)
    if explicit and os.path.isfile(exp):
        return                        # user's explicit path, alive - respect it
    if explicit:
        log(f"Configured ffmpeg not reachable ({exp}); using another copy this run.")
    cands = [os.path.join(_here(), "ffmpeg", "bin", "ffmpeg.exe")]
    for pf in (os.environ.get("ProgramFiles"), os.environ.get("ProgramFiles(x86)")):
        if pf:
            cands.append(os.path.join(pf, "Lore", "ffmpeg", "bin", "ffmpeg.exe"))
            cands.append(os.path.join(pf, "Records", "ffmpeg", "bin", "ffmpeg.exe"))
    for cand in cands:
        if os.path.isfile(cand):
            # Heal IN MEMORY ONLY. We deliberately never rewrite an explicit
            # ffmpeg_path: a path on a merely-disconnected network/USB drive is
            # indistinguishable from a permanently-dead one, and silently
            # discarding the user's choice would lose it for good. Recording
            # uses this copy for the session; when the drive returns next
            # launch, the user's own path is respected again.
            SETTINGS["ffmpeg_path"] = cand
            return
    if explicit:
        SETTINGS["ffmpeg_path"] = "ffmpeg"     # last hope: PATH (in-memory only)


def _atomic_write_json(path, obj):
    """Write JSON to `path` so a crash or power loss can never leave a truncated,
    unreadable file: write a sibling temp file, flush it to disk, then atomically
    replace the real one. Raises on failure (callers decide how loud to be)."""
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(obj, fh, indent=2)
        fh.flush()
        try:
            os.fsync(fh.fileno())
        except Exception:
            pass
    os.replace(tmp, path)   # atomic on Windows and POSIX


def save_settings(data):
    # Never persist runtime-internal keys (e.g. _encoder_resolved): they're
    # re-derived each launch, and saving a stale one would skip GPU re-detection.
    clean = {k: v for k, v in data.items() if not k.startswith("_")}
    with _SETTINGS_LOCK:
        _atomic_write_json(_settings_path(), clean)


# ---------------------------------------------------------------- the key
# NOT in settings.json. That file is plain JSON, gets copied around, and shows
# up in a screenshot the moment anyone opens it. This one is encrypted by
# Windows against this user on this machine, and nothing in LORE ever reads it
# back to the interface - the closest you can get is "yes, there is one".
def _key_path():
    return os.path.join(_data_dir(), "claude.key")


def _dpapi(data, unprotect=False):
    """Windows DPAPI. Returns None if it cannot be done, and the caller then
    refuses to store anything rather than writing a key in the clear."""
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes

        class BLOB(ctypes.Structure):
            _fields_ = [("cbData", wintypes.DWORD),
                        ("pbData", ctypes.POINTER(ctypes.c_char))]

        buf = ctypes.create_string_buffer(data, len(data))
        src = BLOB(len(data), ctypes.cast(buf, ctypes.POINTER(ctypes.c_char)))
        out = BLOB()
        fn = (ctypes.windll.crypt32.CryptUnprotectData if unprotect
              else ctypes.windll.crypt32.CryptProtectData)
        args = ([ctypes.byref(src), None, None, None, None, 0,
                 ctypes.byref(out)] if not unprotect else
                [ctypes.byref(src), None, None, None, None, 0,
                 ctypes.byref(out)])
        if not fn(*args):
            return None
        try:
            return ctypes.string_at(out.pbData, out.cbData)
        finally:
            ctypes.windll.kernel32.LocalFree(out.pbData)
    except Exception:
        return None


def _key_save(raw):
    """Store a key. Returns (ok, why)."""
    raw = (raw or "").strip()
    if not raw:
        return False, "nothing to save"
    if not raw.startswith("sk-ant-"):
        return False, "that does not look like an Anthropic key"
    blob = _dpapi(raw.encode("utf-8"))
    if blob is None:
        return False, "this PC will not encrypt it, so it will not be stored"
    try:
        os.makedirs(os.path.dirname(_key_path()), exist_ok=True)
        with open(_key_path(), "wb") as fh:
            fh.write(blob)
        # remember only what is safe to show: when it went in, and the last
        # four characters, so you can tell one key from another
        when = _dt.datetime.now().strftime("%d %B %Y")
        SETTINGS["claude_key_added"] = when
        SETTINGS["claude_key_tail"] = raw[-4:]
        _persist_setting("claude_key_added", when)
        _persist_setting("claude_key_tail", raw[-4:])
        log("Claude key stored (encrypted to this Windows account).")
        return True, ""
    except Exception as e:
        return False, str(e)


def _key_read():
    """The key itself, for LORE's own use only. Never returned over the API."""
    try:
        with open(_key_path(), "rb") as fh:
            blob = fh.read()
    except OSError:
        return None
    out = _dpapi(blob, unprotect=True)
    return out.decode("utf-8", "replace") if out else None


def _key_forget():
    try:
        os.remove(_key_path())
    except OSError:
        pass
    for k in ("claude_key_added", "claude_key_tail"):
        _persist_setting(k, "")      # also clears the live SETTINGS copy
    log("Claude key forgotten.")
    return True


def _persist_setting(key, value):
    """Update a single key in settings.json on disk without disturbing the live
    SETTINGS or other keys. Used by the watcher to remember a discovered fix."""
    try:
        with _SETTINGS_LOCK:
            d = {}
            if os.path.isfile(_settings_path()):
                with open(_settings_path(), encoding="utf-8") as fh:
                    d = json.load(fh)
            d[key] = value
            _atomic_write_json(_settings_path(), d)
            SETTINGS[key] = value
    except Exception as e:
        log(f"Could not persist setting '{key}': {e}")


# ---------------------------------------------------------------------------
#  Game detection
# ---------------------------------------------------------------------------
def running_process_names():
    names = set()
    for p in psutil.process_iter(["name"]):
        n = p.info.get("name")
        if n:
            names.add(n.lower())
    return names


def _looks_gone(current):
    """The three-agreements gone test in ONE place: a game reads as
    closed only when a TRUSTWORTHY process walk lacks it AND no window
    of its answers. Four separate sites used to trust a single raw walk
    - the active-recording check among them, which is precisely how a
    16-minute Bazaar saved itself and restarted while he was playing:
    two short walks in a row, debounce of two, recording gone."""
    if not current:
        return False
    names = running_process_names()
    return (_process_walk_trustworthy(names)
            and current not in names
            and not _exe_has_any_window(current))


def _process_walk_trustworthy(names):
    """Did that walk actually see the machine?

    Windows is never running twelve processes. A list that short means the
    walk was refused or cut off, and a recording must never be ended on the
    strength of a question that failed to be asked. Idle Windows sits around
    a hundred; twenty is generous."""
    return len(names) >= 20


def load_game_list():
    names = set()
    path = os.path.join(_data_dir(), "games.txt")
    if os.path.isfile(path):
        with open(path, encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line and not line.startswith("#"):
                    if not line.lower().endswith(".exe"):
                        line += ".exe"
                    names.add(line.lower())
    return names


def read_games_lines():
    """Raw game names from games.txt (as the user typed them, no .exe forced)."""
    path = os.path.join(_data_dir(), "games.txt")
    out = []
    if os.path.isfile(path):
        with open(path, encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line and not line.startswith("#"):
                    out.append(line)
    return out


def write_games_lines(lines):
    path = os.path.join(_data_dir(), "games.txt")
    with open(path + ".tmp", "w", encoding="utf-8") as fh:
        fh.write("# Games Lore always captures (one name per line, e.g. eldenring).\n")
        for ln in lines:
            ln = ln.strip()
            if ln:
                fh.write(ln + "\n")
    os.replace(path + ".tmp", path)   # a crash mid-write keeps the old list


def _ignore_path():
    return os.path.join(_data_dir(), "ignore.txt")


def read_ignore_lines():
    """User-added 'never auto-record' names from ignore.txt (as typed)."""
    out = []
    path = _ignore_path()
    if os.path.isfile(path):
        with open(path, encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line and not line.startswith("#"):
                    out.append(line)
    return out


def write_ignore_lines(lines):
    """Save the user's extra never-record list. The built-in list always applies on
    top of this, so games keep recording even if the user empties this file."""
    with open(_ignore_path(), "w", encoding="utf-8") as fh:
        fh.write("# Extra apps Lore should NEVER auto-record when full-screen\n")
        fh.write("# (one .exe name per line, e.g. photoshop.exe). Games are still\n")
        fh.write("# always recorded - your games list and full-screen game detection\n")
        fh.write("# take priority over this list.\n")
        for ln in lines:
            ln = ln.strip()
            if ln:
                if not ln.lower().endswith(".exe"):
                    ln += ".exe"
                fh.write(ln + "\n")


def load_ignore_list():
    """The effective never-auto-record set: the built-in baseline UNION the user's
    ignore.txt additions. Always lower-case, .exe forced."""
    names = set(IGNORE_PROCESSES)
    for ln in read_ignore_lines():
        ln = ln.strip().lower()
        if ln:
            if not ln.endswith(".exe"):
                ln += ".exe"
            names.add(ln)
    return names


def _window_monitor_rect(hwnd):
    """(left, top, right, bottom) of the monitor the given window is on, or None.
    Lets borderless-fullscreen be detected on ANY screen, not just the primary."""
    if os.name != "nt" or not hwnd:
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        MONITOR_DEFAULTTONEAREST = 2
        hmon = user32.MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST)
        if not hmon:
            return None

        class MONITORINFO(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.DWORD), ("rcMonitor", wintypes.RECT),
                        ("rcWork", wintypes.RECT), ("dwFlags", wintypes.DWORD)]

        mi = MONITORINFO()
        mi.cbSize = ctypes.sizeof(MONITORINFO)
        if user32.GetMonitorInfoW(ctypes.c_void_p(hmon), ctypes.byref(mi)):
            r = mi.rcMonitor
            return (r.left, r.top, r.right, r.bottom)
    except Exception:
        return None
    return None


def _watched_monitor_rect():
    """rcMonitor of the screen Lore is set to record (the monitor_index setting;
    0 = the primary screen). Full-screen DETECTION only fires for windows on this
    monitor - a game or app going fullscreen on any OTHER screen is deliberately
    ignored, because Lore would end up recording the watched screen anyway (the
    'it recorded my second monitor's fullscreen app' complaint). Monitors are ranked
    by display number, the same contract build_video_cmd uses for ddagrab output_idx.
    Returns None when monitors can't be enumerated (then any monitor is accepted)."""
    try:
        mons = _monitors_ranked()
        if not mons:
            return None
        idx = min(max(0, _resolve_capture_monitor()), len(mons) - 1)
        return tuple(mons[idx]["rect"])
    except Exception:
        return None


# ---------------------------------------------------------------------------
#  Game recognition v2 (Lore 1.1) - ShadowPlay-style, three signals instead of
#  one guess:
#    1. the WINDOW  - a real, visible, decent-sized top-level window
#    2. the OS      - Windows' own game database (GameConfigStore: the Game
#                     Bar has watched every game launch for years; 142 titles
#                     strong on the dev machine, zero chat apps or browsers)
#    3. the GPU     - sustained per-process 3D-engine load via PDH counters
#                     (the same numbers Task Manager's GPU column shows; games
#                     render at 30-100%, Claude/Discord/browsers idle at ~0-1%)
#  A window whose exe Windows already knows as a game records at once -
#  windowed or fullscreen, any monitor. An UNKNOWN exe must earn it:
#  fullscreen on the watched screen AND real 3D load on consecutive polls -
#  then it's learned, so the next launch is instant. Fullscreen alone never
#  starts a recording again (that's what recorded a fullscreened chat app).
# ---------------------------------------------------------------------------
_GAMEDB = {"set": None, "t": 0.0}


def _windows_game_db():
    """Exe basenames Windows itself has recognised as games - read from
    HKCU\\System\\GameConfigStore\\Children (each entry's MatchedExeFullPath;
    the Game Bar writes one per game it detects). Cached for 5 minutes.
    Crash-handler style entries are filtered; the user's ignore list still
    outranks whatever remains."""
    now = time.time()
    if _GAMEDB["set"] is not None and now - _GAMEDB["t"] < 300:
        return _GAMEDB["set"]
    names = set()
    try:
        import winreg
        root = r"System\GameConfigStore\Children"
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, root) as k:
            count = winreg.QueryInfoKey(k)[0]
            for i in range(count):
                try:
                    sub = winreg.EnumKey(k, i)
                    with winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                                        root + "\\" + sub) as sk:
                        p, _ = winreg.QueryValueEx(sk, "MatchedExeFullPath")
                except OSError:
                    continue
                b = os.path.basename(str(p)).strip().lower()
                if not b.endswith(".exe"):
                    continue
                # junk that rides along in the store: crash reporters put up
                # small dialogs and must never look like the game itself
                if any(t in b for t in ("crash", "crs-handler", "report",
                                        "helper", "launcher", "setup",
                                        "unins", "redist")):
                    continue
                names.add(b)
    except Exception:
        pass
    if names or _GAMEDB["set"] is None:
        _GAMEDB["set"] = names
        _GAMEDB["t"] = now
        if names:
            log(f"Windows game database: {len(names)} titles recognised.")
    return _GAMEDB["set"] or set()


_GPU_PDH = {"q": None, "c": None, "t": 0.0, "map": {}}


def _gpu3d_usage(max_age=2.0):
    """{pid: percent} of 3D-engine GPU utilization, summed over a process's
    3D engine instances - via PDH 'GPU Engine' counters on pdh.dll (pure
    ctypes, no dependencies; exactly what Task Manager's GPU column reads).
    ONE query is kept open for the app's lifetime: PDH rates are deltas
    between collects, so each call measures activity since the previous call
    (results younger than max_age are served from cache). Any PDH hiccup
    closes the query and self-heals on the next call; failures mean {} -
    the caller then simply can't confirm a GPU signal, never crashes."""
    now = time.time()
    if _GPU_PDH["q"] is not None and now - _GPU_PDH["t"] < max_age:
        return _GPU_PDH["map"]
    try:
        import ctypes
        from ctypes import wintypes
        pdh = ctypes.windll.pdh

        class _FMT(ctypes.Structure):
            _fields_ = [("CStatus", wintypes.DWORD), ("pad", wintypes.DWORD),
                        ("doubleValue", ctypes.c_double)]

        class _ITEM(ctypes.Structure):
            _fields_ = [("szName", ctypes.c_wchar_p), ("FmtValue", _FMT)]

        if _GPU_PDH["q"] is None:
            q = ctypes.c_void_p()
            if pdh.PdhOpenQueryW(None, None, ctypes.byref(q)) != 0:
                return {}
            c = ctypes.c_void_p()
            if pdh.PdhAddEnglishCounterW(
                    q, r"\GPU Engine(*engtype_3D)\Utilization Percentage",
                    None, ctypes.byref(c)) != 0:
                pdh.PdhCloseQuery(q)
                return {}
            pdh.PdhCollectQueryData(q)      # baseline; rates need two collects
            _GPU_PDH.update({"q": q, "c": c, "t": now, "map": {}})
            return {}
        q, c = _GPU_PDH["q"], _GPU_PDH["c"]
        if pdh.PdhCollectQueryData(q) != 0:
            raise OSError("collect failed")
        sz = wintypes.DWORD(0)
        cnt = wintypes.DWORD(0)
        r = pdh.PdhGetFormattedCounterArrayW(
            c, 0x00000200, ctypes.byref(sz), ctypes.byref(cnt), None) & 0xFFFFFFFF
        if r != 0x800007D2:                 # PDH_MORE_DATA
            raise OSError(f"size {r:#x}")
        buf = (ctypes.c_byte * sz.value)()
        if pdh.PdhGetFormattedCounterArrayW(
                c, 0x00000200, ctypes.byref(sz), ctypes.byref(cnt), buf) != 0:
            raise OSError("array failed")
        items = ctypes.cast(buf, ctypes.POINTER(_ITEM * cnt.value)).contents
        per = {}
        for it in items:
            name = it.szName or ""
            if it.FmtValue.CStatus not in (0, 1):
                continue
            i = name.find("pid_")
            if i < 0:
                continue
            j = name.find("_", i + 4)
            try:
                pid = int(name[i + 4:j])
            except Exception:
                continue
            per[pid] = per.get(pid, 0.0) + it.FmtValue.doubleValue
        _GPU_PDH["map"] = per
        _GPU_PDH["t"] = now
        return per
    except Exception:
        try:
            if _GPU_PDH["q"] is not None:
                ctypes.windll.pdh.PdhCloseQuery(_GPU_PDH["q"])
        except Exception:
            pass
        _GPU_PDH.update({"q": None, "c": None, "map": {}})
        return {}


_LEARNED = {"set": None}


def _learned_games_path():
    return os.path.join(_data_dir(), "learned_games.json")


_WATCH_NOTE = {"fail_at": 0.0, "fail_g": "",
               "learn_at": 0.0, "learn_g": ""}


def _learned_games():
    """Exes the GPU+fullscreen heuristic has already proven to be games -
    persisted, so every future launch records instantly (windowed too),
    exactly how ShadowPlay 'knows' your library. Ignore-listed names are
    dropped on load, so un-learning is one Settings click away."""
    if _LEARNED["set"] is None:
        s = set()
        try:
            with open(_learned_games_path(), encoding="utf-8") as fh:
                s = {str(x).lower() for x in json.load(fh) if str(x).strip()}
        except Exception:
            pass
        _LEARNED["set"] = s
    return _LEARNED["set"] - load_ignore_list()


def _learn_game_exe(name):
    name = (name or "").strip().lower()
    if not name or name in _learned_games():
        return
    s = _LEARNED["set"] if _LEARNED["set"] is not None else set()
    s.add(name)
    _LEARNED["set"] = s
    try:
        _atomic_write_json(_learned_games_path(), sorted(s))
    except Exception:
        pass
    log(f"Learned a new game: {name} (recognised by GPU + fullscreen).")


# ---------------------------------------------------------------------------
#  AFK detection (Lore 2.0) - "is the user actually here?"
#  Two signals, combined: GetLastInputInfo (keyboard+mouse; the OS's own idle
#  clock) and XInput controller state diffs (pads do NOT touch the OS idle
#  clock - a controller-only session would look AFK without this). Controller
#  changes are dead-zone filtered: an untouched pad's stick jitter increments
#  the packet counter forever and would defeat AFK pause entirely.
# ---------------------------------------------------------------------------
_PAD = {"xi": None, "tried": False, "last": {}, "conn": set(),
        "rescan_t": 0.0, "active_t": 0.0}


def _kbms_idle_ms():
    """Milliseconds since the last keyboard/mouse input in this session.
    0 (= active) on any failure - AFK must fail toward 'user is here'."""
    if os.name != "nt":
        return 0
    try:
        import ctypes
        from ctypes import wintypes

        class LII(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.UINT), ("dwTime", wintypes.DWORD)]
        lii = LII()
        lii.cbSize = ctypes.sizeof(LII)
        if not ctypes.windll.user32.GetLastInputInfo(ctypes.byref(lii)):
            return 0
        return (ctypes.windll.kernel32.GetTickCount() - lii.dwTime) & 0xFFFFFFFF
    except Exception:
        return 0


def _pad_check():
    """Note controller activity into _PAD['active_t']. Dead-zone filtered
    (official XInput thresholds); connected pads polled every call, empty
    slots rescanned every ~5s (Microsoft's own guidance - empty-slot probes
    cost milliseconds each). Safe no-op when XInput is unavailable."""
    if os.name != "nt":
        return
    try:
        import ctypes
        from ctypes import wintypes
        if _PAD["xi"] is None and not _PAD["tried"]:
            _PAD["tried"] = True
            for dll in ("xinput1_4.dll", "xinput1_3.dll", "xinput9_1_0.dll"):
                try:
                    _PAD["xi"] = ctypes.WinDLL(dll)
                    break
                except OSError:
                    pass
        xi = _PAD["xi"]
        if xi is None:
            return

        class GP(ctypes.Structure):
            _fields_ = [("wButtons", wintypes.WORD),
                        ("bLeftTrigger", ctypes.c_ubyte),
                        ("bRightTrigger", ctypes.c_ubyte),
                        ("sThumbLX", ctypes.c_short), ("sThumbLY", ctypes.c_short),
                        ("sThumbRX", ctypes.c_short), ("sThumbRY", ctypes.c_short)]

        class ST(ctypes.Structure):
            _fields_ = [("dwPacketNumber", wintypes.DWORD), ("Gamepad", GP)]
        now = time.time()
        rescan = now - _PAD["rescan_t"] > 5.0
        if rescan:
            _PAD["rescan_t"] = now
        slots = range(4) if rescan else list(_PAD["conn"])
        for i in slots:
            st = ST()
            if xi.XInputGetState(i, ctypes.byref(st)) == 0:
                _PAD["conn"].add(i)
                g, prev = st.Gamepad, _PAD["last"].get(i)
                # THE STATE must differ - never the packet counter alone.
                # Emulated XInput pads (Steam Input / DS4Windows, a
                # DualSense on USB) bump dwPacketNumber at their report
                # rate, hundreds per poll, with the pad flat on the desk:
                # the old bare packet test read that as a human forever
                # and silently defeated the AFK pause.
                # ACTIVITY IS MOVEMENT, NOT POSITION. The sticks
                # were never stored, so they could only be compared
                # against the dead zone - and a pad resting with any
                # drift past it read as a human on every poll, for
                # ever, which is why a 95-minute recording kept rolling
                # through 35 minutes of an empty chair. A constant
                # offset is a constant; only a CHANGE is a person.
                # MOVEMENT is a person - and so is a HELD input.
                # Pure delta read a pinned throttle and a hard-held
                # stick as idle, which would have paused a recording
                # mid-cruise. Triggers count by position (they rest at
                # zero; drift never touches them) and a stick past
                # 25,000 is physically held - drift never reaches
                # near-full deflection. Resting drift still reads
                # idle, which was the whole point.
                if prev is not None and len(prev) >= 8 and (
                        g.wButtons != prev[0]
                        or g.bLeftTrigger > 30 or g.bRightTrigger > 30
                        or abs(g.sThumbLX - prev[4]) > 3200
                        or abs(g.sThumbLY - prev[5]) > 3200
                        or abs(g.sThumbRX - prev[6]) > 3200
                        or abs(g.sThumbRY - prev[7]) > 3200
                        or abs(g.sThumbLX) > 25000
                        or abs(g.sThumbLY) > 25000
                        or abs(g.sThumbRX) > 25000
                        or abs(g.sThumbRY) > 25000):
                    _PAD["active_t"] = now
                _PAD["last"][i] = (g.wButtons, g.bLeftTrigger,
                                   g.bRightTrigger, st.dwPacketNumber,
                                   g.sThumbLX, g.sThumbLY,
                                   g.sThumbRX, g.sThumbRY)
            else:
                _PAD["conn"].discard(i)
                _PAD["last"].pop(i, None)
    except Exception:
        pass


def _cursor_pos():
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes

        class PT(ctypes.Structure):
            _fields_ = [("x", wintypes.LONG), ("y", wintypes.LONG)]
        pt = PT()
        ctypes.windll.user32.GetCursorPos(ctypes.byref(pt))
        return (pt.x, pt.y)
    except Exception:
        return None


# breadcrumb state: the last idle reading, where the cursor was, and when
# the log last spoke (>=10 min between lines - never a log storm)
# THE LAST READING OF THE IDLE CLOCK, shared by everything that wants
# to know without paying for another controller poll.
_AFK_SEEN = {"t": 0.0, "v": 0.0}
_AFK_CLK = {"prev": 0.0, "pos": None, "said": 0.0}


def _afk_idle_seconds():
    """Seconds since the user last did ANYTHING - keyboard, mouse, or a
    real (state-changing, dead-zone-beating) controller input. When a
    countdown that had passed two quiet minutes is reset, the log says by
    WHAT - so a defeated AFK pause (30 silent minutes recorded on
    2026-08-15) is a named culprit next time, not a mystery."""
    _pad_check()
    now = time.time()
    idle = _kbms_idle_ms() / 1000.0
    pad_ago = now - _PAD["active_t"] if _PAD["active_t"] else 1e9
    got = min(idle, pad_ago)
    prev = _AFK_CLK["prev"]
    if prev > 120 and got < 5 and now - _AFK_CLK["said"] > 600:
        _AFK_CLK["said"] = now
        pos, ppos = _cursor_pos(), _AFK_CLK["pos"]
        moved = (abs(pos[0] - ppos[0]) + abs(pos[1] - ppos[1])
                 if pos and ppos else -1)
        src = ("the controller" if pad_ago < 5 else
               f"keyboard/mouse (cursor travelled {moved} px)"
               if moved >= 0 else "keyboard/mouse")
        log(f"AFK countdown reset at {int(prev // 60)} min by {src}.")
    _AFK_CLK["prev"] = got
    _AFK_CLK["pos"] = _cursor_pos()
    # every reader shares this one poll - see _afk_idle_recent
    _AFK_SEEN["t"] = now
    _AFK_SEEN["v"] = got
    return got


def _afk_idle_recent(max_age=2.0):
    """The idle clock WITHOUT adding another poll of the controller.

    _afk_idle_seconds calls _pad_check, which reads "the stick moved"
    as a DELTA against the previous poll. Polling four times as often
    makes every delta a quarter of the size, so a slow stick sweep
    that used to clear the movement floor can stop clearing it - and
    that would quietly blunt the recorder's own AFK pause. The
    recorder's beat stays the one authoritative caller; everything
    added since reads its result while it is fresh.

    Ageing the cached value forward can only ever over-state how long
    he has been away, by at most max_age. On a fifteen-minute
    threshold that is nothing, and on the five-second "he is back"
    test it costs at worst one more beat before the card goes back."""
    now = time.time()
    t = _AFK_SEEN.get("t") or 0
    if t and 0 <= now - t < max_age:
        return float(_AFK_SEEN.get("v") or 0) + (now - t)
    return _afk_idle_seconds()


def _inp_beat(session):
    """THE INPUT CHRONICLE: one cheap sample per healthy watcher beat -
    how many keys/buttons are held and how far the mouse moved - kept on
    the session and written as an .inp sidecar at save. The clock is
    ACTIVE capture time (pauses excluded), so the curve lines up with the
    footage within a rotation's slack. Counts only - never WHICH keys."""
    try:
        now = time.time()
        last = getattr(session, "_inp_wall", 0.0)
        session._inp_wall = now
        if getattr(session, "suspended", False):
            return
        dt = (now - last) if (last and now - last < 5.0) else 0.0
        session._inp_t = getattr(session, "_inp_t", 0.0) + dt
        down = 0
        try:
            import ctypes
            gaks = ctypes.windll.user32.GetAsyncKeyState
            for vk in range(1, 224):
                if gaks(vk) & 0x8000:      # held NOW - never the since-bit
                    down += 1
        except Exception:
            pass
        pos = _cursor_pos()
        prev = getattr(session, "_inp_pos", None)
        px = (abs(pos[0] - prev[0]) + abs(pos[1] - prev[1]))             if (pos and prev) else 0
        session._inp_pos = pos
        buf = getattr(session, "_inp", None)
        if buf is None:
            buf = session._inp = []
        buf.append([round(session._inp_t, 1), down, min(4000, px)])
        if len(buf) > 90000:               # ~15h of beats - never unbounded
            del buf[:len(buf) - 90000]
    except Exception:
        pass


_AFK_DEAF = {"since": 0.0, "said": 0.0}


def _afk_deaf_seconds(ctl, session):
    """How long the recording has been capturing SILENCE.

    The last line of defence behind the idle clock. Whatever the pads,
    the drivers or the OS claim about whether a human is present, a
    recording whose sound has been digital silence for a long stretch
    is filming an empty chair - and that is knowable from the audio
    itself, with no guessing about input at all."""
    try:
        aud = getattr(session, "audio", None)
        if aud is None:
            return 0.0
        now = time.time()
        heard = 0.0
        with aud._ring_lock:
            for r in aud.rings:
                heard = max(heard, float(r.get("last_sound") or 0))
        if not heard:
            # nothing has EVER been heard: date the quiet from the
            # session's own start, not from the epoch
            heard = float(getattr(ctl, "rec_t0", 0) or now)
        return max(0.0, now - heard)
    except Exception:
        return 0.0


def _ring_loud(aud, within=10.0):
    """Has a game/system ring heard something LOUD within the last
    `within` seconds? Reads ring['loud_t'], a stamp a level meter may
    set; last_sound (any non-zero byte) cannot tell a loud game from
    a noise floor, so it is never used here. Rings without the stamp
    answer False - the guard then leans on the input clock alone."""
    if aud is None:
        return False
    try:
        now = time.time()
        with aud._ring_lock:
            for r in aud.rings:
                if r.get("kind") not in ("game", "system"):
                    continue
                lt = float(r.get("loud_t") or 0)
                if lt and now - lt <= within:
                    return True
    except Exception:
        pass
    return False


def _afk_track(ctl, session, current):
    """Auto-pause the recording when the user has been away for the set
    time, and resume the moment they're back - hands-off, like the rest of
    the tome. Reuses the pause/resume machinery (footage kept, same file).
    Never pauses over the window-minimise auto-pause, and a USER pause is
    never touched. Called once per watcher poll."""
    if not SETTINGS.get("afk_pause", True):
        return
    try:
        thresh = max(60, int(SETTINGS.get("afk_minutes", 4)) * 60)
    except Exception:
        thresh = 240
    idle = _afk_idle_seconds()
    try:
        # A VOICE IS A PERSON. He talks through cutscenes with his
        # friends; a mic heard in the last minute holds the countdown
        # even when both hands are off the pad.
        _mheard = _MICWATCH.get("last_sound")
        if _mheard:
            idle = min(idle, max(0.0, time.time() - float(_mheard)))
    except Exception:
        pass
    if getattr(session, "afk_paused", False):
        if idle < 5.0:
            # They're back. ONLY clear the flag - the watcher's suspended
            # branch owns the actual resume, because it re-aims the window
            # first (the window may have vanished, moved screens, or the
            # display flipped HDR while they were away). Resuming here
            # skipped those checks and could record the wrong thing.
            session.afk_paused = False
            log("AFK: you're back - resuming.")
        return
    if session.suspended:
        return                             # user/window pause: not ours
    # THE BACKSTOP: whatever the pads and drivers claim about whether a
    # human is here, a recording whose SOUND has been digital silence
    # for twice the threshold is filming an empty chair. Tonight's
    # Rocket League ran 35 minutes past -91 dB because one input signal
    # lied; no single signal gets to hold the recorder open again.
    deaf = _afk_deaf_seconds(ctl, session)
    if idle < thresh and deaf >= max(600.0, thresh * 2.0):
        log("AFK: not a sound on any track for %d min and no real "
            "input - pausing. (An input device was claiming you were "
            "here; the silence outvoted it.)" % int(deaf // 60))
        idle = deaf
    if idle >= thresh:
        session.afk_paused = True
        _loop_sound(ctl, "off")            # chime symmetry with the resume
        session.suspend()
        ctl.set_status("paused")
        log(f"AFK for {int(idle // 60)} min - recording paused (it resumes "
            "when you're back).")
        ctl.notify("Recording paused",
                   "You seem to be away - it continues when you're back.")


def _exe_has_any_window(pname):
    """Does this process own ANY top-level window - visible or not? An
    alt-tabbed exclusive-fullscreen game HIDES its window (it still exists);
    a wedged crash or exit-to-tray resident has none. The gone-pause
    backstop uses this to tell 'long alt-tab, keep waiting' apart from
    'never coming back, save the footage'. Errors report False, so footage
    is saved rather than held hostage."""
    if os.name != "nt" or not pname:
        return False
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        pids = set()
        for pr in psutil.process_iter(["pid", "name"]):
            try:
                if (pr.info.get("name") or "").lower() == pname.lower():
                    pids.add(pr.info["pid"])
            except Exception:
                pass
        if not pids:
            return False
        found = []

        @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p)
        def _enum(h, _l):
            try:
                pid = wintypes.DWORD()
                user32.GetWindowThreadProcessId(h, ctypes.byref(pid))
                if pid.value in pids:
                    if not (user32.GetWindowLongW(h, -20) & 0x00000080):
                        found.append(h)     # any non-tool top-level counts
                        return 0
            except Exception:
                pass
            return 1
        user32.EnumWindows(_enum, 0)
        return bool(found)
    except Exception:
        return False


_GPU_HITS = {}   # exe -> (streak, last-hit wallclock) for the unknown-exe path


def detect_game_smart():
    """The auto-detection heart of Lore 1.1 (see the banner comment above).
    Returns the exe name to record, or None. The user/builtin lists are
    checked by find_active_game BEFORE this runs - this function decides
    about what's on screen right now. LEARNED games are checked here (not
    by process presence): a machine-curated entry must show a real window,
    or a lingering background process would claim recordings forever."""
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        # Prune stale GPU streaks FIRST - before any early return can skip
        # it. A streak only counts as 'consecutive' if its last hit is
        # within ~two polls; anything older is a dead spike, not a game.
        try:
            poll = float(SETTINGS.get("poll_interval", 3) or 3)
        except Exception:
            poll = 3.0
        now = time.time()
        for k in list(_GPU_HITS):
            if now - _GPU_HITS[k][1] > max(8.0, poll * 2.5):
                del _GPU_HITS[k]
        ignore = load_ignore_list()
        gamedb = _windows_game_db() | _learned_games()
        watched = _watched_monitor_rect()
        cands = []                   # (exe, pid, fullscreen-ish, on_watched)

        def _consider(h):
            pid = wintypes.DWORD()
            user32.GetWindowThreadProcessId(h, ctypes.byref(pid))
            if not pid.value or pid.value == os.getpid():
                return
            try:
                if user32.GetWindow(h, 4):                    # GW_OWNER
                    return
                ex = user32.GetWindowLongW(h, -20)            # GWL_EXSTYLE
                if ex & 0x00000080:                           # TOOLWINDOW
                    return
                buf = ctypes.create_unicode_buffer(64)
                user32.GetClassNameW(h, buf, 64)
                if buf.value in ("Progman", "WorkerW", "Shell_TrayWnd",
                                 "Windows.UI.Core.CoreWindow"):
                    return
                cloaked = ctypes.c_int(0)
                if ctypes.windll.dwmapi.DwmGetWindowAttribute(
                        h, 14, ctypes.byref(cloaked),
                        ctypes.sizeof(cloaked)) == 0 and cloaked.value:
                    return
                r = wintypes.RECT()
                user32.GetWindowRect(h, ctypes.byref(r))
                w, hh = r.right - r.left, r.bottom - r.top
                if w < 480 or hh < 320:
                    return                                    # dialogs, stubs
                mrect = _window_monitor_rect(h)
                fs = False
                if mrect:
                    mw, mh = mrect[2] - mrect[0], mrect[3] - mrect[1]
                    caption = user32.GetWindowLongW(h, -16) & 0x00C00000
                    fs = (not caption and w >= mw - 2 and hh >= mh - 2)
                on_watched = (watched is None
                              or (mrect is not None and tuple(mrect) == watched))
                try:
                    pr = psutil.Process(pid.value)
                    exe = pr.name().lower()
                except psutil.Error:
                    return
                if exe in ignore:
                    return
                # a window whose exe lives in a game-store library is a
                # game until proven otherwise - browsers and editors do
                # not live in steamapps\common. The TOOLS that live in
                # there beside the games (crash reporters, prelaunchers,
                # setup stubs) are named like tools, and a mislearn is
                # permanent - so they never earn.
                gamey = False
                try:
                    pth = (pr.exe() or "").lower()
                    gamey = ("\\steamapps\\common\\" in pth
                             or "\\epic games\\" in pth
                             or "\\gog galaxy\\games\\" in pth
                             or "\\xboxgames\\" in pth)
                    if gamey and any(t in exe for t in (
                            "launcher", "crashreport", "helper",
                            "setup", "install", "updater", "unins",
                            "redist", "dxsetup", "easyanticheat",
                            "battleye", "report", "config")):
                        gamey = False
                except (psutil.Error, OSError):
                    pass
                cands.append((exe, pid.value, fs, on_watched, gamey))
            except Exception:
                pass

        @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p)
        def _enum(h, _l):
            try:
                if user32.IsWindowVisible(h) and not user32.IsIconic(h):
                    _consider(h)
            except Exception:
                pass
            return 1
        user32.EnumWindows(_enum, 0)

        # Signal 2: the OS already calls it a game -> record, windowed or
        # not, whatever monitor it's on (window scope follows it there).
        for exe, pid, fs, onw, gamey in cands:
            if exe in gamedb:
                return exe

        # Unknown exe: it must EARN recording. Fullscreen-ish on the watched
        # screen AND real 3D load across two consecutive polls -> game;
        # remember it so next time it's instant. (QUNS_RUNNING_D3D_FULL_SCREEN
        # marks exclusive fullscreen even when the window rect lies.)
        excl = None
        try:
            state = ctypes.c_int(0)
            ctypes.windll.shell32.SHQueryUserNotificationState(ctypes.byref(state))
            if state.value == 3:
                fh = user32.GetForegroundWindow()
                fp = wintypes.DWORD()
                user32.GetWindowThreadProcessId(fh, ctypes.byref(fp))
                if fp.value and fp.value != os.getpid():
                    try:
                        e = psutil.Process(fp.value).name().lower()
                        if e not in ignore:
                            excl = (e, fp.value)
                    except psutil.Error:
                        pass
        except Exception:
            pass
        # who is HE looking at - a store-library game earns windowed,
        # but only the one in front (a launcher idling in the back must
        # not learn its way into the library)
        fg_pid = 0
        try:
            _fh = user32.GetForegroundWindow()
            _fp = wintypes.DWORD()
            user32.GetWindowThreadProcessId(_fh, ctypes.byref(_fp))
            fg_pid = _fp.value or 0
        except Exception:
            pass
        hopefuls = {}
        for exe, pid, fs, onw, gamey in cands:
            if fs and onw:
                hopefuls[exe] = (pid, 12.0)
            elif gamey and onw and pid == fg_pid \
                    and exe not in hopefuls:
                # WINDOWED GAMES EXIST. The fullscreen requirement made
                # a windowed indie invisible forever (Hearth and Hamlet,
                # a whole session unrecorded). A store-library exe in
                # the FOREGROUND earns by the same two-poll GPU streak,
                # at a threshold a cozy indie on a big card can clear.
                # Never overwriting means a fullscreen sibling window
                # keeps its stricter bar.
                hopefuls[exe] = (pid, 3.0)
        if excl and excl[0] not in hopefuls:
            hopefuls[excl[0]] = (excl[1], 12.0)
        if hopefuls:
            # cache no longer than the poll gap, or two 'consecutive' polls
            # would read the SAME GPU sample and one spike could pass for two
            usage = _gpu3d_usage(max_age=min(2.0, max(0.5, poll * 0.8)))
            for exe, (pid, thresh) in hopefuls.items():
                if usage.get(pid, 0.0) >= thresh:
                    n = _GPU_HITS.get(exe, (0, 0.0))[0] + 1
                    _GPU_HITS[exe] = (n, now)
                    if n >= 2:
                        _learn_game_exe(exe)
                        _WATCH_NOTE["learn_at"] = time.time()
                        _WATCH_NOTE["learn_g"] = exe
                        return exe
                else:
                    _GPU_HITS.pop(exe, None)   # streak broke: GPU went idle
    except Exception:
        return None
    return None


def detect_fullscreen_game():
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        shell32 = ctypes.windll.shell32
        ignore = load_ignore_list()
        watched = _watched_monitor_rect()

        def _name_if_game(hwnd, require_borderless):
            """Process name if hwnd covers its monitor and isn't Lore / an ignored
            app / (when require_borderless) an ordinary titled or owned window. The
            cheap geometry + style checks run BEFORE the psutil lookup so scanning all
            windows stays light."""
            pid = wintypes.DWORD()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
            if not pid.value or pid.value == os.getpid():
                return None
            if require_borderless:
                # A borderless-fullscreen game is a caption-less, un-owned, plain
                # top-level window. Excluding WS_CAPTION skips a merely-maximized
                # browser/editor (which also fills its monitor); excluding owned
                # windows skips tool popups; excluding TRANSPARENT / TOOLWINDOW /
                # NOACTIVATE ex-styles skips click-through overlays (crosshairs,
                # OSDs); excluding the shell's Progman/WorkerW skips the desktop and
                # live-wallpaper hosts; and excluding DWM-cloaked windows skips
                # suspended UWP apps that keep an invisible full-screen frame alive.
                try:
                    if user32.GetWindowLongW(hwnd, -16) & 0x00C00000:   # GWL_STYLE & WS_CAPTION
                        return None
                    if user32.GetWindow(hwnd, 4):                       # GW_OWNER
                        return None
                    ex = user32.GetWindowLongW(hwnd, -20)               # GWL_EXSTYLE
                    if ex & (0x00000020 | 0x00000080 | 0x08000000):     # TRANSPARENT|TOOLWINDOW|NOACTIVATE
                        return None
                    buf = ctypes.create_unicode_buffer(64)
                    user32.GetClassNameW(hwnd, buf, 64)
                    if buf.value in ("Progman", "WorkerW", "Shell_TrayWnd"):
                        return None
                    cloaked = ctypes.c_int(0)
                    if ctypes.windll.dwmapi.DwmGetWindowAttribute(
                            hwnd, 14, ctypes.byref(cloaked),
                            ctypes.sizeof(cloaked)) == 0 and cloaked.value:
                        return None                                    # DWMWA_CLOAKED
                except Exception:
                    return None
            rect = wintypes.RECT()
            user32.GetWindowRect(hwnd, ctypes.byref(rect))
            mrect = _window_monitor_rect(hwnd)
            # Only the WATCHED monitor counts: a window filling any other screen is
            # ignored entirely (Lore would be capturing the watched screen anyway).
            if watched is not None:
                if mrect is None or tuple(mrect) != watched:
                    return None
            if mrect:
                mon_w, mon_h = (mrect[2] - mrect[0]), (mrect[3] - mrect[1])
            else:
                mon_w, mon_h = user32.GetSystemMetrics(0), user32.GetSystemMetrics(1)
            w, h = rect.right - rect.left, rect.bottom - rect.top
            if not (w > 0 and h > 0 and w >= mon_w - 2 and h >= mon_h - 2):
                return None
            try:
                name = psutil.Process(pid.value).name().lower()
            except psutil.Error:
                return None
            return None if name in ignore else name

        # 1) Foreground window: D3D exclusive fullscreen (a global foreground state),
        # or a borderless window covering its monitor. The user focused it, so we don't
        # require it to be caption-less here.
        hwnd = user32.GetForegroundWindow()
        if hwnd:
            fpid = wintypes.DWORD()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(fpid))
            if fpid.value and fpid.value != os.getpid():
                try:
                    fname = psutil.Process(fpid.value).name().lower()
                except psutil.Error:
                    fname = None
                if fname and fname not in ignore:
                    # D3D exclusive fullscreen - but only if it's happening on the
                    # monitor Lore actually watches/records.
                    on_watched = True
                    if watched is not None:
                        fmr = _window_monitor_rect(hwnd)
                        on_watched = (fmr is not None and tuple(fmr) == watched)
                    if on_watched:
                        state = ctypes.c_int(0)
                        try:
                            shell32.SHQueryUserNotificationState(ctypes.byref(state))
                            if state.value == 3:           # QUNS_RUNNING_D3D_FULL_SCREEN
                                return fname
                        except Exception:
                            pass
            n = _name_if_game(hwnd, require_borderless=False)
            if n:
                return n

        # 2) Nothing in the foreground qualifies: scan top-level windows so a
        # borderless game on the WATCHED monitor is still caught while the user is
        # focused elsewhere (game on the primary, clicked into Discord on screen 2).
        # _name_if_game rejects windows on other monitors, and the caption/owner/
        # ignore guards prevent grabbing a maximized browser or a media player.
        found = []

        @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p)
        def _enum(h, _lparam):
            try:
                if user32.IsWindowVisible(h) and not user32.IsIconic(h):
                    nm = _name_if_game(h, require_borderless=True)
                    if nm:
                        found.append(nm)
                        return 0                           # first match: stop enumerating
            except Exception:
                pass
            return 1
        user32.EnumWindows(_enum, 0)
        if found:
            return found[0]
    except Exception:
        return None
    return None


# The tome ships with its own knowledge of games (known_games.txt, bundled
# read-only next to the app): any of these launching starts a recording even
# WINDOWED - no fullscreen needed, nothing for the user to add by hand. The
# user's ignore list always outranks it.
_BUILTIN_GAMES = {"set": None}


def load_builtin_games():
    if _BUILTIN_GAMES["set"] is not None:
        return _BUILTIN_GAMES["set"]
    names = set()
    for base in (_here(), getattr(sys, "_MEIPASS", None)):
        if not base:
            continue
        p = os.path.join(base, "known_games.txt")
        if os.path.isfile(p):
            try:
                with open(p, encoding="utf-8") as fh:
                    for line in fh:
                        line = line.strip().lower()
                        if line and not line.startswith("#"):
                            if not line.endswith(".exe"):
                                line += ".exe"
                            names.add(line)
                log(f"Known-games list loaded: {len(names)} titles.")
            except Exception:
                pass
            break
    if not names:
        # Say so ONCE - otherwise a missing/unreadable bundle makes windowed
        # auto-detect silently inert with no clue in the log.
        log("No known_games.txt bundled; windowed games auto-record only "
            "when they're in your own games list.")
    _BUILTIN_GAMES["set"] = names
    return names


def _listed_game_by_window(listed):
    """A listed game found by its WINDOW, for when the process walk
    misses it. The walk lied before (the Bazaar's self-stop) and it
    lied again tonight: hearth and hamlet.exe ran, listed, foreground -
    and the walk-based check read blank for a whole session while a
    per-window PID lookup saw it instantly. Windows are enumerated and
    each owner is asked by PID - a different road entirely, so one
    flaky snapshot cannot blind both checks at once."""
    if os.name != "nt" or not listed:
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        hits = []

        @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p,
                            ctypes.c_void_p)
        def _enum(h, _l):
            try:
                if not user32.IsWindowVisible(h) or user32.IsIconic(h):
                    return 1
                r = wintypes.RECT()
                user32.GetWindowRect(h, ctypes.byref(r))
                if (r.right - r.left) < 480 or (r.bottom - r.top) < 320:
                    return 1               # dialogs, stubs
                pid = wintypes.DWORD()
                user32.GetWindowThreadProcessId(h, ctypes.byref(pid))
                if not pid.value or pid.value == os.getpid():
                    return 1
                try:
                    nm = psutil.Process(pid.value).name().lower()
                except psutil.Error:
                    return 1
                if nm in listed:
                    hits.append(nm)
                    return 0
            except Exception:
                pass
            return 1
        user32.EnumWindows(_enum, 0)
        return hits[0] if hits else None
    except Exception:
        return None


def find_active_game():
    # The games.txt list is ALWAYS honored - this catches windowed games like
    # Hearthstone that window detection would miss.
    listed = load_game_list()
    running = None
    if listed:
        running = running_process_names()
        hit = listed & running
        if hit:
            return sorted(hit)[0]
        # the walk can lie (short/incomplete snapshots, measured twice
        # on this machine) - a listed game with a real window on screen
        # is playing, whatever the walk says
        byw = _listed_game_by_window(listed)
        if byw:
            return byw
    if SETTINGS["detection_mode"] == "list":
        return None
    # Auto mode: the built-in known-games list catches windowed games the
    # moment they launch (user's ignore list wins over it)...
    builtin = load_builtin_games()
    if builtin:
        if running is None:
            running = running_process_names()
        hit = (builtin & running) - load_ignore_list()
        if hit:
            return sorted(hit)[0]
    # ...and real game RECOGNITION catches everything else: Windows' own
    # game database + games the GPU heuristic learned + sustained 3D GPU
    # load for the rest. Learned games are checked THERE (with a real
    # window required), never by bare process presence - a lingering
    # background process must not claim recordings. Fullscreen alone no
    # longer starts a recording (it used to record any fullscreened app).
    return detect_game_smart()


# ---------------------------------------------------------------------------
#  WASAPI audio capture (the part ffmpeg can't do)
# ---------------------------------------------------------------------------
# ONE process-wide gate for PortAudio. Its initialise/terminate touch global
# state; two threads inside them at once corrupts the heap, which is what the
# ntdll access violation on a quick stop-then-start actually was.
_PA_GATE = threading.RLock()
# how long to let in-flight callbacks finish after the streams are closed.
# Measured against the crash: without it, terminate() could free structures a
# callback was still writing into.
_PA_SETTLE = 0.25


def _pa_open(pyaudio):
    """Enter PortAudio under the gate."""
    with _PA_GATE:
        return pyaudio.PyAudio()


def _pa_close(pa):
    """Leave PortAudio under the same gate, never twice."""
    if pa is None:
        return
    with _PA_GATE:
        try:
            pa.terminate()
        except Exception:
            pass


def _prewarm_proctap():
    """Pay the one-off cost of per-app capture at boot, on a daemon
    thread, never inside start(). The first ProcessAudioCapture() in a
    process takes 3.4-3.8 s because proctap.backends.windows imports its
    converter, which imports scipy.signal (measured with -X importtime;
    scipy ships in _internal) - the native activation itself is 9 ms.
    Warmed here, the first source tap of the night opens in 1-2 ms like
    every later one. An import that fails is remembered in _PROCTAP so
    the recorder can say so once and record the Mix and Mic only, as
    before."""
    t = time.time()
    try:
        import proctap  # noqa: F401
        from proctap.backends.windows import WindowsBackend  # noqa: F401
        _PROCTAP.update(ok=True, err="", ms=int((time.time() - t) * 1000))
    except Exception as e:
        _PROCTAP.update(ok=False, err=str(e)[:160])
        log(f"Sources: per-app capture unavailable ({e}) - recording the "
            f"Mix and Mic only, as before.")


class AudioRecorder:
    """Captures system loopback (default playback device) and/or the mic to
    separate WAV files using WASAPI. No rerouting, no added latency."""

    def __init__(self, tmp_dir, tag="", game_pid=None, sources=None):
        self.tmp_dir = tmp_dir
        self.tag = tag                       # per-run suffix so pause/resume parts don't clash
        self.game_pid = game_pid             # for the EXPERIMENTAL game-audio-only tap
        # 3.31 CAPTURE BY SOURCE. The session passes what it knows - the
        # game's exe and root pid, the voice app list - and the recorder
        # owns liveness, anchors and the manifest. sources=None keeps every
        # older constructor call valid.
        self.sources = sources or {}         # {"game_exe", "game_pid", "voice_apps"}
        self.t0 = None                       # ONE anchor for every tap ring start() opens
        self.voice_wav = None
        self.game_wav = None
        self._taps = {}                      # kind -> ring (the layer rings, for the watch)
        self._said = set()                   # once-per-session log keys
        self._manifest = {"t0": None, "voice": None, "game": None,
                          "media": "none"}
        # the status rows are per capture run: a new run starts clean
        for _k in ("voice", "game"):
            _TAPWATCH[_k] = {"exe": "", "pid": None, "state": "", "since": 0.0,
                             "fixes": 0, "err": ""}
        _TAPWATCH["media"] = "none"
        self._sys_done = False
        self._pa = None
        self._streams = []
        self._threads = []
        self._stop = threading.Event()
        self.system_wav = None
        self.mic_wav = None
        # In-memory rolling buffer of the most recent audio, per stream, so the
        # "save last minute" replay can be muxed without reading the live WAVs.
        self.rings = []          # list of dicts: kind, rate, channels, chunks, bytes, max
        self._ring_lock = threading.Lock()
        # Hold enough audio for the LONGEST clip any feature can ask for - the
        # replay length, the clip-hotkey length (up to 120s) and the Discord clip
        # length - not just the default, or a long clip would get full video but
        # truncated/silent audio.
        self._replay_seconds = max(
            60,
            int(SETTINGS.get("replay_seconds", 60)),
            int(SETTINGS.get("clip_hotkey_seconds", 60)),
            int(SETTINGS.get("discord_clip_seconds", 15)),
        ) + 5

    def _open_capture(self, dev, path, label, kind):
        import pyaudiowpatch as pyaudio
        import queue
        from collections import deque
        channels = max(1, int(dev["maxInputChannels"]))
        rate = int(dev["defaultSampleRate"])
        wf = wave.open(path, "wb")
        wf.setnchannels(channels)
        wf.setsampwidth(2)  # paInt16
        wf.setframerate(rate)

        ring = {"kind": kind, "rate": rate, "channels": channels,
                "chunks": deque(), "bytes": 0,
                "max": rate * channels * 2 * self._replay_seconds,
                "t_first": None, "frames": 0, "push": None,
                "frame_bytes": channels * 2,
                # THE MIC WATCH (3.11): a virtual input can die mid-
                # session and hand back perfect silence forever, and
                # nothing used to notice.
                "dev": str(dev.get("name") or ""), "heard": None,
                "last_sound": None}
        if kind == "mic":
            _MICWATCH.update({"dev": ring["dev"], "heard": None,
                              "last_sound": None, "quiet": False,
                              "since": time.time(), "said": False})
        with self._ring_lock:
            self.rings.append(ring)

        # Bound the writer queue to ~60s of audio so a sustained disk stall can't grow
        # memory without limit (the ring is already bounded; the live-WAV queue was
        # not). Overflow happens only on a slow/full drive and is counted SEPARATELY
        # from WASAPI capture xruns, so the log stays diagnostic.
        qmax = max(256, int(rate * 60 / 4096) + 16)
        q = queue.Queue(maxsize=qmax)
        drops = {"n": 0}
        qdrops = {"n": 0}
        frame_bytes = channels * 2

        def _push(data):
            try:
                q.put_nowait(data)
            except queue.Full:
                qdrops["n"] += 1          # disk can't keep up; cap RAM (rare, catastrophic)
            with self._ring_lock:
                ring["chunks"].append(data)
                ring["bytes"] += len(data)
                while ring["bytes"] > ring["max"] and len(ring["chunks"]) > 1:
                    ring["bytes"] -= len(ring["chunks"].popleft())
        ring["push"] = _push              # signal_stop() uses it to fill the tail

        # Callback mode: WASAPI hands us audio the instant it's ready. The
        # callback only drops the bytes into a queue (fast, non-blocking); a
        # writer thread does the actual disk writing so the audio system is
        # never stalled. `status` is non-zero when WASAPI had data ready but we
        # weren't quick enough to take it - i.e. samples were LOST.
        #
        # SILENCE-GAP FILL: WASAPI *loopback* starves while the render engine is
        # idle (loading screens, menus, quiet moments) - callbacks pause or turn
        # up empty. Left as-is those wall-clock seconds are simply missing from
        # the WAV, so everything after a gap plays EARLY (and the old duration-
        # based sync then over-delayed the whole track: the '4-6 seconds late'
        # bug). Fix: count frames delivered and, on every callback, top the
        # stream up with real silence until it matches the wall clock since the
        # first sample - the WAV timeline then always equals wall time no matter
        # HOW the device starves.
        def callback(in_data, frame_count, time_info, status):
            now = time.time()
            ring["cb_at"] = now       # ALIVE - whatever it is delivering
            if kind == "mic":
                _MICWATCH["cb_at"] = now
            if ring.get("closed"):
                return (None, pyaudio.paComplete)       # tail already sealed by stop
            if status:
                drops["n"] += 1
            nfr = len(in_data) // frame_bytes
            if ring["t_first"] is None:
                if not nfr:
                    return (None, pyaudio.paContinue)   # idle ticks before any audio
                ring["t_first"] = now - nfr / rate      # sync anchor: first REAL sample
                ring["frames"] = 0
            target = int((now - ring["t_first"]) * rate)
            miss = target - ring["frames"] - nfr
            if miss > rate * 0.25:                      # engine starved: true silence
                # fill the WHOLE gap (bounded pieces) - filling only 30s per
                # callback scattered post-gap audio as blips every 30s when
                # a source stayed silent for minutes
                miss = int(min(miss, rate * 14400))
                while miss > 0:
                    n = int(min(miss, rate * 30))
                    _push(b"\x00" * (n * frame_bytes))
                    ring["frames"] += n
                    miss -= n
            if nfr:
                # IS THERE ANYTHING THERE AT ALL? Exact digital silence
                # strips to nothing; a live microphone never does, not
                # even in a quiet room.
                if in_data.strip(b"\x00"):
                    # EVERY ring stamps its clock. When only the mic
                    # did, a noise-gated mic made "deaf" measure the
                    # session's AGE - and the backstop then paused a
                    # recording he was actively playing, every few
                    # polls, for the rest of the night (review 318,
                    # critical). A booming game is not deafness.
                    ring["last_sound"] = now
                if kind == "mic" and in_data.strip(b"\x00"):
                    if ring["heard"] is None:
                        ring["heard"] = now
                        _MICWATCH["heard"] = now
                    _MICWATCH["last_sound"] = now
                    if _MICWATCH.get("quiet"):
                        _MICWATCH["quiet"] = False
                        _MICWATCH["said"] = False
                        log("Your microphone is back ("
                            + ring["dev"] + ").")
                _push(in_data)
                ring["frames"] += nfr
            return (None, pyaudio.paContinue)

        # A bigger buffer means the callback fires less often, which leaves far
        # more headroom against scheduling jitter while the GPU is busy encoding.
        # That headroom is what keeps the high-rate Sonar stream (8ch @ 96kHz)
        # from dropping samples and sounding robotic.
        def _open_stream():
            return self._pa.open(
                format=pyaudio.paInt16, channels=channels, rate=rate,
                input=True, input_device_index=dev["index"],
                frames_per_buffer=4096, stream_callback=callback,
            )

        stream = _open_stream()
        self._streams.append(stream)
        # HOW TO COME BACK. The same callback, the same ring, the same
        # queue and the same WAV - only the endpoint is replaced. The
        # callback's wall-clock gap-fill then writes real silence for
        # the dead stretch, so the timeline never shifts.
        ring["cb_at"] = time.time()
        ring["reopen"] = _open_stream
        ring["stream"] = stream

        def writer():
            try:
                while not self._stop.is_set() or not q.empty():
                    try:
                        wf.writeframes(q.get(timeout=0.3))
                    except queue.Empty:
                        continue
            except Exception as e:
                # one write error used to kill this thread in silence while
                # the video kept encoding - a 3-hour session with audio
                # ending at minute 40 and nothing anywhere saying why
                log(f"Audio writer DIED mid-recording: {e} - this "
                    f"recording's sound ends early.")
            finally:
                try:
                    wf.close()
                except Exception:
                    pass
                if drops["n"]:
                    log(f"Audio WARNING: '{label}' had {drops['n']} capture xrun(s) "
                        f"- if it sounds choppy, this is why.")
                if qdrops["n"]:
                    log(f"Audio WARNING: '{label}' dropped {qdrops['n']} buffer(s) to a "
                        f"disk backlog (slow/full drive); memory was capped to protect the app.")

        t = threading.Thread(target=writer, daemon=True)
        t.lore_kind = "the %s writer" % kind
        t.start()
        self._threads.append(t)
        log(f"Audio: capturing {label} -> {channels}ch @ {rate}Hz")

    def _open_process_tap(self, pid, path, kind="system", label="game",
                          exe=None, anchor=None, wait=2.5):
        """A WASAPI process-loopback tap (proctap) on one process TREE,
        written like every other stream the recorder keeps: int16 WAV,
        replay ring, wall-clock silence-fill (process loopback delivers
        NOTHING while the target is silent - unfilled, the track would
        drift early, the same starvation bug the loopback path solves).

        TWO CALLERS, ONE CONTRACT. The legacy game_audio_only path calls
        it as _open_process_tap(pid, path): kind 'system', synchronous
        (`wait` seconds for the tap to prove itself), True/False back,
        and the caller falls back to the device loopback on False. The
        3.31 SOURCES layers call it with kind 'voice'/'game', an `exe`
        (the liveness gate), an `anchor` (the run's shared t0, so the
        layer's WAV starts at the same wall instant as the others) and
        wait=0: the tap commits ITSELF from its own thread and the ring
        comes back at once in state 'opening' - start() never waits on
        a layer, so the mic and the Mix keep their 'open in well under
        a second' promise.

        THE LIVENESS GATE comes before construction: a tap on a DEAD pid
        constructs fine, reports process-specific and stays silent for
        ever (measured), so the honesty check cannot catch a stale pid -
        only a pid that is alive and wears the expected exe is tapped.
        THE HONESTY CHECK stays: Windows silently hands back a
        SYSTEM-WIDE loopback when process activation fails, and
        recording everything under a layer's name is the opposite of
        the feature. The sync wait is 8 s on the legacy path now (was
        2.5): native activation can take up to 10 s, and the first tap
        of a lore.exe lifetime pays ~3.4 s importing scipy inside
        proctap's converter unless _prewarm_proctap got there first."""
        try:
            from proctap import ProcessAudioCapture  # noqa: F401
            import numpy as np
            from collections import deque
            import queue
        except Exception as e:
            if kind == "system":
                log(f"Game-audio tap unavailable ({e}); using system audio.")
            else:
                _PROCTAP.update(ok=False, err=str(e)[:160])
                if "proctap" not in self._said:
                    self._said.add("proctap")
                    log(f"Sources: per-app capture unavailable ({e}) - "
                        f"recording the Mix and Mic only, as before.")
            return False
        if exe and not _pid_wears(pid, exe):
            # the reason rides the status row: the gao fallback line reads
            # _TAPWATCH['game']['err'], and a bare gate left it reading
            # 'failed to start ()'. 'is gone' only when the pid is dead;
            # a pid that is alive under another name says so.
            alive = _pid_alive(pid)
            why = (f"pid {pid} does not wear {exe}" if alive
                   else f"pid {pid} is gone")
            if isinstance(_TAPWATCH.get(kind), dict):
                _TAPWATCH[kind].update(exe=exe or "", pid=pid, err=why)
            key = ("gone_pid", kind, pid)
            if key not in self._said:
                self._said.add(key)
                if alive:
                    log(f"Sources: pid {pid} is not {exe} - looking for it again.")
                else:
                    log(f"Sources: {exe} pid {pid} is gone - looking for it again.")
            return False
        rate, channels = 48000, 2
        frame_bytes = channels * 2
        wf = wave.open(path, "wb")
        wf.setnchannels(channels)
        wf.setsampwidth(2)
        wf.setframerate(rate)
        ring = {"kind": kind, "rate": rate, "channels": channels,
                "chunks": deque(), "bytes": 0,
                "max": rate * channels * 2 * self._replay_seconds,
                "t_first": None, "frames": 0, "push": None,
                "frame_bytes": frame_bytes,
                # the keys _open_capture gives its rings, so the deaf
                # backstop and the watches read every ring alike
                "dev": exe or "", "heard": None, "last_sound": None,
                "cb_at": time.time(),
                # the tap's own bookkeeping (see _tap_watch / _tap_reopen)
                "pid": pid, "exe": exe, "state": "opening", "live_at": None,
                "reopens": 0, "stop_evt": threading.Event(), "path": path,
                "label": label, "is_tap": True, "gen": 0, "err": None,
                "gap_s": 0.0, "down_at": None, "wf": wf,
                # the stall cadence (_tap_watch C): when the last stall
                # reopen was, and whether the kind is on the 60 s cadence
                "stall_at": None, "stall_backoff": False}
        if anchor is not None:
            # THE SHARED ANCHOR: a layer start() opens counts its frames
            # from the run's t0, so however late the tap activates its
            # first chunk is preceded by real silence up to its own wall
            # moment and the layer WAVs line up sample for sample. A tap
            # opened later by the watch keeps first-sample anchoring
            # (anchor None) - no zero burst for the hours before it.
            ring["t_first"] = anchor
            ring["frames"] = 0
        with self._ring_lock:
            self.rings.append(ring)
        if kind != "system":
            self._taps[kind] = ring
            _TAPWATCH[kind].update(exe=exe or "", pid=pid, state="opening",
                                   since=time.time(), err="")
        # ~60 s of 480-frame buffers, bounded like _open_capture's queue,
        # overflow counted and reported at writer exit
        qmax = max(256, int(rate * 60 / 480) + 16)
        q = queue.Queue(maxsize=qmax)
        qdrops = {"n": 0}
        ring["qdrops"] = qdrops

        def _push(data):
            try:
                q.put_nowait(data)
            except queue.Full:
                qdrops["n"] += 1
            with self._ring_lock:
                ring["chunks"].append(data)
                ring["bytes"] += len(data)
                while ring["bytes"] > ring["max"] and len(ring["chunks"]) > 1:
                    ring["bytes"] -= len(ring["chunks"].popleft())
        ring["push"] = _push

        def on_pcm(pcm, gen):
            # float32 [-1,1] -> int16, then the same clock-fill discipline
            # as the WASAPI callback: the WAV timeline always equals wall
            # time, however the tap starves. `gen` is the tap's generation:
            # a tap retired by a reopen may deliver a few late chunks, and
            # counting them would push the clock ahead of the wall for the
            # rest of the run.
            now = time.time()
            if ring.get("closed") or ring.get("gen") != gen:
                return
            ring["cb_at"] = now       # ALIVE - whatever it is delivering
            fl = np.frombuffer(pcm, dtype=np.float32)
            data = (np.clip(fl, -1.0, 1.0) * 32767.0).astype(np.int16).tobytes()
            nfr = len(data) // frame_bytes
            if ring["t_first"] is None:
                if not nfr:
                    return
                ring["t_first"] = now - nfr / rate
                ring["frames"] = 0
            target = int((now - ring["t_first"]) * rate)
            miss = target - ring["frames"] - nfr
            if miss > rate * 0.25:
                # whole-gap fill: a game can be silent for MINUTES (menus,
                # cutscenes) and the resumed audio must land exactly at its
                # wall-clock spot, not 30s at a time
                miss = int(min(miss, rate * 14400))
                while miss > 0:
                    n = int(min(miss, rate * 30))
                    _push(b"\x00" * (n * frame_bytes))
                    ring["frames"] += n
                    miss -= n
            if nfr:
                if data.strip(b"\x00"):
                    # parity with the loopback: a booming game or a
                    # talking friend is not deafness (_afk_deaf_seconds)
                    ring["last_sound"] = now
                _push(data)
                ring["frames"] += nfr
        ring["on_pcm"] = on_pcm

        state = {"live": False, "err": None}

        def _done(live, err):
            if live:
                state["live"] = True
            else:
                state["err"] = err
            if wait == 0:
                # async: the tap thread commits (or retires) itself
                if live:
                    self._tap_commit(ring, wf, q, path, label)
                else:
                    self._tap_failed(ring, wf, path, err)

        self._spawn_tap(ring, pid, _done)
        if wait == 0:
            return ring
        # commit only once start() ran and the tap proved process-specific
        for _ in range(int(wait * 10)):
            if state["err"] is not None or state["live"]:
                break
            time.sleep(0.1)
        if state["err"] is not None or not state["live"]:
            self._tap_failed(ring, wf, path, state["err"])
            return False
        return bool(self._tap_commit(ring, wf, q, path, label))

    def _spawn_tap(self, ring, pid, done):
        """One tap on its own clean thread (it initialises COM itself and
        must not inherit pywebview's apartment). `done(live, err)` is
        called exactly once, from that thread, when the tap has proved
        itself or failed; the thread then holds the tap open until the
        run ends or the ring's stop_evt retires it (a reopen puts a new
        tap on the same ring, see _tap_reopen)."""
        stop_evt = ring["stop_evt"]
        gen = ring.get("gen", 0)
        on_pcm = ring["on_pcm"]

        def tap_thread():
            tap = None
            try:
                from proctap import ProcessAudioCapture
                tap = ProcessAudioCapture(
                    int(pid), on_data=lambda pcm, *_a: on_pcm(pcm, gen))
                tap.start()
                # THE HONESTY CHECK: proctap's native layer silently falls
                # back to SYSTEM-WIDE loopback when process activation fails
                # (protected process) - construction still succeeds. A
                # non-specific tap is treated as a failure.
                try:
                    native = getattr(getattr(tap, "_backend", None),
                                     "_native", None)
                    if native is not None and hasattr(native,
                                                      "is_process_specific"):
                        if not native.is_process_specific():
                            raise RuntimeError(
                                "tap fell back to system-wide capture")
                except RuntimeError:
                    raise
                except Exception:
                    pass          # introspection unavailable: trust the tap
            except Exception as e:
                try:
                    if tap is not None:
                        tap.stop()
                        tap.close()
                except Exception:
                    pass
                done(False, e)
                return
            done(True, None)
            while not self._stop.is_set() and not stop_evt.is_set():
                self._stop.wait(0.5)
            try:
                tap.stop()
                tap.close()
            except Exception:
                pass
        tt = threading.Thread(target=tap_thread, daemon=True)
        tt.lore_kind = "the %s tap" % ring["kind"]
        tt.start()
        with self._ring_lock:
            self._threads.append(tt)

    def _tap_commit(self, ring, wf, q, path, label):
        """The success half of a tap: the writer thread starts ONLY now
        (so the WAV handle is never held by a writer when the file must
        be deleted), the ring turns 'live', the status row and the
        manifest learn it. Called from the tap thread (async) or the
        wait loop (sync)."""
        import queue
        if self._stop.is_set() or ring["stop_evt"].is_set() or ring.get("closed"):
            if ring["kind"] == "system":
                return self._tap_failed(ring, wf, path, "the run ended first")
            # a layer that proves itself after signal_stop has nothing to
            # say: finalize drops every never-live ring by name and says
            # 'never came up in time' once - a line here named the same
            # tap twice. Seal it so a late chunk lands nowhere; finalize
            # closes the WAV, removes it and marks the ring 'failed'.
            ring["closed"] = True
            try:
                ring["stop_evt"].set()
            except Exception:
                pass
            return False
        qdrops = ring.get("qdrops") or {"n": 0}

        def writer():
            try:
                while not self._stop.is_set() or not q.empty():
                    try:
                        wf.writeframes(q.get(timeout=0.3))
                    except queue.Empty:
                        continue
            except Exception as e:
                # one write error used to kill this thread in silence while
                # the video kept encoding - a 3-hour session with audio
                # ending at minute 40 and nothing anywhere saying why
                log(f"Audio writer DIED mid-recording ({label}): {e} - this "
                    f"recording's sound ends early.")
            finally:
                try:
                    wf.close()
                except Exception:
                    pass
                if qdrops["n"]:
                    log(f"Audio WARNING: '{label}' dropped {qdrops['n']} buffer(s) to a "
                        f"disk backlog (slow/full drive); memory was capped to protect the app.")
        t = threading.Thread(target=writer, daemon=True)
        t.lore_kind = "the %s tap's writer" % ring["kind"]
        t.start()
        with self._ring_lock:
            self._threads.append(t)
        now = time.time()
        ring["state"] = "live"
        ring["live_at"] = now
        # the stall clock starts HERE, not at construction: native
        # activation can take seconds, and a tap seen 8 s after its
        # ring was built had not had 8 s to deliver anything
        ring["cb_at"] = now
        kind = ring["kind"]
        if kind == "system":
            log(f"Audio: capturing the GAME's own sound only (pid {ring['pid']}).")
            return True
        self._taps[kind] = ring
        _TAPWATCH[kind].update(exe=ring.get("exe") or "", pid=ring["pid"],
                               state="live", since=now, specific=True, err="")
        self._manifest[kind] = {"exe": ring.get("exe"), "pid": ring["pid"],
                                "specific": True, "opened": now,
                                "anchor": ring.get("t_first"),
                                "reopens": ring.get("reopens", 0)}
        log(f"Sources: capturing the {label} layer from {ring.get('exe')} "
            f"(pid {ring['pid']}) -> 2ch @ 48000Hz")
        return True

    def _tap_failed(self, ring, wf, path, why):
        """The failure half: seal the ring, drop it, close and delete the
        WAV, forget the layer, say why - once per (kind, reason). The
        ring's state flips to 'failed' LAST: it is the flag the watch and
        the tests poll, and it must mean the file is gone."""
        ring["closed"] = True      # a late-finishing tap must push nothing
        ring["err"] = None if why is None else str(why)[:160]
        try:
            ring["stop_evt"].set()
        except Exception:
            pass
        with self._ring_lock:
            try:
                self.rings.remove(ring)
            except ValueError:
                pass
        try:
            wf.close()
        except Exception:
            pass
        try:
            os.remove(path)
        except Exception:
            pass
        kind, label = ring["kind"], ring.get("label") or "game"
        if kind == "system":
            log(f"Game-audio tap failed to start ({why}); using system audio.")
            ring["state"] = "failed"
            return False
        self._taps.pop(kind, None)
        if kind == "voice":
            self.voice_wav = None
        if kind == "game":
            self.game_wav = None
        _TAPWATCH[kind].update(state="failed", err=ring["err"] or "")
        honest = isinstance(why, RuntimeError) and "system-wide" in str(why)
        key = ("failed", kind, "wide" if honest else str(why)[:60])
        if key not in self._said:
            self._said.add(key)
            if honest:
                log(f"Sources: Windows would only give a system-wide tap for "
                    f"{ring.get('exe')} (pid {ring['pid']}) - the {label} layer "
                    f"is off for this run; the Mix is unaffected.")
            else:
                log(f"Sources: the {label} tap could not start ({why}) - the "
                    f"{label} layer is off for this run; the Mix is unaffected.")
        ring["state"] = "failed"
        return False

    def start(self):
        import pyaudiowpatch as pyaudio
        # ONE ANCHOR for every layer this run opens (see _open_process_tap)
        self.t0 = time.time()
        self._manifest["t0"] = self.t0
        self._pa = _pa_open(pyaudio)
        wasapi = self._pa.get_host_api_info_by_type(pyaudio.paWASAPI)
        by_src = bool(SETTINGS.get("capture_by_source"))
        gao = bool(SETTINGS.get("game_audio_only"))

        # the legacy game-audio-only tap (capture_by_source OFF): the game's
        # own tree stands in for the device loopback, ring kind 'system'
        if SETTINGS["capture_system"] and gao and not by_src \
                and getattr(self, "game_pid", None):
            self.system_wav = os.path.join(
                self.tmp_dir, f"system{('_' + self.tag) if self.tag else ''}.wav")
            if self._open_process_tap(self.game_pid, self.system_wav, wait=8.0):
                self._sys_done = True
            else:
                self.system_wav = None      # fall through to normal loopback

        # the device loopback - the Mix source. Under 'Keep only the game' +
        # by-source it is not opened at all: the game tap IS the Mix's system
        # half (see Session._stop_run), and if that tap fails _open_sources
        # opens the loopback after all.
        if SETTINGS["capture_system"] and not getattr(self, "_sys_done", False) \
                and not (by_src and gao and self.sources.get("game_pid")):
            self._open_loopback(wasapi)

        if SETTINGS["capture_mic"]:
            mic = self._resolve_mic(wasapi)
            if mic is not None:
                self.mic_wav = os.path.join(
                    self.tmp_dir, f"mic{('_' + self.tag) if self.tag else ''}.wav")
                self._open_capture(mic, self.mic_wav, f"mic ({mic['name']})", "mic")
            else:
                log("Audio: no microphone found yet; LORE will keep "
                    "looking while this records.")
        # THE LAYERS COME LAST, so the instant devices are never behind a
        # tap; they ride behind on the shared t0.
        if SETTINGS["capture_system"] and by_src:
            self._open_sources(wasapi)
        if SETTINGS.get("capture_mic", True):
            # the watch runs for the life of the session
            _t = threading.Thread(target=self._mic_watch, daemon=True)
            _t.lore_kind = "the mic watch"
            _t.start()
            self._threads.append(_t)

    def _open_loopback(self, wasapi):
        """The device loopback (the Mix source): the user's explicit pick
        from Settings > Audio, or the Windows default. A pure move out of
        start() so the by-source path can open it late (after a failed
        game tap under 'Keep only the game')."""
        # Which playback device to listen to: the user's explicit pick from
        # Settings > Audio, or the Windows default. (It was always the default
        # before, which looked random to anyone who switches outputs.)
        out = self._pa.get_device_info_by_index(wasapi["defaultOutputDevice"])
        want = str(SETTINGS.get("audio_output_device", "") or "").strip().lower()
        if want:
            for i in range(self._pa.get_device_count()):
                d0 = self._pa.get_device_info_by_index(i)
                if (d0.get("maxOutputChannels", 0) > 0
                        and not d0.get("isLoopbackDevice")
                        and want in str(d0.get("name", "")).lower()):
                    out = d0
                    break
            else:
                log(f"Audio: chosen output '{want}' not found; using the default.")
        loop = None
        for d in self._pa.get_loopback_device_info_generator():
            if out["name"] in d["name"]:
                loop = d
                break
        if loop is None:  # fall back to first loopback device
            gen = self._pa.get_loopback_device_info_generator()
            loop = next(gen, None)
        if loop is not None:
            self.system_wav = os.path.join(
                self.tmp_dir, f"system{('_' + self.tag) if self.tag else ''}.wav")
            self._open_capture(loop, self.system_wav, f"system ({out['name']})", "system")
            self._sys_done = True
            self._manifest["media"] = "loopback"
            _TAPWATCH["media"] = "loopback"
        else:
            log("Audio: no WASAPI loopback device found; system sound skipped.")

    def _open_sources(self, wasapi):
        """start()'s step 4 (3.31): the GAME tap on the game's root pid and
        the VOICE tap on the voice app's root, both async on the shared
        t0, then the watch that keeps them on their feet. Every failure
        here drops a layer and nothing else - the Mix and the mic are
        already open."""
        if _PROCTAP.get("err"):
            if "proctap" not in self._said:
                self._said.add("proctap")
                log(f"Sources: per-app capture unavailable ({_PROCTAP['err']}) "
                    f"- recording the Mix and Mic only, as before.")
            return
        sfx = ("_" + self.tag) if self.tag else ""
        gao = bool(SETTINGS.get("game_audio_only"))
        gexe = self.sources.get("game_exe")
        gpid = self.sources.get("game_pid")
        if gpid:
            self.game_wav = os.path.join(self.tmp_dir, f"game{sfx}.wav")
            # under 'Keep only the game' the loopback was NOT opened, so this
            # tap must be known good (or not) before start() returns - the
            # one place a layer is waited on
            r = self._open_process_tap(gpid, self.game_wav, kind="game",
                                       label="game", exe=gexe, anchor=self.t0,
                                       wait=(8.0 if gao else 0))
            if r is False:
                self.game_wav = None
                if gao and not getattr(self, "_sys_done", False):
                    log(f"Game-audio tap failed to start "
                        f"({_TAPWATCH['game'].get('err')}); using system audio.")
                    try:
                        self._open_loopback(wasapi)
                    except Exception as e:
                        log(f"Audio: the loopback could not be opened either ({e}).")
            elif gao and "gao_media" not in self._said:
                self._said.add("gao_media")
                log("Sources: 'Keep only the game' is on, so there is no device "
                    "loopback to find a video in - the media layer is off for "
                    "this recording.")
        elif gexe:
            if "game_wait" not in self._said:
                self._said.add("game_wait")
                log(f"Sources: no live process for {gexe} yet - the game layer "
                    f"will start when it appears.")
        elif "game_desk" not in self._said:
            self._said.add("game_desk")
            log("Sources: no game process to follow for a desktop recording - "
                "the game layer is off.")
        apps = list(self.sources.get("voice_apps") or SETTINGS.get("voice_apps") or [])
        vexe, vpid = _voice_target(apps)
        if vpid:
            self.voice_wav = os.path.join(self.tmp_dir, f"voice{sfx}.wav")
            if self._open_process_tap(vpid, self.voice_wav, kind="voice",
                                      label="voice", exe=vexe, anchor=self.t0,
                                      wait=0) is False:
                self.voice_wav = None
        elif "voice_off" not in self._said:
            self._said.add("voice_off")
            who = ("Discord" if (not apps or str(apps[0]).startswith("discord"))
                   else str(apps[0]))
            log(f"Sources: {who} is not running - the voice layer is your "
                f"microphone alone until it starts.")
        _t = threading.Thread(target=self._tap_watch, daemon=True)
        _t.lore_kind = "the tap watch"
        _t.start()
        self._threads.append(_t)

    def _resolve_mic(self, wasapi):
        want = SETTINGS["mic_name_contains"].strip().lower()
        if want:
            for i in range(self._pa.get_device_count()):
                d = self._pa.get_device_info_by_index(i)
                if d["maxInputChannels"] > 0 and not d.get("isLoopbackDevice") \
                        and want in d["name"].lower():
                    return d
        try:
            return self._pa.get_device_info_by_index(wasapi["defaultInputDevice"])
        except Exception:
            return None

    def first_sample_wallclock(self, kind):
        """Wall-clock time of this stream's first captured sample ('system',
        'mic', and since 3.31 'voice'/'game'), or None. The A/V sync anchors
        on this instead of guessing from durations; a layer start() opened
        answers the run's shared t0."""
        with self._ring_lock:
            for r in self.rings:
                if r["kind"] == kind:
                    return r["t_first"]
        return None

    def sources_manifest(self):
        """What this run captured by source, for Session.runs and the
        .src.json sidecar: {t0, voice: {exe, pid, specific, opened, anchor,
        reopens, state, gap_s} | None, game: {...} | None, media:
        'loopback' | 'none'}. gap_s is the seconds a layer spent not live
        after it first came up (its app dead, or a reopen failing) - the
        reader stands media detection down when the voice layer was lost
        for long, because friends heard only in the Mix would otherwise be
        filed as a video."""
        m = dict(self._manifest)
        m["t0"] = self.t0
        now = time.time()
        for kind, ring in list(self._taps.items()):
            gap = float(ring.get("gap_s") or 0.0)
            if ring.get("down_at"):
                gap += max(0.0, now - float(ring["down_at"]))
            m[kind] = {"exe": ring.get("exe"), "pid": ring.get("pid"),
                       "specific": True, "opened": ring.get("live_at"),
                       "anchor": ring.get("t_first"),
                       "reopens": int(ring.get("reopens") or 0),
                       "state": ring.get("state"), "gap_s": round(gap, 1)}
        with self._ring_lock:
            loop = any(r.get("kind") == "system" and not r.get("is_tap")
                       for r in self.rings)
        m["media"] = "loopback" if loop else "none"
        return m

    def signal_stop(self):
        """Tell capture threads to stop now (non-blocking), so audio and video
        stop at the same instant. First seals each ring (so a racing callback
        can't double-fill), then tops every stream up with silence to the current
        wall clock in small chunks - a recording that ENDS during a quiet stretch
        would otherwise have its last starved seconds missing from the WAV. The
        tail fill is capped at 2 minutes: beyond that the missing part is
        trailing silence anyway, and a multi-hour zero-buffer would spike RAM."""
        now = time.time()
        for r in list(self.rings):
            try:
                r["closed"] = True
                if r["t_first"] is not None and r["push"]:
                    miss = int((now - r["t_first"]) * r["rate"]) - r["frames"]
                    miss = min(miss, r["rate"] * 120)
                    while miss > 0:                              # 5s pieces
                        n = min(miss, r["rate"] * 5)
                        r["push"](b"\x00" * (n * r["frame_bytes"]))
                        r["frames"] += n
                        miss -= n
            except Exception:
                pass
        self._stop.set()

    def finalize(self):
        """Stop capture, then let writer threads flush the rest to disk."""
        if getattr(self, "_finalized", False):
            return                       # twice through here is a double-free
        self._finalized = True
        # Stop the callback streams first so they stop filling the queues...
        for s in self._streams:
            try:
                s.stop_stream()
            except Exception:
                pass
        # ...let any callback ALREADY RUNNING finish before the close. Closing
        # underneath a live callback is half of the crash.
        try:
            time.sleep(_PA_SETTLE)
        except Exception:
            pass
        for s in self._streams:
            try:
                s.close()
            except Exception:
                pass
        self._streams = []
        # every tap thread returns promptly, a still-opening one included
        # (its commit then routes to _tap_failed: no writer, no file)
        for r in list(self._taps.values()):
            try:
                r["stop_evt"].set()
            except Exception:
                pass
        # ...then let the writer threads drain whatever's left and close files.
        with self._ring_lock:
            threads = list(self._threads)
        for t in threads:
            t.join(timeout=10)
            if t.is_alive():
                # by name: 'a writer thread' could be any of seven
                what = getattr(t, "lore_kind", None) or "a writer"
                log(f"Audio: {what} thread is still flushing after 10s (slow/full "
                    "disk); its track may be slightly truncated.")
        # A LAYER THAT NEVER CAME UP leaves a header-only WAV, and _stop_run
        # would hand that to the mux as a track. Drop it here, by name.
        for kind, r in list(self._taps.items()):
            if r.get("live_at") is not None:
                continue
            r["closed"] = True
            with self._ring_lock:
                try:
                    self.rings.remove(r)
                except ValueError:
                    pass
            try:
                r["wf"].close()
            except Exception:
                pass
            try:
                os.remove(r["path"])
            except Exception:
                pass
            r["state"] = "failed"        # LAST: it means the file is gone
            self._taps.pop(kind, None)
            if kind == "voice":
                self.voice_wav = None
            if kind == "game":
                self.game_wav = None
            _TAPWATCH[kind].update(state="failed", err="never came up in time")
            label = r.get("label") or kind
            if ("late", kind) not in self._said:
                self._said.add(("late", kind))
                log(f"Sources: the {label} tap never came up in time - the "
                    f"{label} layer is off for this run.")
        # and terminate under the gate, so a recording starting right now
        # cannot be inside PyAudio() while this one is inside terminate()
        _pa_close(self._pa)
        self._pa = None

    def _mic_ring(self):
        with self._ring_lock:
            for r in self.rings:
                if r.get("kind") == "mic":
                    return r
        return None

    def _mic_reopen(self, ring, why):
        """Put a dead microphone back on its feet, in place."""
        try:
            old = ring.get("stream")
            if old is not None:
                try:
                    old.stop_stream()
                except Exception:
                    pass
                try:
                    old.close()
                except Exception:
                    pass
                try:
                    self._streams.remove(old)
                except ValueError:
                    pass
            ring["stream"] = None
            fresh = ring["reopen"]()
            ring["stream"] = fresh
            self._streams.append(fresh)
            ring["cb_at"] = time.time()
            _MICWATCH["cb_at"] = ring["cb_at"]
            _MICWATCH["fixes"] = int(_MICWATCH.get("fixes") or 0) + 1
            _MICWATCH["state"] = "reconnected"
            log("Microphone reconnected (" + str(ring.get("dev") or "")
                + ") - " + why + ". The gap is filled with silence so "
                "the sound stays in step with the picture.")
            return True
        except Exception as e:
            _MICWATCH["state"] = "reconnecting"
            log("Microphone could not be reopened yet ("
                + str(e)[:100] + ") - trying again shortly.")
            return False

    def _tap_reopen(self, ring, pid, why, exe=None):
        """Put a layer back on its feet IN PLACE, like _mic_reopen: same
        ring, same queue, same WAV - only the tap is replaced. The ring's
        clock keeps running, so the next chunk's wall-clock fill writes
        real silence for the dead stretch and the timeline never shifts.
        A failed reopen leaves the ring 'dead' - the watch keeps trying
        on the same or a new root - because a Discord that keeps running
        while its tap is lost must not have its friends filed as a video
        for the rest of the night."""
        kind, label = ring["kind"], ring.get("label") or ring["kind"]
        if exe:
            ring["exe"] = exe
        if not _pid_wears(pid, ring.get("exe")):
            return False
        old = ring.get("pid")
        try:
            ring["stop_evt"].set()             # retire the old tap thread
        except Exception:
            pass
        ring["stop_evt"] = threading.Event()
        ring["gen"] = int(ring.get("gen") or 0) + 1
        ring["pid"] = pid
        ring["reopens"] = int(ring.get("reopens") or 0) + 1
        ring["state"] = "opening"
        res = {"done": False, "live": False, "err": None}
        ev = threading.Event()

        def _done(live, err):
            if res["done"]:
                return                         # a late answer to a given-up try
            res.update(done=True, live=live, err=err)
            ev.set()
        self._spawn_tap(ring, pid, _done)
        ev.wait(10.0)
        now = time.time()
        if not res["live"]:
            res["done"] = True
            try:
                ring["stop_evt"].set()         # a late success closes itself
            except Exception:
                pass
            err = res["err"] if res["err"] is not None else "it did not come up in time"
            ring["state"] = "dead"
            ring["err"] = str(err)[:160]
            ring["down_at"] = ring.get("down_at") or now
            _TAPWATCH[kind].update(pid=pid, state="dead", err=ring["err"])
            if ("reopen_fail", kind) not in self._said:
                self._said.add(("reopen_fail", kind))
                log(f"Sources: the {label} tap could not be reopened yet "
                    f"({str(err)[:100]}) - trying again shortly.")
            return False
        ring["state"] = "live"
        ring["cb_at"] = now
        ring["err"] = None
        if ring.get("down_at"):
            ring["gap_s"] = float(ring.get("gap_s") or 0.0) + max(
                0.0, now - float(ring["down_at"]))
            ring["down_at"] = None
        self._said.discard(("reopen_fail", kind))
        _TAPWATCH[kind].update(exe=ring.get("exe") or "", pid=pid,
                               state="reconnected", err="",
                               fixes=int(_TAPWATCH[kind].get("fixes") or 0) + 1)
        if isinstance(self._manifest.get(kind), dict):
            self._manifest[kind]["reopens"] = ring["reopens"]
            self._manifest[kind]["pid"] = pid
        if pid != old:
            log(f"Sources: {ring.get('exe')} restarted (pid {old} -> {pid}) - "
                f"the {label} layer follows the new one; the gap is filled "
                f"with silence so the sound stays in step with the picture.")
        else:
            log(f"Sources: the {label} tap is back on {ring.get('exe')} "
                f"(pid {pid}) - {why}; the gap is filled with silence so the "
                f"sound stays in step with the picture.")
        return True

    def _mic_watch(self):
        """A virtual microphone can stop delivering while its handle
        stays open, and it can be missing at the moment a recording
        starts. Neither is a reason to lose his voice for a whole
        night, so both are repaired here while the film rolls."""
        import pyaudiowpatch as pyaudio
        last_try = 0.0
        while not self._stop.wait(4.0):
            if not SETTINGS.get("capture_mic", True):
                continue
            now = time.time()
            ring = self._mic_ring()
            if ring is None:
                # B: it was never opened. Keep asking - Sonar may still
                # be starting up, or a game had the device first.
                if now - last_try < 20:
                    continue
                last_try = now
                try:
                    wasapi = self._pa.get_host_api_info_by_type(
                        pyaudio.paWASAPI)
                    mic = self._resolve_mic(wasapi)
                    if mic is not None:
                        self.mic_wav = os.path.join(
                            self.tmp_dir,
                            "mic%s.wav" % (("_" + self.tag)
                                           if self.tag else ""))
                        self._open_capture(mic, self.mic_wav,
                                           "mic (%s)" % mic["name"],
                                           "mic")
                        log("Microphone found on a second look ("
                            + str(mic["name"]) + ") - it is being "
                            "recorded from here on.")
                except Exception:
                    pass
                continue
            cb = ring.get("cb_at") or 0
            if cb and now - cb > 8:
                # A: the endpoint stopped delivering. This is the one
                # that cost him a night.
                _MICWATCH["state"] = "reconnecting"
                self._mic_reopen(ring, "it stopped sending sound")
                continue
            # CONTENT silence is treated gently: his noise gate is
            # MEANT to emit digital silence when he is not talking.
            snd = ring.get("last_sound")
            base = snd or ring.get("t_first") or 0
            if base and now - base > 480 and now - ring.get(
                    "last_fix", 0) > 600:
                ring["last_fix"] = now
                self._mic_reopen(
                    ring, "it had been silent for eight minutes")

    def _tap_watch(self):
        """The layers' watch, a mirror of _mic_watch on the same 4 s beat.
        Liveness is a pid check (0.02 ms): the stream gives NO signal when
        its target dies (measured: after a kill the tap keeps delivering
        zeros, is_running stays True, is_process_specific stays True).
        Three cases, like the mic's:
          B  never opened - look for the app every 20 s and open it with
             its OWN anchor (first sample, not t0: no zero burst for the
             hours before it appeared);
          A  the pid died, or a reopen failed ('dead') - re-walk every 8 s
             and reopen into the SAME ring on a new root (or the same one
             when it is alive again); after 60 s with nothing AND the pid
             really dead, say the app closed (once) and keep looking. A
             'dead' ring whose pid is alive (Discord runs, its tap will
             not reopen) keeps its 'could not be reopened yet' line and
             stays 'dead', retried - never 'gone', never 'closed';
          C  alive but the tap stalled (cb_at older than 8 s; proctap
             swallows worker errors, so silence is the only symptom) -
             reopen on the same pid, said once per kind. Only while the
             Mix heard sound in the last 30 s: a device playing nothing
             starves every process loopback by design (no chunk at all
             while the endpoint idles), and that is not a stall - no line,
             no reopen. A same-pid reopen whose fresh tap goes quiet again
             within the minute is not fixed by an 8 s hammer: one try a
             minute from then, until a reopened tap has run a good minute."""
        last_look = {"voice": 0.0, "game": 0.0}
        gone_since = {}
        while not self._stop.wait(4.0):
            if not (SETTINGS.get("capture_by_source")
                    and SETTINGS.get("capture_system")):
                continue
            now = time.time()
            for kind in ("voice", "game"):
                try:
                    ring = self._taps.get(kind)
                    if ring is None:
                        if now - last_look[kind] < 20:
                            continue
                        last_look[kind] = now
                        if kind == "voice":
                            exe, pid = _voice_target(list(
                                self.sources.get("voice_apps")
                                or SETTINGS.get("voice_apps") or []))
                        else:
                            exe = self.sources.get("game_exe")
                            pid = _root_pids((exe,)).get(exe) if exe else None
                        if not pid:
                            continue
                        path = os.path.join(
                            self.tmp_dir,
                            "%s%s.wav" % (kind, ("_" + self.tag) if self.tag else ""))
                        r = self._open_process_tap(pid, path, kind=kind, label=kind,
                                                   exe=exe, anchor=None, wait=0)
                        if r is not False:
                            if kind == "voice":
                                self.voice_wav = path
                            else:
                                self.game_wav = path
                            log(f"Sources: {exe} found on a second look (pid {pid}) "
                                f"- the {kind} layer is being recorded from here on.")
                        continue
                    st = ring.get("state")
                    if st in ("opening", "failed"):
                        continue
                    if st == "dead" or not _pid_wears(ring.get("pid"), ring.get("exe")):
                        if kind not in gone_since:
                            gone_since[kind] = now
                            ring["down_at"] = ring.get("down_at") or now
                        if now - last_look[kind] < 8:
                            continue
                        last_look[kind] = now
                        exe = ring.get("exe")
                        if kind == "voice":
                            exe, pid = _voice_target(list(
                                self.sources.get("voice_apps")
                                or SETTINGS.get("voice_apps") or []))
                        else:
                            pid = _root_pids((exe,)).get(exe) if exe else None
                        if pid and (pid != ring.get("pid") or st == "dead"):
                            if self._tap_reopen(ring, pid,
                                                "it restarted" if pid != ring.get("pid")
                                                else "it is back", exe=exe):
                                gone_since.pop(kind, None)
                        elif (now - gone_since[kind] > 60
                              and not _pid_alive(ring.get("pid"))
                              and ("gone_" + kind) not in self._said):
                            self._said.add("gone_" + kind)
                            ring["state"] = "gone"
                            _TAPWATCH[kind]["state"] = "gone"
                            log(f"Sources: {ring.get('exe')} closed - the {kind} "
                                f"layer is "
                                f"{'your microphone alone' if kind == 'voice' else 'silent'}"
                                f" from here.")
                        continue
                    cb = ring.get("cb_at") or 0
                    if not (cb and now - cb > 8):
                        continue
                    # C: quiet is a stall only while the Mix is hearing
                    # something (a silent device starves the taps by design)
                    mix = None
                    with self._ring_lock:
                        for r in self.rings:
                            if r.get("kind") == "system" and not r.get("is_tap"):
                                mix = r
                                break
                    if mix is not None and not (
                            mix.get("last_sound")
                            and now - float(mix["last_sound"]) <= 30):
                        continue
                    # the cadence rides the ring (stall_at / stall_backoff,
                    # beside reopens and down_at): a reopened tap that went
                    # quiet again within the minute waits a minute per try
                    prev = ring.get("stall_at")
                    if prev:
                        # cb - prev: how long the reopened tap kept delivering
                        ring["stall_backoff"] = not (cb - prev > 60)
                        if ring["stall_backoff"] and now - prev < 60:
                            continue
                    if ("stall", kind) not in self._said:
                        self._said.add(("stall", kind))
                        log(f"Sources: the {kind} tap stopped sending sound - "
                            f"reopening it.")
                    ring["stall_at"] = now
                    self._tap_reopen(ring, ring.get("pid"),
                                     "it stopped sending sound")
                except Exception:
                    pass

    def stop(self):
        self.signal_stop()
        self.finalize()

    def dump_ring(self, out_dir, seconds, trim_tail=0.0):
        """Write the last `seconds` of buffered audio to WAV file(s). Returns
        (system_wav_or_None, mic_wav_or_None, ends) where ends maps
        'system'/'mic' to the WALL-CLOCK time of the written wav's LAST sample.
        That anchor is what lets the clip mux line audio up against the video's
        own wall-clock end instead of guessing - the guess ('trim half a
        segment') left clip audio 1-2s EARLY whenever the open segment was
        young. trim_tail still drops the most-recent N seconds first (the clip's
        video ends in the past; audio buffered beyond it is useless).

        A voice or game layer ring (3.31 sources) is written the same way,
        at <out_dir>/voice_clip.wav and game_clip.wav, and ends carries
        'voice'/'game' beside 'system'/'mic'; the return arity stays
        (system, mic, ends) for the clip caller. ONLY A RING OF KIND 'mic'
        IS EVER RETURNED AS THE MIC - the old else-branch handed back
        whichever non-system ring came last, which with a layer ring
        present would have muxed Discord (or the game) as the Mic track."""
        sys_path = mic_path = None
        ends = {}
        # Snapshot under the lock with only a shallow ref-copy of each deque (fast),
        # then do the expensive b"".join OUTSIDE the lock so the audio callback isn't
        # blocked appending to the ring while a long clip is assembled (that block was
        # causing capture drops exactly when the user saved a clip). Bytes chunks are
        # immutable, so the joined result is identical to joining under the lock.
        # Top every ring up to NOW first: process-loopback (and starved
        # WASAPI) delivers nothing while the source is silent, so the ring's
        # newest bytes can be minutes old - a clip cut from that would lay
        # stale audio over silent footage. Bounded to the clip length.
        now = time.time()
        cap = int(max(1, seconds) + 5)
        with self._ring_lock:
            for r in self.rings:
                try:
                    if r.get("closed") or r["t_first"] is None or not r["push"]:
                        continue
                    miss = int((now - r["t_first"]) * r["rate"]) - r["frames"]
                    miss = min(miss, r["rate"] * cap)
                    while miss > 0:
                        n = min(miss, r["rate"] * 5)
                        r["push"](b"\x00" * (n * r["frame_bytes"]))
                        r["frames"] += n
                        miss -= n
                except Exception:
                    pass
            # a layer still opening, failed or gone has no sound of this
            # moment to lend a clip; 'dead' keeps its clock (silence) so
            # the clip's layout holds
            snap_refs = [(r["kind"], r["rate"], r["channels"], list(r["chunks"]),
                          r.get("t_first"), r.get("frames", 0))
                         for r in self.rings
                         if not r.get("is_tap")
                         or r.get("state") in ("live", "reconnected", "dead")]
        snapshot = [(kind, rate, channels, b"".join(chunks), t0, frames)
                    for (kind, rate, channels, chunks, t0, frames) in snap_refs]
        for kind, rate, channels, data, t0, frames in snapshot:
            frame = channels * 2                     # bytes per sample frame
            drop = int(rate * channels * 2 * max(0.0, trim_tail))
            drop -= drop % frame
            dropped_sec = 0.0
            if 0 < drop < len(data):
                data = data[:-drop]                  # discard the newest audio
                dropped_sec = drop / float(rate * channels * 2)
            want = int(rate * channels * 2 * seconds)
            tail = data[-want:] if want < len(data) else data
            tail = tail[len(tail) % frame:]          # keep cut on a sample boundary
            path = os.path.join(out_dir, f"{kind}_clip.wav")
            try:
                wf = wave.open(path, "wb")
                wf.setnchannels(channels); wf.setsampwidth(2); wf.setframerate(rate)
                wf.writeframes(tail); wf.close()
            except Exception as e:
                log(f"Replay: could not write {kind} audio ({e})")
                continue
            if not tail:
                # a ring that has delivered nothing yet: a header-only WAV
                # offered as a track fails the clip's mux, so it is not
                try:
                    os.remove(path)
                except Exception:
                    pass
                continue
            # Wall-clock of the wav's last sample: ring start + frames delivered
            # (the silence top-up keeps 'frames' tracking wall time), minus what
            # trim_tail actually removed.
            if t0 is not None and frames:
                ends[kind] = t0 + frames / float(rate) - dropped_sec
            if kind == "system":
                sys_path = path
            elif kind == "mic":
                mic_path = path
        return sys_path, mic_path, ends


def list_audio_devices():
    """(playback_outputs, microphones) - device-name lists for the Settings
    pickers. WASAPI devices only, loopback mirrors excluded. Safe on failure."""
    outs, mics = [], []
    try:
        import pyaudiowpatch as pyaudio
        pa = _pa_open(pyaudio)
        try:
            was = pa.get_host_api_info_by_type(pyaudio.paWASAPI)["index"]
            for i in range(pa.get_device_count()):
                d = pa.get_device_info_by_index(i)
                if d.get("hostApi") != was or d.get("isLoopbackDevice"):
                    continue
                name = str(d.get("name", "")).strip()
                if not name:
                    continue
                if d.get("maxOutputChannels", 0) > 0 and name not in outs:
                    outs.append(name)
                if d.get("maxInputChannels", 0) > 0 and name not in mics:
                    mics.append(name)
        finally:
            _pa_close(pa)
    except Exception as e:
        log(f"Audio device scan failed: {e}")
    return outs, mics


def diag_audio():
    load_settings()
    try:
        import pyaudiowpatch as pyaudio
    except ImportError:
        print("PyAudioWPatch not installed. Run:  pip install PyAudioWPatch")
        return
    p = _pa_open(pyaudio)
    wasapi = p.get_host_api_info_by_type(pyaudio.paWASAPI)
    out = p.get_device_info_by_index(wasapi["defaultOutputDevice"])
    inp = p.get_device_info_by_index(wasapi["defaultInputDevice"])
    print(f"\nDefault PLAYBACK (system sound will follow this): {out['name']}")
    print(f"Default MICROPHONE: {inp['name']}\n")
    print("Loopback devices (system capture uses one of these automatically):")
    for d in p.get_loopback_device_info_generator():
        print(f"  - {d['name']}")
    print("\nMicrophones / inputs you can target via 'mic_name_contains':")
    for i in range(p.get_device_count()):
        d = p.get_device_info_by_index(i)
        if d["maxInputChannels"] > 0 and not d.get("isLoopbackDevice"):
            print(f"  - {d['name']}")
    _pa_close(p)
    print("\nTip: to use your clean HyperX mic, set mic_name_contains to 'HyperX'.")


# ---------------------------------------------------------------------------
#  GPU / encoder auto-detection  (so it runs on AMD, NVIDIA, or Intel)
# ---------------------------------------------------------------------------
def get_screen_size():
    """Primary monitor pixel size (used only to probe the encoder at the real
    resolution - catches e.g. H.264's 4096px-wide hardware limit)."""
    if os.name == "nt":
        try:
            import ctypes
            try:
                ctypes.windll.user32.SetProcessDPIAware()
            except Exception:
                pass
            u = ctypes.windll.user32
            w, h = u.GetSystemMetrics(0), u.GetSystemMetrics(1)
            if w and h:
                return int(w), int(h)
        except Exception:
            pass
    return 1920, 1080


def _enumerate_active_monitors():
    r"""All currently-active display monitors, each as a dict:
        device  - the '\\.\DISPLAYn' GDI name
        num     - the trailing integer of that name (Windows' display number)
        rect    - (left, top, right, bottom) in virtual-desktop pixels
        primary - True for the primary monitor
    Returned in no particular order. Windows-only; [] elsewhere or on error."""
    mons = []
    if os.name != "nt":
        return mons
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32

        class MONITORINFOEXW(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.DWORD),
                        ("rcMonitor", wintypes.RECT),
                        ("rcWork", wintypes.RECT),
                        ("dwFlags", wintypes.DWORD),
                        ("szDevice", ctypes.c_wchar * 32)]

        MONITORENUMPROC = ctypes.WINFUNCTYPE(
            ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p,
            ctypes.POINTER(wintypes.RECT), ctypes.c_void_p)
        handles = []

        def _cb(hmon, hdc, lprc, lparam):
            handles.append(hmon)
            return 1
        user32.EnumDisplayMonitors(None, None, MONITORENUMPROC(_cb), 0)
        for hmon in handles:
            mi = MONITORINFOEXW()
            mi.cbSize = ctypes.sizeof(MONITORINFOEXW)
            if user32.GetMonitorInfoW(ctypes.c_void_p(hmon), ctypes.byref(mi)):
                dev = mi.szDevice or ""
                digits = "".join(c for c in dev if c.isdigit())
                mons.append({
                    "device": dev,
                    "num": int(digits) if digits else 0,
                    "rect": (mi.rcMonitor.left, mi.rcMonitor.top,
                             mi.rcMonitor.right, mi.rcMonitor.bottom),
                    "work": (mi.rcWork.left, mi.rcWork.top,
                             mi.rcWork.right, mi.rcWork.bottom),
                    "primary": bool(mi.dwFlags & 1),
                })
    except Exception:
        return []
    return mons


def _active_monitor_count():
    """How many monitors the screen-grabber can address (>=1)."""
    return max(1, len(_enumerate_active_monitors()))


_DXGI_MAP = {"at": 0.0, "map": None}


def _dxgi_output_map():
    """{device name: ddagrab output_idx}, asked of DXGI itself.

    ddagrab counts outputs the way DXGI enumerates them, which has nothing
    to do with the number in a device name. The tome used to assume they
    matched; on a desk whose primary screen is DISPLAY2 they are inverted,
    and every capture went to the wrong monitor. Cached for a minute -
    enumerating COM objects on the watcher beat is rude. An empty dict on
    any failure, and the caller falls back to the old guess rather than
    refusing to record."""
    now = time.time()
    if _DXGI_MAP["map"] is not None and now - _DXGI_MAP["at"] < 60:
        return _DXGI_MAP["map"]
    out = {}
    if os.name != "nt":
        return out
    try:
        import ctypes
        from ctypes import POINTER, byref, c_void_p, c_uint
        import uuid as _uuid

        class _GUID(ctypes.Structure):
            _fields_ = [("d1", ctypes.c_ulong), ("d2", ctypes.c_ushort),
                        ("d3", ctypes.c_ushort), ("d4", ctypes.c_ubyte * 8)]

        class _RECT(ctypes.Structure):
            _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                        ("right", ctypes.c_long), ("bottom", ctypes.c_long)]

        class _ODESC(ctypes.Structure):
            _fields_ = [("DeviceName", ctypes.c_wchar * 32),
                        ("DesktopCoordinates", _RECT),
                        ("AttachedToDesktop", ctypes.c_int),
                        ("Rotation", ctypes.c_uint),
                        ("Monitor", c_void_p)]

        g = _GUID()
        b = _uuid.UUID("770aae78-f26f-4dba-a829-253c83d1b387").bytes
        g.d1 = int.from_bytes(b[0:4], "big")
        g.d2 = int.from_bytes(b[4:6], "big")
        g.d3 = int.from_bytes(b[6:8], "big")
        for i in range(8):
            g.d4[i] = b[8 + i]

        fac = c_void_p()
        if ctypes.windll.dxgi.CreateDXGIFactory1(byref(g), byref(fac)) != 0:
            return out

        def _call(p, slot, restype, *args):
            vt = ctypes.cast(p, POINTER(POINTER(c_void_p)))[0]
            return ctypes.WINFUNCTYPE(restype, c_void_p, *args)(vt[slot])

        try:
            a = 0
            while True:
                ad = c_void_p()
                # EnumAdapters1 is slot 12, read as a plain long: the LAST
                # call always returns a failure code and an HRESULT
                # restype would raise on it
                if _call(fac, 12, ctypes.c_long, c_uint,
                         POINTER(c_void_p))(fac, a, byref(ad)) != 0:
                    break
                try:
                    o = 0
                    while True:
                        op = c_void_p()
                        if _call(ad, 7, ctypes.c_long, c_uint,
                                 POINTER(c_void_p))(ad, o, byref(op)) != 0:
                            break
                        try:
                            d = _ODESC()
                            _call(op, 7, ctypes.c_long,
                                  POINTER(_ODESC))(op, byref(d))
                            if d.DeviceName:
                                out[d.DeviceName] = o
                        finally:
                            _call(op, 2, ctypes.c_ulong)(op)
                        o += 1
                finally:
                    _call(ad, 2, ctypes.c_ulong)(ad)
                a += 1
        finally:
            _call(fac, 2, ctypes.c_ulong)(fac)
    except Exception:
        return {}
    _DXGI_MAP["map"] = out
    _DXGI_MAP["at"] = now
    return out


def _mon_output_idx(mon, fallback=0):
    """One monitor's ddagrab output index, or the old guess if DXGI is
    unreadable."""
    try:
        got = _dxgi_output_map().get(mon.get("device") or "")
        if got is not None:
            return int(got)
    except Exception:
        pass
    return int(fallback)


def _monitors_ranked():
    """Every active monitor, PRIMARY FIRST, then by display number.

    The setting has always said "0 = the primary screen". It ranked by the
    number in the device name instead, so on a desk whose primary is
    DISPLAY2 the default pointed at the other screen. Primary first makes
    that sentence true, and every rect check now reads the same list."""
    mons = _enumerate_active_monitors()
    if not mons:
        return []
    return sorted(mons, key=lambda m: (0 if m.get("primary") else 1,
                                       m.get("num", 0)))


def _capture_output_idx(idx=None):
    """The ddagrab output_idx for the screen the tome is set to record.

    The single place that turns "which monitor" into "which output"."""
    mons = _monitors_ranked()
    if not mons:
        return 0
    try:
        i = int(idx if idx is not None else SETTINGS.get("monitor_index", 0))
    except (TypeError, ValueError):
        i = 0
    i = min(max(0, i), len(mons) - 1)
    return _mon_output_idx(mons[i], i)


def _resolve_capture_monitor():
    """Which screen to capture. Simple and predictable: the monitor_index setting,
    where 0 = primary screen (the default). "Auto"/-1 also means the primary screen.
    No foreground-window guessing - that proved unreliable across mixed multi-monitor
    setups and could silently record the wrong screen."""
    try:
        idx = int(SETTINGS.get("monitor_index", 0))
    except Exception:
        idx = 0
    return idx if idx >= 0 else 0



def _hdr_active():
    """True if ANY active display currently has HDR (advanced colour) switched ON.
    Windows-only, and deliberately CONSERVATIVE: any uncertainty returns False, so
    it can never wrongly tone-map an ordinary SDR desktop. This is what lets Lore
    record correctly when Windows HDR is on even if the app's HDR toggle is off."""
    if os.name != "nt":
        return False
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        QDC_ONLY_ACTIVE_PATHS = 2

        class LUID(ctypes.Structure):
            _fields_ = [("LowPart", wintypes.DWORD), ("HighPart", wintypes.LONG)]

        class SRC(ctypes.Structure):
            _fields_ = [("adapterId", LUID), ("id", wintypes.UINT),
                        ("modeInfoIdx", wintypes.UINT), ("statusFlags", wintypes.UINT)]

        class TGT(ctypes.Structure):
            _fields_ = [("adapterId", LUID), ("id", wintypes.UINT),
                        ("modeInfoIdx", wintypes.UINT), ("outputTechnology", wintypes.UINT),
                        ("rotation", wintypes.UINT), ("scaling", wintypes.UINT),
                        ("refreshNum", wintypes.UINT), ("refreshDen", wintypes.UINT),
                        ("scanline", wintypes.UINT), ("targetAvailable", wintypes.BOOL),
                        ("statusFlags", wintypes.UINT)]

        class PATH(ctypes.Structure):
            _fields_ = [("sourceInfo", SRC), ("targetInfo", TGT), ("flags", wintypes.UINT)]

        class MODE(ctypes.Structure):       # we only need the right size for the buffer
            _fields_ = [("infoType", wintypes.UINT), ("id", wintypes.UINT),
                        ("adapterId", LUID), ("blob", ctypes.c_byte * 64)]

        class HDR(ctypes.Structure):
            _fields_ = [("type", wintypes.UINT), ("size", wintypes.UINT),
                        ("adapterId", LUID), ("id", wintypes.UINT),
                        ("value", wintypes.UINT), ("colorEncoding", wintypes.UINT),
                        ("bitsPerColor", wintypes.UINT)]

        npaths, nmodes = wintypes.UINT(), wintypes.UINT()
        if user32.GetDisplayConfigBufferSizes(QDC_ONLY_ACTIVE_PATHS,
                                              ctypes.byref(npaths), ctypes.byref(nmodes)) != 0:
            return False
        paths = (PATH * npaths.value)()
        modes = (MODE * nmodes.value)()
        if user32.QueryDisplayConfig(QDC_ONLY_ACTIVE_PATHS, ctypes.byref(npaths), paths,
                                     ctypes.byref(nmodes), modes, None) != 0:
            return False
        GET_ADVANCED_COLOR_INFO = 9
        for i in range(npaths.value):
            req = HDR()
            req.type = GET_ADVANCED_COLOR_INFO
            req.size = ctypes.sizeof(HDR)
            req.adapterId = paths[i].targetInfo.adapterId
            req.id = paths[i].targetInfo.id
            if user32.DisplayConfigGetDeviceInfo(ctypes.byref(req)) == 0:
                # bit0 = advancedColorSupported, bit1 = advancedColorEnabled (HDR on)
                if req.value & 0x2:
                    return True
        return False
    except Exception:
        return False


def _sdr_white_nits():
    """The Windows 'SDR content brightness' level in nits - the brightness an HDR
    desktop draws WHITE (255,255,255) at. This is THE anchor for converting an
    HDR recording back to a normal-looking SDR file: convert against a textbook
    reference (100 or 203 nits) instead and everything comes out 1.2-2.4x too
    bright ('mega blown out' - the 1.21-1.23 bug). Returns the LARGEST level
    across active displays (SDR-only displays report the 80-nit floor, the HDR
    display carries the real slider value), or None if the query fails.
    Verified against the dev G95SC: slider 40% -> SDRWhiteLevel 3000 -> 240.0."""
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        QDC_ONLY_ACTIVE_PATHS = 2

        class LUID(ctypes.Structure):
            _fields_ = [("LowPart", wintypes.DWORD), ("HighPart", wintypes.LONG)]

        class SRC(ctypes.Structure):
            _fields_ = [("adapterId", LUID), ("id", wintypes.UINT),
                        ("modeInfoIdx", wintypes.UINT), ("statusFlags", wintypes.UINT)]

        class TGT(ctypes.Structure):
            _fields_ = [("adapterId", LUID), ("id", wintypes.UINT),
                        ("modeInfoIdx", wintypes.UINT), ("outputTechnology", wintypes.UINT),
                        ("rotation", wintypes.UINT), ("scaling", wintypes.UINT),
                        ("refreshNum", wintypes.UINT), ("refreshDen", wintypes.UINT),
                        ("scanline", wintypes.UINT), ("targetAvailable", wintypes.BOOL),
                        ("statusFlags", wintypes.UINT)]

        class PATH(ctypes.Structure):
            _fields_ = [("sourceInfo", SRC), ("targetInfo", TGT), ("flags", wintypes.UINT)]

        class MODE(ctypes.Structure):
            _fields_ = [("infoType", wintypes.UINT), ("id", wintypes.UINT),
                        ("adapterId", LUID), ("blob", ctypes.c_byte * 64)]

        class SDRW(ctypes.Structure):   # DISPLAYCONFIG_SDR_WHITE_LEVEL
            _fields_ = [("type", wintypes.UINT), ("size", wintypes.UINT),
                        ("adapterId", LUID), ("id", wintypes.UINT),
                        ("SDRWhiteLevel", wintypes.ULONG)]

        npaths, nmodes = wintypes.UINT(), wintypes.UINT()
        if user32.GetDisplayConfigBufferSizes(QDC_ONLY_ACTIVE_PATHS,
                                              ctypes.byref(npaths), ctypes.byref(nmodes)) != 0:
            return None
        paths = (PATH * npaths.value)()
        modes = (MODE * nmodes.value)()
        if user32.QueryDisplayConfig(QDC_ONLY_ACTIVE_PATHS, ctypes.byref(npaths), paths,
                                     ctypes.byref(nmodes), modes, None) != 0:
            return None
        GET_SDR_WHITE_LEVEL = 11
        best = None
        for i in range(npaths.value):
            req = SDRW()
            req.type = GET_SDR_WHITE_LEVEL
            req.size = ctypes.sizeof(SDRW)
            req.adapterId = paths[i].targetInfo.adapterId
            req.id = paths[i].targetInfo.id
            if user32.DisplayConfigGetDeviceInfo(ctypes.byref(req)) == 0:
                nits = req.SDRWhiteLevel * 80.0 / 1000.0   # units of 1/1000 of 80 nits
                if nits > 0 and (best is None or nits > best):
                    best = nits
        return best
    except Exception:
        return None


_FILTER_CACHE = {}


def _has_filter(name):
    """Does the bundled ffmpeg have this filter? Probed once per session."""
    v = _FILTER_CACHE.get(name)
    if v is not None:
        return v
    try:
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        r = subprocess.run([SETTINGS["ffmpeg_path"], "-hide_banner", "-h", f"filter={name}"],
                           capture_output=True, text=True, timeout=10, creationflags=flags)
        v = (r.returncode == 0 and "Unknown filter" not in (r.stderr or "")
             and "Unknown filter" not in (r.stdout or ""))
    except Exception:
        v = False
    _FILTER_CACHE[name] = v
    return v


def _hdr_strategy():
    """How this capture should handle an HDR desktop:
      None      - no HDR handling (SDR desktop, or the user turned it off)
      'native'  - capture the float16 (scRGB) desktop surface zero-copy into an
                  AMF encoder, producing a TRUE 10-bit HDR10 (PQ/BT.2020) file.
    Why float16 is not optional: the colour-patch lab proved every other ddagrab
    readback of an HDR desktop (8-bit AND 10-bit) is LINEAR light hard-clipped at
    80 nits by Windows - most of the image is destroyed before any filter can
    touch it. That clipped source is what made 1.16-1.23 HDR washed/neon under
    every tone-map curve tried. Only AMF encoders accept the float16 surface on
    the GPU, so 'native' applies only to them; everything else records plain
    (build_video_cmd handles that), which is flat-ish but never neon.
    Accepts legacy values (bool / 'on' / 'tonemap')."""
    mode = str(SETTINGS.get("hdr_mode", "auto")).strip().lower()
    if mode in ("off", "false", "0", "no"):
        return None
    return "native" if _hdr_active() else None


def _enc_supports_10bit(enc):
    """Can this encoder produce a real 10-bit stream? Native HDR must never be
    attempted on 8-bit-only encoders (h264_nvenc, h264_amf, libx264) - the run
    would just die and burn a retry cycle on every recording."""
    e = (enc or "").lower()
    return ("av1" in e) or ("hevc" in e) or ("265" in e)


def _hdr_native_args(grab, enc_name=""):
    """(filtergraph, extra encoder args, global pre-args) for native HDR capture
    on an AMF encoder - the ONLY encoder family here that accepts the float16
    scRGB desktop surface directly (zero-copy d3d11; measured the same speed
    class as plain capture on the dev RX 9070 XT, and bit-exact PQ against the
    drawn-patch lab: white 255 -> 255, grey 128 -> 129 after finishing).

    The pieces, each load-bearing:
      * output_fmt=16bit    - the float16 surface; the only UNCLIPPED source.
      * -init_hw_device...  - a shared d3d11 device; without it AMF refuses the
                              float16 frames outright ('Invalid argument').
      * -bitdepth 10 / main10 - with 10-bit output AMF PQ-encodes the linear
                              floats at the true scRGB scale (1.0 = 80 nits,
                              verified against PQ maths to within quantisation).
      * the metadata BSF    - AMF stamps the container 'linear/gbr', which is
                              wrong; the BSF writes PQ/BT.2020 into the actual
                              bitstream header, which is what decoders trust."""
    if enc_name.startswith("av1"):
        depth = ["-bitdepth", "10"]
        bsf = ["-bsf:v", "av1_metadata=color_primaries=9:"
               "transfer_characteristics=16:matrix_coefficients=9:color_range=tv"]
    else:                                   # hevc_amf
        depth = ["-profile:v", "main10"]
        bsf = ["-bsf:v", "hevc_metadata=colour_primaries=9:"
               "transfer_characteristics=16:matrix_coefficients=9"]
    pre = ["-init_hw_device", "d3d11va=dd", "-filter_hw_device", "dd"]
    vf = f"{grab}:output_fmt=16bit[v]"
    return vf, depth + bsf, pre


def _hdr_to_sdr_vf(trc, nits=None):
    """The ONE offline HDR->SDR conversion used everywhere (finishing queue,
    Discord copies, thumbnails), so every consumer produces the same colours.
    Validated absolutely against drawn patches on the dev machine: white 255 ->
    255, grey 180 -> 180, grey 128 -> 129, red (255,0,0) -> (252,6,4).

    The recipe (each part fixes a measured failure - don't 'improve' casually):
      * setparams when the container says 'linear' - our own recordings: AMF
        writes real PQ/BT.2020 pixels but mislabels the container; concat-copied
        segments keep that label. Forcing the true interpretation makes the
        chain deterministic even if a decoder ignores the (correct) bitstream
        header that the recording BSF wrote.
      * npl = the Windows SDR white level AT RECORD TIME (the nits argument;
        falls back to querying now, then 240). PQ is absolute: dividing by the
        wrong white is exactly the old 'mega blown out' bug - npl=100 lifted a
        240-nit desktop 2.4x.
      * tonemap=clip:desat=0 - highlights above SDR white clip, exactly like an
        SDR monitor would show them. desat=0 matters: the filter's DEFAULT
        desat=2 bleeds blue into bright yellows/reds (measured +65/255 blue).
      * output transfer iec61966-2-1 (sRGB) - matches how the desktop actually
        displayed the content; the classic bt709 camera curve measured ~+7 too
        bright on every mid grey."""
    n = 240
    try:
        n = int(round(float(nits))) if nits else int(round(_sdr_white_nits() or 240))
    except Exception:
        pass
    n = max(80, min(1000, n))
    pre = ""
    if (trc or "").strip().lower() == "linear":
        pre = ("setparams=color_primaries=bt2020:color_trc=smpte2084:"
               "colorspace=bt2020nc,")
    return (pre + f"zscale=t=linear:npl={n},"
            "tonemap=tonemap=clip:param=1.0:desat=0,"
            "zscale=p=bt709:t=iec61966-2-1:m=bt709:r=tv")


def _is_hdr_trc(trc):
    """Is this transfer tag one of our HDR recordings? 'smpte2084'/'arib-std-b67'
    are real HDR labels; 'linear' is what AMF stamps on the CONTAINER of our
    float16-native recordings (the bitstream itself is PQ - see _hdr_native_args)."""
    return (trc or "").strip().lower() in ("smpte2084", "arib-std-b67", "linear")


def detect_gpu_vendor():
    """Return 'amd' / 'nvidia' / 'intel' / None by asking Windows what display
    adapter is installed. Prefers a discrete GPU when more than one is listed."""
    if os.name != "nt":
        return None
    try:
        flags = subprocess.CREATE_NO_WINDOW
        out = subprocess.run(
            ["powershell", "-NoProfile", "-Command",
             "Get-CimInstance Win32_VideoController | "
             "Select-Object -ExpandProperty Name"],
            capture_output=True, text=True, timeout=6, creationflags=flags
        ).stdout.lower()
    except Exception:
        out = ""
    if any(k in out for k in ("nvidia", "geforce", "rtx", "gtx")):
        return "nvidia"
    if any(k in out for k in ("radeon", "amd", "rx ")):
        return "amd"
    if any(k in out for k in ("intel", "arc", "iris", "uhd graphics")):
        return "intel"
    return None


def _encoder_works(enc, w, h, fps):
    """True if this encoder actually initialises on this machine. Feeds it a few
    synthetic nv12 frames at the real resolution - the same pixel format the real
    capture delivers - so a pass is representative."""
    if enc in _BAD_ENCODERS:
        return False
    cmd = [SETTINGS["ffmpeg_path"], "-hide_banner", "-loglevel", "error",
           "-f", "lavfi", "-i", f"color=c=black:s={w}x{h}:r={fps}",
           "-vf", "format=nv12", "-frames:v", "3", "-c:v", enc, "-f", "null", "-"]
    try:
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        return subprocess.run(cmd, capture_output=True, timeout=40,
                              creationflags=flags).returncode == 0
    except Exception:
        return False


def choose_encoder(vendor, w, h, fps, prefer_av1=True):
    """Pick the best WORKING encoder for this GPU. Tries the vendor's AV1 then
    HEVC hardware encoder, then any other vendor's HEVC (in case detection was
    off), then guarantees a result with software encoding. Encoders that died at
    runtime earlier this session (_BAD_ENCODERS) are skipped."""
    fam = {
        "amd":    ["av1_amf", "hevc_amf"],
        "nvidia": ["av1_nvenc", "hevc_nvenc"],
        "intel":  ["av1_qsv", "hevc_qsv"],
    }.get(vendor, [])
    if not prefer_av1:
        fam = [e for e in fam if not e.startswith("av1")]
    # Cross-vendor fallback. Include the hardware AV1 encoders here too (when AV1 is
    # wanted) so a machine whose GPU vendor couldn't be detected (e.g. PowerShell/WMI
    # locked down) still tries hardware AV1 before dropping to CPU software. The
    # h264 HARDWARE encoders come before software: an older GPU (GTX 6xx-9xx,
    # pre-Skylake Intel) still beats libx264 trying to chase 60fps on the CPU.
    tail = (["av1_amf", "av1_nvenc", "av1_qsv"] if prefer_av1 else []) \
        + ["hevc_amf", "hevc_nvenc", "hevc_qsv",
           "h264_nvenc", "h264_qsv", "h264_amf", "libx265", "libx264"]
    seen, order = set(), []
    for e in fam + tail:
        if e not in seen and e not in _BAD_ENCODERS:
            seen.add(e); order.append(e)
    for enc in order:
        if _encoder_works(enc, w, h, fps):
            return enc
    return "libx264"  # last resort; always present in a full ffmpeg build


def _capture_screen_size():
    """A representative resolution for the encoder probe. The capture target may be a
    secondary monitor LARGER than the primary, so probe at the biggest active monitor
    (and never below the primary) - that keeps the H.264 4096px-wide guard meaningful
    when capturing a 4K/ultrawide secondary. Falls back to the primary on any error."""
    pw, ph = get_screen_size()
    try:
        mons = _enumerate_active_monitors()
        if mons:
            w = max((m["rect"][2] - m["rect"][0]) for m in mons)
            h = max((m["rect"][3] - m["rect"][1]) for m in mons)
            return max(w, pw), max(h, ph)
    except Exception:
        pass
    return pw, ph


def resolve_encoder():
    """Turn the 'encoder' setting (auto / av1 / hevc / explicit) into a concrete
    encoder that works on THIS machine, and cache it for the session."""
    pref = str(SETTINGS.get("encoder", "auto")).lower()
    w, h = _capture_screen_size()
    fps = int(SETTINGS["framerate"])
    if pref in ("auto", "av1", "hevc"):
        vendor = detect_gpu_vendor()
        enc = choose_encoder(vendor, w, h, fps, prefer_av1=(pref != "hevc"))
        log(f"GPU detected: {vendor or 'unknown'} -> encoder '{enc}' @ {w}x{h}/{fps}")
    elif _encoder_works(pref, w, h, fps):
        enc = pref
    else:
        vendor = detect_gpu_vendor()
        enc = choose_encoder(vendor, w, h, fps, True)
        log(f"Encoder '{pref}' didn't work here; falling back to '{enc}'")
    SETTINGS["_encoder_resolved"] = enc
    return enc


def _current_encoder():
    return SETTINGS.get("_encoder_resolved") or resolve_encoder()


def _ffmpeg_ok():
    """Quick one-shot check that the ffmpeg binary actually runs. Lets a missing or
    antivirus-quarantined ffmpeg surface as a plain-language message at startup
    instead of degrading into a permanent, silent 'never records'."""
    try:
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        r = subprocess.run([SETTINGS["ffmpeg_path"], "-version"],
                           capture_output=True, timeout=10, creationflags=flags)
        return r.returncode == 0
    except Exception:
        return False


def encoder_quality_flags(enc, br):
    """Rate-control + quality flags, tuned for QUALITY PER GIGABYTE: peak-constrained
    VBR instead of CBR, so quiet scenes stop burning bits and busy scenes may borrow
    up to 2x the target. Real files come out well under the old CBR sizes at equal
    or better quality. The option NAMES differ per encoder family, so this can't be
    shared - AMF uses -quality, NVENC uses -preset pN, etc."""
    q = SETTINGS["amf_quality"]
    vbr = ["-b:v", f"{br}M", "-maxrate", f"{br * 2}M", "-bufsize", f"{br * 4}M"]
    if enc.endswith("_amf"):
        return ["-rc", "vbr_peak", *vbr, "-quality", q]
    if enc.endswith("_nvenc"):
        preset = {"speed": "p1", "balanced": "p4", "quality": "p7"}.get(q, "p4")
        return ["-rc", "vbr", *vbr, "-preset", preset]
    if enc.endswith("_qsv"):
        preset = {"speed": "veryfast", "balanced": "medium", "quality": "slower"}.get(q, "medium")
        return [*vbr, "-preset", preset]
    # software libx264 / libx265: constant-quality capped at the same peak
    preset = {"speed": "veryfast", "balanced": "medium", "quality": "slow"}.get(q, "medium")
    return ["-crf", "23", "-maxrate", f"{br * 2}M", "-bufsize", f"{br * 4}M",
            "-preset", preset]


# ---------------------------------------------------------------------------
#  ffmpeg: video capture + final mux
# ---------------------------------------------------------------------------
def _game_window_title(pname):
    """Title of the given process's biggest visible top-level window, or None.
    Used by the EXPERIMENTAL window-only capture scope to aim gdigrab."""
    if os.name != "nt" or not pname:
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        pids = set()
        for pr in psutil.process_iter(["pid", "name"]):
            try:
                if (pr.info.get("name") or "").lower() == pname.lower():
                    pids.add(pr.info["pid"])
            except Exception:
                pass
        if not pids:
            return None
        best = {"area": 0, "title": None}

        @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p)
        def _enum(h, _l):
            try:
                if not user32.IsWindowVisible(h) or user32.IsIconic(h):
                    return 1
                pid = wintypes.DWORD()
                user32.GetWindowThreadProcessId(h, ctypes.byref(pid))
                if pid.value not in pids:
                    return 1
                r = wintypes.RECT()
                user32.GetWindowRect(h, ctypes.byref(r))
                area = max(0, r.right - r.left) * max(0, r.bottom - r.top)
                if area <= best["area"]:
                    return 1
                n = user32.GetWindowTextLengthW(h)
                if n <= 0:
                    return 1
                buf = ctypes.create_unicode_buffer(n + 1)
                user32.GetWindowTextW(h, buf, n + 1)
                if buf.value:
                    best["area"] = area
                    best["title"] = buf.value
            except Exception:
                pass
            return 1
        user32.EnumWindows(_enum, 0)
        return best["title"]
    except Exception:
        return None


def _pid_for_exe(pname):
    """The pid to tap for this exe name, or None. Used to aim the game
    tap (process loopback captures the pid + its children, so the main
    process is the right target even for launcher-spawned games). The
    ROOT (the process whose parent does not wear the same name) is the
    right target: process loopback captures the pid + its children,
    never its parent or siblings - a game whose exe re-spawns a child of
    the same name would be tapped at the child and miss the parent's
    sound. Falls back to the first live match when the walk gives
    nothing."""
    if not pname:
        return None
    try:
        root = _root_pids((pname.lower(),)).get(pname.lower())
        if root:
            return root
    except Exception:
        pass
    try:
        for pr in psutil.process_iter(["pid", "name"]):
            try:
                if (pr.info.get("name") or "").lower() == pname.lower():
                    return pr.info["pid"]
            except Exception:
                pass
    except Exception:
        pass
    return None


def _root_pids(names):
    """{exe name: root pid} for the given lowercase exe names - the root
    is a process of that name whose PARENT does not wear the same name.
    Discord.exe is six processes and the renderer is not the one to tap:
    INCLUDE_TARGET_PROCESS_TREE follows the tree DOWN from the pid it is
    given (proven by qa/proctap_tree.py), so the root hears them all.
    A process whose parent is already dead counts as a root.

    Toolhelp32 through ctypes, not psutil: the snapshot walk costs 10-14
    ms for ~300 processes here, where psutil.process_iter with ppid took
    3.4 s cold on this machine - and the tap watch walks this every 8 s
    while a layer's app is missing."""
    want = {str(n or "").strip().lower() for n in (names or ()) if n}
    if not want or os.name != "nt":
        return {}
    import ctypes
    from ctypes import wintypes

    class _PE32W(ctypes.Structure):
        _fields_ = [("dwSize", wintypes.DWORD),
                    ("cntUsage", wintypes.DWORD),
                    ("th32ProcessID", wintypes.DWORD),
                    ("th32DefaultHeapID", ctypes.c_size_t),
                    ("th32ModuleID", wintypes.DWORD),
                    ("cntThreads", wintypes.DWORD),
                    ("th32ParentProcessID", wintypes.DWORD),
                    ("pcPriClassBase", ctypes.c_long),
                    ("dwFlags", wintypes.DWORD),
                    ("szExeFile", ctypes.c_wchar * 260)]

    k32 = ctypes.windll.kernel32
    k32.CreateToolhelp32Snapshot.restype = wintypes.HANDLE
    k32.CreateToolhelp32Snapshot.argtypes = [wintypes.DWORD, wintypes.DWORD]
    k32.Process32FirstW.restype = wintypes.BOOL
    k32.Process32FirstW.argtypes = [wintypes.HANDLE, ctypes.POINTER(_PE32W)]
    k32.Process32NextW.restype = wintypes.BOOL
    k32.Process32NextW.argtypes = [wintypes.HANDLE, ctypes.POINTER(_PE32W)]
    k32.CloseHandle.argtypes = [wintypes.HANDLE]
    snap = k32.CreateToolhelp32Snapshot(0x2, 0)        # TH32CS_SNAPPROCESS
    if not snap or snap == wintypes.HANDLE(-1).value:
        return {}
    procs = {}                                         # pid -> (exe, ppid)
    try:
        e = _PE32W()
        e.dwSize = ctypes.sizeof(_PE32W)
        if k32.Process32FirstW(snap, ctypes.byref(e)):
            while True:
                procs[int(e.th32ProcessID)] = (
                    (e.szExeFile or "").lower(), int(e.th32ParentProcessID))
                if not k32.Process32NextW(snap, ctypes.byref(e)):
                    break
    finally:
        try:
            k32.CloseHandle(snap)
        except Exception:
            pass
    out = {}
    for pid, (nm, pp) in procs.items():
        if nm in want and nm not in out and procs.get(pp, ("",))[0] != nm:
            out[nm] = pid
    return out


def _climb_to_root(pid, exe):
    """The window's owner may be a child of the same exe; the tap must
    sit on the tree root. Returns the same pid when its parent does not
    wear the game's name, or on any error."""
    if not pid:
        return pid
    try:
        cur = psutil.Process(int(pid))
        want = str(exe or "").lower()
        for _ in range(32):                # a same-name chain, never a loop
            pp = cur.parent()
            if pp is None or (pp.name() or "").lower() != want:
                return cur.pid
            cur = pp
        return cur.pid
    except Exception:
        return pid


def _pid_alive(pid):
    """Is this pid simply alive, whatever it wears? The watch's 'closed for
    good' verdict wants the process REALLY gone: _pid_wears also says no
    for a pid that is alive under a name it cannot read (AccessDenied) or
    a reopen that keeps failing while the app runs, and neither of those
    is an app that closed."""
    try:
        return bool(pid) and psutil.pid_exists(int(pid))
    except Exception:
        return False


def _pid_wears(pid, exe):
    """THE LIVENESS GATE (0.02 ms measured): is this pid alive AND wearing
    this exe name? A tap on a dead pid is granted, process-specific, and
    silent for ever - so nothing may tap a pid this has not just said
    yes to."""
    try:
        return bool(pid) and psutil.pid_exists(int(pid)) and (
            psutil.Process(int(pid)).name() or "").lower() == str(exe or "").lower()
    except Exception:
        return False


def _voice_target(voice_apps):
    """(exe, root pid) of the voice app to tap - the FIRST running name in
    the setting's order - or (None, None). One tap only: with Discord and
    Steam both listed and running, the layer follows the first and says
    so once (the other's voices land in the Mix only)."""
    apps = [str(n or "").strip().lower() for n in (voice_apps or ()) if n]
    roots = _root_pids(apps)
    for nm in apps:
        if nm in roots:
            if (sum(1 for n in apps if n in roots) > 1
                    and "voice_two" not in _TAPWATCH["said"]):
                _TAPWATCH["said"].add("voice_two")
                log(f"Sources: more than one voice app is running; the "
                    f"voice layer follows {nm}.")
            return nm, roots[nm]
    return None, None


def _screen_capture_wh(mon_idx):
    """Pixel size of the screen a screen-scope session records. A capture
    restart may only continue the SAME file while this is unchanged: the
    runs are joined with -c copy, and two frame sizes in one stream make an
    unplayable video. Ranked by display number, the ddagrab output_idx
    contract. None when it can't be determined (caller then plays safe)."""
    # Retried: this is asked precisely WHILE the display mode is changing,
    # and a single failed enumeration then would read as "the screen changed
    # shape" and split the recording - the exact symptom being fixed.
    for attempt in range(3):
        try:
            mons = _monitors_ranked()
            if mons:
                m = mons[min(max(0, int(mon_idx or 0)), len(mons) - 1)]
                r = m["rect"]
                return (r[2] - r[0], r[3] - r[1])
        except Exception:
            pass
        if attempt < 2:
            time.sleep(0.2)
    return None


def _hdr_run_flag():
    """Will the NEXT capture run record true HDR? Mirrors build_video_cmd's
    gate exactly (float16 only rides a 10-bit-capable AMF encoder). A
    restart may only continue the same file while this is unchanged - an
    HDR run and an SDR run cannot be concatenated by stream copy."""
    try:
        strat = _hdr_strategy()
        enc_now = _current_encoder()
        if strat == "native" and not (enc_now.endswith("_amf")
                                      and _enc_supports_10bit(enc_now)):
            strat = None
        return bool(strat and _HDR_LEVEL[0] < 1)
    except Exception:
        return False


def _game_window_rect(pname, hwnd=None):
    """Where the given game's window is RIGHT NOW, as a capture rect:
        {"hwnd", "mon" (ddagrab output index), "x", "y", "w", "h"}
      or {"hwnd", "iconic": True}   while the window is minimised
      or None                       when the process has no usable window.
    x/y/w/h are the window's CLIENT area (the game's picture, no title bar)
    in monitor-relative physical pixels, clamped to the screen and aligned
    for the encoder (offsets even, size mod-8 - AMF pads odd sizes up, which
    would smuggle dead pixel columns in and shift dims between runs).
    Used by the EXPERIMENTAL window-only capture scope: the rect crops the
    same GPU desktop-duplication capture the whole screen uses, so HDR and
    zero-copy encoding keep working. Pass the previous poll's hwnd - it is
    revalidated cheaply and the full window hunt runs only when it died
    (games recreate their window on display-mode switches)."""
    if os.name != "nt" or not pname:
        return None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        # ddagrab captures PHYSICAL pixels, but a system-DPI-aware process
        # reads VIRTUALISED rects for windows on monitors whose scale differs
        # from the system DPI (a game on a 150% 4K next to a 100% primary
        # would get a rect ~2/3 its real size - the file would hold only part
        # of the game). Flip just this thread to per-monitor awareness while
        # measuring; restored below. Pre-1703 Windows: quietly skipped -
        # single-scale setups were already correct there.
        oldctx = None
        try:
            user32.SetThreadDpiAwarenessContext.restype = ctypes.c_void_p
            user32.SetThreadDpiAwarenessContext.argtypes = [ctypes.c_void_p]
            oldctx = user32.SetThreadDpiAwarenessContext(ctypes.c_void_p(-4))
        except Exception:
            oldctx = None
        try:
            h = None
            icon_h = None
            if hwnd:
                try:
                    if user32.IsWindow(hwnd) and user32.IsWindowVisible(hwnd):
                        pid = wintypes.DWORD()
                        user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
                        if (pid.value
                                and psutil.Process(pid.value).name().lower()
                                == pname.lower()):
                            h = hwnd
                except Exception:
                    h = None
            if h is None:
                pids = set()
                for pr in psutil.process_iter(["pid", "name"]):
                    try:
                        if (pr.info.get("name") or "").lower() == pname.lower():
                            pids.add(pr.info["pid"])
                    except Exception:
                        pass
                if not pids:
                    return None
                best = {"area": 0, "hwnd": None, "icon": None}

                @ctypes.WINFUNCTYPE(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p)
                def _enum(hw, _l):
                    try:
                        if not user32.IsWindowVisible(hw):
                            return 1
                        pid = wintypes.DWORD()
                        user32.GetWindowThreadProcessId(hw, ctypes.byref(pid))
                        if pid.value not in pids:
                            return 1
                        if user32.IsIconic(hw):
                            # minimised counts (it pauses capture) - tracked
                            # apart so a tiny visible stub window (a crash
                            # handler, a notifier) can't make the real,
                            # minimised game look 'gone'
                            if best["icon"] is None:
                                best["icon"] = hw
                            return 1
                        r = wintypes.RECT()
                        user32.GetWindowRect(hw, ctypes.byref(r))
                        area = (max(0, r.right - r.left)
                                * max(0, r.bottom - r.top))
                        if area > best["area"]:
                            best["area"] = area
                            best["hwnd"] = hw
                    except Exception:
                        pass
                    return 1
                user32.EnumWindows(_enum, 0)
                h = best["hwnd"] or best["icon"]
                icon_h = best["icon"]
            if h is None:
                return None
            if user32.IsIconic(h):
                return {"hwnd": h, "iconic": True}
            cr = wintypes.RECT()
            if not user32.GetClientRect(h, ctypes.byref(cr)):
                return None
            pt = wintypes.POINT(0, 0)
            if not user32.ClientToScreen(h, ctypes.byref(pt)):
                return None
            x, y = pt.x, pt.y
            w, hh = cr.right - cr.left, cr.bottom - cr.top
            if w < 64 or hh < 64:
                # the visible winner is a stub; honour a minimised sibling so
                # capture pauses instead of falling back to the whole screen
                if icon_h:
                    return {"hwnd": icon_h, "iconic": True}
                return None

            # which screen the window lives on -> the matching ddagrab
            # output. Ranked by display number: the same contract every other
            # output_idx consumer uses (_watched_monitor_rect and friends) -
            # raw EnumDisplayMonitors order is NOT guaranteed to match it.
            class MI(ctypes.Structure):
                _fields_ = [("cbSize", wintypes.DWORD), ("rcMonitor", wintypes.RECT),
                            ("rcWork", wintypes.RECT), ("dwFlags", wintypes.DWORD)]
            hm = user32.MonitorFromWindow(h, 2)      # MONITOR_DEFAULTTONEAREST
            mi = MI()
            mi.cbSize = ctypes.sizeof(MI)
            if not user32.GetMonitorInfoW(hm, ctypes.byref(mi)):
                return None
            mrect = (mi.rcMonitor.left, mi.rcMonitor.top,
                     mi.rcMonitor.right, mi.rcMonitor.bottom)
            # WHICH OUTPUT, NOT WHICH RANK. This matched the window's
            # monitor against a list sorted by device number and gave
            # ddagrab that position. DXGI numbers its outputs its own way,
            # so on his desk a game on the main screen was captured from
            # the second one - the screen his own window was filling,
            # which is how the tome ended up inside his recordings.
            mons = _monitors_ranked()
            mon = 0
            for i, m in enumerate(mons):
                if tuple(m["rect"]) == mrect:
                    mon = _mon_output_idx(m, i)
                    break
            cx, cy = max(x, mrect[0]), max(y, mrect[1])
            cw = min(x + w, mrect[2]) - cx
            ch = min(y + hh, mrect[3]) - cy
            ox, oy = cx - mrect[0], cy - mrect[1]
            ox -= ox % 2
            oy -= oy % 2
            cw -= cw % 8
            ch -= ch % 8
            if cw < 160 or ch < 120:
                return None  # off-screen sliver / splash remnant - not the game
            return {"hwnd": h, "mon": mon, "x": ox, "y": oy, "w": cw, "h": ch}
        finally:
            if oldctx:
                try:
                    user32.SetThreadDpiAwarenessContext(oldctx)
                except Exception:
                    pass
    except Exception:
        return None


def build_video_cmd(out_pattern, start_number=0, monitor_index=None,
                    window_rect=None):
    """Capture the screen and encode it, writing the stream as a sequence of
    short MP4 segments (out_pattern like '.../seg_%06d.mp4'). Segments let us
    (a) concat them into the full session file at the end, (b) grab just the
    last minute on demand for the replay hotkey, and (c) continue numbering
    after a pause - all without re-encoding. start_number is where this run's
    segment numbering begins (so a resumed run doesn't overwrite earlier ones).
    monitor_index overrides which screen to grab; None falls back to settings.
    window_rect=(x, y, w, h) crops the capture AT THE SOURCE to the game's
    window (monitor-relative, from _game_window_rect): the same GPU
    duplication capture, so zero-copy encoding and HDR keep working - unlike
    the old gdigrab path, which returned black frames for modern games."""
    s = SETTINGS
    enc = _current_encoder()
    br = s["bitrate_mbps"]
    safe = _ENC_SAFE[0]
    mon = monitor_index if monitor_index is not None else s.get("monitor_index", 0)
    try:
        mon = int(mon)
    except Exception:
        mon = 0
    if mon < 0:
        mon = 0   # "Auto" records the primary screen (output 0) - simple and reliable
    # Never ask ddagrab for a screen that doesn't exist (a stale saved index, or a
    # monitor that was unplugged) - clamp to the real screen count so capture still
    # starts on a valid output instead of failing outright.
    mon = min(mon, _active_monitor_count() - 1)
    grab = f"ddagrab=output_idx={mon}:framerate={s['framerate']}"
    if window_rect:
        x, y, w, h = window_rect
        grab += f":offset_x={x}:offset_y={y}:video_size={w}x{h}"

    hdr_enc_args = []
    hdr_pre_args = []
    strategy = None if _HDR_LEVEL[0] >= 1 else _hdr_strategy()
    if strategy == "native" and not (enc.endswith("_amf") and _enc_supports_10bit(enc)):
        # Only AMF encoders accept the float16 surface (the sole unclipped HDR
        # source - see _hdr_strategy). Everyone else records plain SDR capture:
        # slightly flat on an HDR desktop, but stable and never neon.
        strategy = None
    if strategy == "native":
        # True HDR file: the float16 scRGB surface goes zero-copy into the AMF
        # encoder, which PQ-encodes it (verified bit-exact against PQ maths).
        # The finishing queue converts it to normal SDR right after the session.
        # If the chain yields zero frames, the watcher steps _HDR_LEVEL to plain.
        vf, hdr_enc_args, hdr_pre_args = _hdr_native_args(grab, enc)
        # Give the HDR master a bitrate FLOOR: it lives through one more encode
        # generation (the SDR finishing pass) than a normal recording, so the
        # master must not be the quality bottleneck - the finished file should
        # be bounded by the user's own bitrate. Costs disk only TEMPORARILY:
        # finishing re-encodes at the user's bitrate and replaces this file.
        br = max(int(br), 30)
    elif enc.endswith(("_amf", "_nvenc")) and not safe:
        # AMF and NVENC consume ddagrab's d3d11 frames directly (zero-copy, most
        # efficient). On fragile setups (some 4K AMD combos, hybrid laptops where
        # capture runs on the iGPU and NVENC on the dGPU) this fast path can fail
        # to start - the encoder-died recovery then retries in 'safe' mode below
        # and remembers it, so it self-heals after one lost start, once ever.
        vf = f"{grab}[v]"
    else:
        # NVENC / QSV / software (and AMF in safe mode) take frames in system
        # memory as nv12 - the most compatible path.
        vf = f"{grab},hwdownload,format=bgra,format=nv12[v]"

    seg = max(2, int(s.get("segment_seconds", 4)))
    fps = int(s["framerate"])
    gop = max(1, fps * seg)
    # Force a keyframe on each segment boundary so cuts land on time. Some
    # encoders choke on the expression form, so safe mode relies on -g alone.
    keyframes = [] if safe else ["-force_key_frames", f"expr:gte(t,n_forced*{seg})"]
    # Safe mode also drops encoder-specific tuning (-quality/-preset/-rc), which
    # can be rejected by some driver/ffmpeg combos, for plain CBR.
    rc = (["-b:v", f"{br}M", "-maxrate", f"{br}M", "-bufsize", f"{br * 2}M"]
          if safe else encoder_quality_flags(enc, br))
    tail = [
        "-c:v", enc,
        *rc,
        *hdr_enc_args,                 # 10-bit depth + PQ/BT.2020 bitstream tags
        "-g", str(gop), *keyframes,
        # MP4 segments work for AV1 / HEVC / H.264 alike (MPEG-TS can't carry
        # AV1, which is what AMD GPUs pick by default - that broke saving).
        # hybrid_fragmented (2.0): each segment is written as a fragmented
        # file and converted to plain MP4 when it closes - a hard crash or
        # power cut mid-segment now loses NOTHING (the tail segment stays a
        # valid fMP4 the salvage weld reads normally). Finished segments are
        # byte-identical plain MP4s, so nothing downstream changes.
        "-f", "segment", "-segment_time", str(seg),
        "-segment_format", "mp4", "-reset_timestamps", "1",
        "-segment_format_options", "movflags=+hybrid_fragmented",
        "-segment_start_number", str(int(start_number)),
        out_pattern,
    ]
    return [
        s["ffmpeg_path"], "-y", "-hide_banner", "-loglevel", "error", "-stats",
        *hdr_pre_args,                 # shared d3d11 device (float16 HDR capture only)
        "-filter_complex", vf,
        "-map", "[v]",
        *tail,
    ]


def build_wgc_cmd(w, h, fps, out_pattern, start_number=0):
    """ffmpeg tail for the WGC (Windows Graphics Capture) transport: raw
    BGRA frames arrive on stdin from _WGCFeed and everything downstream -
    encoder flags, GOP, keyframes, 4s MP4 segments - matches
    build_video_cmd exactly, so replay clips, pause/resume and the save
    pipeline never know which transport recorded the footage. bgr0 goes
    STRAIGHT into the AMF encoder (it accepts RGB natively) - the
    BGRA->NV12 conversion happens on the GPU, not in Python or swscale."""
    s = SETTINGS
    enc = _current_encoder()
    br = s["bitrate_mbps"]
    safe = _ENC_SAFE[0]
    seg = max(2, int(s.get("segment_seconds", 4)))
    gop = max(1, fps * seg)
    keyframes = [] if safe else ["-force_key_frames", f"expr:gte(t,n_forced*{seg})"]
    rc = (["-b:v", f"{br}M", "-maxrate", f"{br}M", "-bufsize", f"{br * 2}M"]
          if safe else encoder_quality_flags(enc, br))
    return [
        s["ffmpeg_path"], "-y", "-hide_banner", "-loglevel", "error", "-stats",
        "-f", "rawvideo", "-pixel_format", "bgr0",
        "-video_size", f"{w}x{h}", "-framerate", str(fps),
        # WHY THE AUDIO USED TO DRIFT. rawvideo carries no timestamps, so
        # ffmpeg stamped frame N at exactly N/fps - the rate we ASKED for.
        # The audio is captured separately against the wall clock. So any
        # stretch where the window did not actually deliver 60 fps made the
        # picture's clock run slow while the sound's kept real time, and the
        # two slid apart for the rest of the recording. Measured on a real
        # session: 58.9 fps delivered, 5.4 seconds adrift by the end.
        # Wall-clock stamps in, constant rate out: frames are timed by when
        # they ARRIVED, then resampled to an exactly-60fps output so the
        # segment weld still has one unchanging frame rate to copy.
        "-use_wallclock_as_timestamps", "1",
        "-i", "pipe:0",
        "-fps_mode", "cfr", "-r", str(fps),
        "-c:v", enc, *rc,
        "-g", str(gop), *keyframes,
        "-f", "segment", "-segment_time", str(seg),
        "-segment_format", "mp4", "-reset_timestamps", "1",
        "-segment_format_options", "movflags=+hybrid_fragmented",
        "-segment_start_number", str(int(start_number)),
        out_pattern,
    ]


def _frame_black(buf, w, h, stride=8, max_lim=16, mean_lim=2.0):
    """Is this BGRA frame black? A stride-8 sample of the BGR bytes
    (240x135 points at 1080p - any lit block of 8x8 px or more lands at
    least one) must have no byte at or above max_lim AND a mean under
    mean_lim. Both, because a single dark game frame (Devour, Garden
    of Witches: means 0.5-1.7 with maxes over 100) must never pass as
    black, while a limited-range black (Y=16 in the file) decodes to
    0-7 in BGRA and must. A buffer shorter than the frame is never
    black by accident. Measured 0.61 ms at 1080p, 0.86 ms at 1440p."""
    try:
        import numpy as np
        a = np.frombuffer(buf, dtype=np.uint8)
        if a.size < w * h * 4 or w <= 0 or h <= 0:
            return False
        a = a[:w * h * 4].reshape(h, w, 4)[::stride, ::stride, :3]
        return int(a.max()) < max_lim and float(a.mean()) < mean_lim
    except Exception:
        return False


def _root_hwnd(h):
    """The top-level owner of a window handle (GA_ROOT), or the handle
    itself when Windows cannot say."""
    try:
        import ctypes
        r = ctypes.windll.user32.GetAncestor(int(h or 0), 2)
        return int(r or h or 0)
    except Exception:
        return int(h or 0)


def _foreground_root():
    """The root handle of whatever window is in front right now."""
    try:
        import ctypes
        return _root_hwnd(ctypes.windll.user32.GetForegroundWindow())
    except Exception:
        return 0


def _screen_probe(rect):
    """Mean brightness (0-255) of the game window's rect AS THE SCREEN
    SHOWS IT - a GDI StretchBlt of that screen area down to 64x36 - or
    None when the screen could not be read. This is the guard's second
    witness: a black feed under a lit screen means the capture lied; a
    black feed under a black screen is a loading screen or a cutscene
    and nothing is wrong. `rect` is the dict _game_window_rect returns;
    its hwnd is measured afresh here (ClientToScreen under per-monitor
    DPI awareness, the same flip _game_window_rect makes) so the probe
    reads exactly the client area the capture is meant to carry. No
    CAPTUREBLT: layered overlays are not the window. Measured 28 ms at
    1080p, 41 ms at 1440p - called only after ten seconds of black, at
    most every five seconds."""
    try:
        import ctypes
        from ctypes import wintypes
        u = ctypes.windll.user32
        g = ctypes.windll.gdi32
        h = int((rect or {}).get("hwnd") or 0)
        if not h:
            return None
        oldctx = None
        try:
            u.SetThreadDpiAwarenessContext.restype = ctypes.c_void_p
            u.SetThreadDpiAwarenessContext.argtypes = [ctypes.c_void_p]
            oldctx = u.SetThreadDpiAwarenessContext(ctypes.c_void_p(-4))
        except Exception:
            oldctx = None
        try:
            cr = wintypes.RECT()
            pt = wintypes.POINT(0, 0)
            if not u.GetClientRect(h, ctypes.byref(cr)):
                return None
            if not u.ClientToScreen(h, ctypes.byref(pt)):
                return None
            sx, sy = int(pt.x), int(pt.y)
            w, hh = cr.right - cr.left, cr.bottom - cr.top
            if w < 16 or hh < 16:
                return None
            u.GetDC.restype = ctypes.c_void_p
            u.GetDC.argtypes = [ctypes.c_void_p]
            u.ReleaseDC.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            g.CreateCompatibleDC.restype = ctypes.c_void_p
            g.CreateCompatibleDC.argtypes = [ctypes.c_void_p]
            g.CreateDIBSection.restype = ctypes.c_void_p
            g.CreateDIBSection.argtypes = [
                ctypes.c_void_p, ctypes.c_void_p, wintypes.UINT,
                ctypes.POINTER(ctypes.c_void_p), ctypes.c_void_p,
                wintypes.DWORD]
            g.SelectObject.restype = ctypes.c_void_p
            g.SelectObject.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            g.DeleteObject.argtypes = [ctypes.c_void_p]
            g.DeleteDC.argtypes = [ctypes.c_void_p]
            g.SetStretchBltMode.argtypes = [ctypes.c_void_p, ctypes.c_int]
            g.StretchBlt.argtypes = [
                ctypes.c_void_p, ctypes.c_int, ctypes.c_int, ctypes.c_int,
                ctypes.c_int, ctypes.c_void_p, ctypes.c_int, ctypes.c_int,
                ctypes.c_int, ctypes.c_int, wintypes.DWORD]

            class _BIH(ctypes.Structure):
                _fields_ = [("biSize", wintypes.DWORD),
                            ("biWidth", ctypes.c_long),
                            ("biHeight", ctypes.c_long),
                            ("biPlanes", wintypes.WORD),
                            ("biBitCount", wintypes.WORD),
                            ("biCompression", wintypes.DWORD),
                            ("biSizeImage", wintypes.DWORD),
                            ("biXPelsPerMeter", ctypes.c_long),
                            ("biYPelsPerMeter", ctypes.c_long),
                            ("biClrUsed", wintypes.DWORD),
                            ("biClrImportant", wintypes.DWORD)]

            class _BMI(ctypes.Structure):
                _fields_ = [("bmiHeader", _BIH),
                            ("bmiColors", wintypes.DWORD * 3)]

            bmi = _BMI()
            bmi.bmiHeader.biSize = ctypes.sizeof(_BIH)
            bmi.bmiHeader.biWidth = 64
            bmi.bmiHeader.biHeight = -36          # top-down
            bmi.bmiHeader.biPlanes = 1
            bmi.bmiHeader.biBitCount = 32
            bmi.bmiHeader.biCompression = 0      # BI_RGB
            hdc = u.GetDC(None)
            if not hdc:
                return None
            mdc = hbm = old = None
            try:
                mdc = g.CreateCompatibleDC(hdc)
                if not mdc:
                    return None
                bits = ctypes.c_void_p()
                hbm = g.CreateDIBSection(hdc, ctypes.byref(bmi), 0,
                                         ctypes.byref(bits), None, 0)
                if not hbm or not bits.value:
                    return None
                old = g.SelectObject(mdc, hbm)
                g.SetStretchBltMode(mdc, 4)      # HALFTONE
                try:
                    g.SetBrushOrgEx(mdc, 0, 0, None)
                except Exception:
                    pass
                ok = g.StretchBlt(mdc, 0, 0, 64, 36, hdc, sx, sy, w, hh,
                                  0x00CC0020)  # SRCCOPY
                try:
                    g.GdiFlush()
                except Exception:
                    pass
                if not ok:
                    return None
                raw = ctypes.string_at(bits.value, 64 * 36 * 4)
            finally:
                try:
                    if old is not None:
                        g.SelectObject(mdc, old)
                    if hbm:
                        g.DeleteObject(hbm)
                    if mdc:
                        g.DeleteDC(mdc)
                finally:
                    u.ReleaseDC(None, hdc)
            tot = 0
            for i in range(0, len(raw), 4):
                tot += raw[i] + raw[i + 1] + raw[i + 2]
            return tot / float(64 * 36 * 3)
        finally:
            if oldctx:
                try:
                    u.SetThreadDpiAwarenessContext(oldctx)
                except Exception:
                    pass
    except Exception:
        return None


def _client_crop(hwnd, frame_w, frame_h):
    """Where the window's CLIENT area sits inside a WGC frame, in frame
    pixels: (x, y, w, h) - or None if anything looks off.

    The frame is the window's physical surface; GetWindowRect/ClientToScreen
    speak the process's coordinate space, which may be scaled by DPI. Taking
    the ratio between the two removes that difference without needing to know
    the scale factor, and it stays right on a mixed-DPI desktop."""
    try:
        import ctypes
        u = ctypes.windll.user32

        class _R(ctypes.Structure):
            _fields_ = [("l", ctypes.c_long), ("t", ctypes.c_long),
                        ("r", ctypes.c_long), ("b", ctypes.c_long)]

        class _P(ctypes.Structure):
            _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]

        wr, cr, org = _R(), _R(), _P(0, 0)
        if not u.GetWindowRect(hwnd, ctypes.byref(wr)):
            return None
        if not u.GetClientRect(hwnd, ctypes.byref(cr)):
            return None
        if not u.ClientToScreen(hwnd, ctypes.byref(org)):
            return None
        win_w, win_h = wr.r - wr.l, wr.b - wr.t
        cli_w, cli_h = cr.r - cr.l, cr.b - cr.t
        if win_w <= 0 or win_h <= 0 or cli_w <= 0 or cli_h <= 0:
            return None
        sx, sy = frame_w / float(win_w), frame_h / float(win_h)
        x = int(round((org.x - wr.l) * sx))
        y = int(round((org.y - wr.t) * sy))
        w = int(round(cli_w * sx))
        h = int(round(cli_h * sy))
        # a borderless / fullscreen window is all client - nothing to trim
        if x < 0 or y < 0 or w < 16 or h < 16:
            return None
        if x + w > frame_w or y + h > frame_h:
            return None
        return x, y, w, h
    except Exception:
        return None


class _WGCFeed:
    """Windows Graphics Capture -> ffmpeg stdin. The WINDOW ITSELF is the
    source (not a screen region), which is the 2.0 upgrade: overlays,
    popups and Discord toasts physically cannot appear in the recording,
    the feed follows the window wherever it moves, and alt-tab doesn't
    kill anything - WGC keeps compositing an occluded window.

    WGC only delivers frames when the window CHANGES, so a paused game
    would starve the encoder; a 60Hz ticker therefore re-sends the last
    frame whenever no fresh one arrived (constant frame rate, segment
    maths stay exact). One write per frame on a raw (bufsize=0) pipe -
    the single-syscall pattern the pipe can sustain at 2560x1440@60
    (measured 90fps headroom on this machine).

    A frame arriving at a DIFFERENT size means the window was resized:
    feeding it would corrupt the raw stream, so the feed stops cleanly
    and the watcher's existing resize law (split the chapter) takes over."""

    def __init__(self, hwnd, fps):
        self.w = self.h = 0               # aligned encode size (first frame,
        self.fps = fps                    # width mod-8 / height even)
        self._raw_w = self._raw_h = 0     # the window's true physical size
        self._ox = self._oy = 0           # client-area origin inside the frame
        self.stdin = None
        self.size_changed = False
        self.dead = False
        self.frames_in = 0
        self.frames_out = 0
        self._last = None                 # latest BGRA bytes (owned copy)
        self._lock = threading.Lock()
        self._stopev = threading.Event()
        self._first = threading.Event()
        self._ctl = None
        self._ticker_t = None
        self.hwnd = int(hwnd)
        self._crop = None                 # (x, y, w, h) of the CLIENT area
        # THE BLACK CLOCK (3.32). Read by _black_track on the watcher beat.
        self.black_since = None           # wall time the black run began
        self.black_n = 0                  # black samples in that run
        self.lit_at = 0.0                 # last sample that had a picture
        self.seen_in = 0                  # frames_in at the last sample
        self.stalled_since = None         # frames_in stopped moving here
        self.sampler_dead = False         # the sampler raised: it is off
        self._tick_n = 0
        from windows_capture import WindowsCapture
        # draw_border=False removes the yellow highlight Windows paints around
        # a captured window - it is part of the composed surface, so it lands
        # IN the recording. Older Windows builds don't accept the argument.
        try:
            cap = WindowsCapture(cursor_capture=False, draw_border=False,
                                 window_hwnd=self.hwnd)
        except Exception:
            cap = WindowsCapture(cursor_capture=False, window_hwnd=self.hwnd)
        feed = self

        @cap.event
        def on_frame_arrived(frame, capture_control):
            if feed._stopev.is_set():
                try:
                    capture_control.stop()
                except Exception:
                    pass
                return
            if not feed._first.is_set():
                feed._raw_w, feed._raw_h = frame.width, frame.height
                # WGC hands back the WHOLE window - title bar, buttons and
                # frame included (measured: 39px of chrome above the client
                # area). A game recording wants the game, so crop to the
                # client area; that also takes the window's outer edge with
                # it. Falls back to the full frame if the maths look wrong.
                feed._crop = _client_crop(feed.hwnd, frame.width, frame.height)
                cx, cy, cw, ch = (feed._crop if feed._crop
                                  else (0, 0, frame.width, frame.height))
                # the SAME alignment law as every other capture path: width
                # mod-8, height even - AMF pads odd sizes up and the padding
                # columns would appear as a garbage stripe in the video
                feed.w = cw - (cw % 8)
                feed.h = ch - (ch % 2)
                feed._ox, feed._oy = cx, cy
                buf = frame.frame_buffer[cy:cy + feed.h,
                                         cx:cx + feed.w].tobytes()
                with feed._lock:
                    feed._last = buf
                feed.frames_in += 1
                feed._first.set()
                return
            if frame.width != feed._raw_w or frame.height != feed._raw_h:
                feed.size_changed = True      # resize: the raw stream is over
                feed._stopev.set()
                return
            buf = frame.frame_buffer[feed._oy:feed._oy + feed.h,
                                     feed._ox:feed._ox + feed.w].tobytes()
            with feed._lock:
                feed._last = buf
            feed.frames_in += 1

        @cap.event
        def on_closed():
            feed.dead = True                     # window destroyed (game exit)
            feed._stopev.set()
        self._cap = cap

    def begin(self, timeout=2.5):
        """Start capturing; block until the first frame reveals the true
        frame size. None on timeout (exclusive-fullscreen windows can be
        invisible to WGC) - the caller then falls back to ddagrab."""
        self._ctl = self._cap.start_free_threaded()
        if not self._first.wait(timeout=timeout):
            self.stop()
            return None
        return (self.w, self.h)

    def attach(self, stdin):
        self.stdin = stdin
        t = threading.Thread(target=self._ticker, daemon=True)
        t.start()
        self._ticker_t = t

    def _ticker(self):
        period = 1.0 / self.fps
        nxt = time.perf_counter()
        while not self._stopev.is_set():
            nxt += period
            delay = nxt - time.perf_counter()
            if delay > 0:
                time.sleep(delay)
            else:
                nxt = time.perf_counter()        # fell behind: re-anchor
            with self._lock:
                buf = self._last
            if buf is None:
                continue                          # nothing captured yet
            try:
                self.stdin.write(buf)             # ONE WriteFile, GIL released
                self.frames_out += 1
            except Exception:
                self.dead = True                  # encoder went away
                break
            # every 30th write (2 Hz at 60 fps): is what ffmpeg just got a
            # picture at all? This is the one place that sees every frame
            # the encoder receives, including the re-sent frame of a feed
            # that has gone quiet - on_frame_arrived never fires then.
            self._tick_n += 1
            if self._tick_n % 30 == 0 and not self.sampler_dead:
                self._sample(buf, time.time())
        try:
            self.stdin.close()                    # EOF -> ffmpeg finalises
        except Exception:
            pass

    def _sample(self, buf, now):
        """One luma sample of the frame just sent: keep the black clock
        and the stall clock. Never raises - a sampler failure turns the
        sampler off and the write loop carries on exactly as before."""
        try:
            if self.sampler_dead:
                return
            if _frame_black(buf, self.w, self.h):
                if self.black_since is None:
                    self.black_since = now
                    self.black_n = 0
                self.black_n += 1
            else:
                self.black_since = None
                self.lit_at = now
            if self.frames_in == self.seen_in:
                if self.stalled_since is None:
                    self.stalled_since = now
            else:
                self.stalled_since = None
                self.seen_in = self.frames_in
        except Exception:
            self.sampler_dead = True          # never touch the write loop

    def stop(self):
        self._stopev.set()
        try:
            if self._ctl is not None:
                self._ctl.stop()
        except Exception:
            pass
        try:
            if self._ticker_t is not None:
                self._ticker_t.join(timeout=3)
        except Exception:
            pass


def _wgc_available():
    try:
        import windows_capture  # noqa: F401
        return True
    except Exception:
        return False


# GAMES WHOSE WINDOW CAPTURE LIED TONIGHT: {game exe, lower: wall time}.
# Sticky for the night (12 h) so a 'restart' - which builds a fresh
# Session - and every later run of that game take the screen-region
# path; cleared when the capture_backend setting changes.
_WGC_BLACK = {}
_WGC_BLACK_TTL = 12 * 3600.0


def _wgc_black_banned(game, now=None):
    """Did this game's window give only black frames earlier tonight?"""
    try:
        t = _WGC_BLACK.get((game or "").lower())
        if not t:
            return False
        return ((now if now is not None else time.time()) - float(t)
                < _WGC_BLACK_TTL)
    except Exception:
        return False


_SPIN_CACHE = {}


def _drive_has_seek_penalty(path):
    """True if `path` lives on a SPINNING disk, False for solid state, None
    when it cannot be told. Asks the volume itself via the storage device's
    seek-penalty property - no WMI, no admin rights."""
    try:
        root = os.path.splitdrive(os.path.abspath(path))[0].upper()
        if not root:
            return None
        if root in _SPIN_CACHE:
            return _SPIN_CACHE[root]
        import ctypes
        from ctypes import wintypes
        GENERIC_READ = 0            # query-only: no rights needed, so this
        OPEN_EXISTING = 3           # works without running as administrator
        IOCTL = 0x2D1400            # IOCTL_STORAGE_QUERY_PROPERTY

        class STORAGE_PROPERTY_QUERY(ctypes.Structure):
            _fields_ = [("PropertyId", wintypes.DWORD),
                        ("QueryType", wintypes.DWORD),
                        ("AdditionalParameters", ctypes.c_byte * 1)]

        class DEVICE_SEEK_PENALTY_DESCRIPTOR(ctypes.Structure):
            _fields_ = [("Version", wintypes.DWORD),
                        ("Size", wintypes.DWORD),
                        ("IncursSeekPenalty", ctypes.c_byte)]

        h = ctypes.windll.kernel32.CreateFileW(
            rf"\\.\{root}", GENERIC_READ, 3, None, OPEN_EXISTING, 0, None)
        if h == -1 or h == ctypes.c_void_p(-1).value:
            return None
        try:
            q = STORAGE_PROPERTY_QUERY(7, 0, (ctypes.c_byte * 1)())  # SeekPenalty
            d = DEVICE_SEEK_PENALTY_DESCRIPTOR()
            got = wintypes.DWORD()
            ok = ctypes.windll.kernel32.DeviceIoControl(
                h, IOCTL, ctypes.byref(q), ctypes.sizeof(q),
                ctypes.byref(d), ctypes.sizeof(d), ctypes.byref(got), None)
            res = bool(d.IncursSeekPenalty) if ok else None
        finally:
            ctypes.windll.kernel32.CloseHandle(h)
        _SPIN_CACHE[root] = res
        return res
    except Exception:
        return None


def _free_bytes(path):
    try:
        return shutil.disk_usage(path).free
    except Exception:
        return 0


def _work_dir():
    """A SINGLE hidden parent folder for in-progress capture scratch (segments
    + wavs).

    It used to live beside the recordings "so the final assemble is a fast
    local read". On a spinning library drive that reasoning is backwards: the
    save then READS the segments and WRITES the finished file through the same
    head, and a paused session is welded twice (segments -> one file per run ->
    one final file), so a 48 GB recording moves about 240 GB through one disk.
    Measured on this machine: 16-27 MB/s.

    So when the library is on a spinning disk and a solid-state drive has room,
    the scratch goes THERE: the save becomes a fast read plus one clean
    sequential write, with no head fighting itself. 'scratch_dir' overrides."""
    out = SETTINGS.get("output_dir", "") or _data_dir()
    want = str(SETTINGS.get("scratch_dir", "auto") or "auto").strip()
    if want and want.lower() != "auto":
        d = os.path.join(want, ".lore_cache")
        try:
            os.makedirs(d, exist_ok=True)
            return d
        except Exception:
            pass                      # unreachable drive: fall through to auto
    elif _drive_has_seek_penalty(out) is True:
        best, best_free = None, 0
        for cand in _scratch_candidates():
            if _drive_has_seek_penalty(cand) is not False:
                continue              # only trust a KNOWN solid-state drive
            free = _free_bytes(cand)
            # a long session needs the segments AND the per-run welds at once
            if free > best_free and free >= 120 * (1 << 30):
                best, best_free = cand, free
        if best:
            d = os.path.join(best, ".lore_cache")
            try:
                os.makedirs(d, exist_ok=True)
                return d
            except Exception:
                pass
    d = os.path.join(out, ".lore_cache")
    try:
        os.makedirs(d, exist_ok=True)
    except Exception:
        d = os.path.join(_data_dir(), ".lore_cache")
        os.makedirs(d, exist_ok=True)
    return d


def _work_dirs_all():
    """Every folder that could be holding in-progress footage: the scratch in
    use now PLUS the legacy one beside the library. Moving the scratch to a
    solid state drive must never strand a crashed session's segments on the
    old drive - salvage and sweeping both walk this list."""
    seen, out = set(), []
    for d in (_work_dir(),
              os.path.join(SETTINGS.get("output_dir", "") or _data_dir(),
                           ".lore_cache"),
              os.path.join(_data_dir(), ".lore_cache")):
        k = os.path.normcase(os.path.abspath(d))
        if k in seen or not os.path.isdir(d):
            continue
        seen.add(k)
        out.append(d)
    return out


def _scratch_candidates():
    """Fixed local drive roots that could host the scratch folder, best first."""
    out = []
    if os.name != "nt":
        return out
    try:
        import ctypes
        bits = ctypes.windll.kernel32.GetLogicalDrives()
        for i in range(26):
            if not (bits >> i) & 1:
                continue
            root = f"{chr(65 + i)}:\\"
            # 3 == DRIVE_FIXED: never a USB stick or a network share
            if ctypes.windll.kernel32.GetDriveTypeW(root) != 3:
                continue
            out.append(root)
    except Exception:
        return []
    out.sort(key=lambda r: -_free_bytes(r))
    return out


def _already_saved(base):
    """Is '<base>.mp4' already in the library - on ANY shelf?

    Salvage used to ask only whether output_dir/<base>.mp4 existed. Real
    recordings live at output_dir/<Game>/Videos/<base>.mp4, so the answer was
    always no, and every launch rebuilt sessions that had finished weeks ago:
    a half-hour concat per orphan, timing out, holding its temp open, blocking
    its own promote, and leaving tens of gigabytes of duplicate welds behind.
    Three of the five stuck files on this machine were already saved."""
    want = (base + ".mp4").lower()
    out = SETTINGS.get("output_dir", "") or ""
    try:
        if os.path.isfile(os.path.join(out, base + ".mp4")):
            return True
        for d, _kind in _library_dirs(out):
            try:
                for fn in os.listdir(d):
                    if fn.lower() == want:
                        return True
            except OSError:
                continue
    except Exception:
        pass
    return False


def _salvage_skip(d):
    return os.path.isfile(os.path.join(d, "_discarded.flag"))


def _salvage_interrupted():
    """A previous run died mid-save (force-kill, crash, power cut). NEVER
    just sweep its remains - they are the user's footage:
      * '<name>.mp4.__assembling__.mp4' whose weld actually FINISHED (it
        probes to a real duration) only missed its final rename - promote it
        into the library.
      * a session folder still holding seg_*.mp4 gets a best-effort re-weld:
        video concat + whatever audio the run captured, muxed from zero.
        (The wall-clock anchors died with the process, so sync is within a
        few hundred ms - imperfect footage beats deleted footage.)
    Anything truly unreadable is parked in .lore_cache\\lost, never deleted.
    Born of a real loss: a 69-minute session was welding when the process
    was killed, and the next boot swept its segments."""
    out = SETTINGS.get("output_dir", "")
    if not out or not os.path.isdir(out):
        return
    ff = SETTINGS.get("ffmpeg_path") or "ffmpeg"
    lost = os.path.join(_work_dir(), "lost")

    def _fresh(path):
        # younger than a minute = something LIVE is writing it, not a corpse
        try:
            return time.time() - os.path.getmtime(path) < 60
        except Exception:
            return True
    # 1) finished-but-unrenamed assemblies. Scan the library root AND every
    #    per-game shelf (<Game>/Videos, <Game>/Clips): real recordings assemble
    #    INSIDE their shelf, so a root-only scan left a completed weld orphaned
    #    forever - the exact bug that stranded a finished session as a stuck
    #    '.__assembling__.mp4' the app never recovered.
    scan_dirs = {out}
    try:
        for _d, _kind in _library_dirs(out):
            scan_dirs.add(_d)
    except Exception:
        pass
    for d in scan_dirs:
        try:
            entries = list(os.listdir(d))
        except Exception:
            continue
        for name in entries:
            if not name.endswith(".__assembling__.mp4"):
                continue
            p = os.path.join(d, name)
            if _fresh(p):
                continue
            final = os.path.join(d, name[:-len(".__assembling__.mp4")])
            try:
                base0 = os.path.splitext(os.path.basename(final))[0]
                if _already_saved(base0):
                    os.remove(p)         # a duplicate of a shelved recording
                    log(f"Cleared a duplicate rebuild: {name}")
                    continue
                if (_probe_duration(p) or 0) > 1.0 and not os.path.exists(final):
                    os.replace(p, final)
                    _record_made_file(final)
                    log("Recovered an interrupted save: "
                        + os.path.basename(final))
                else:
                    os.makedirs(lost, exist_ok=True)
                    os.replace(p, os.path.join(lost, name))
                    log("An interrupted save could not be read; parked in "
                        ".lore_cache\\lost: " + name)
            except Exception as e:
                log(f"Salvage skipped for {name}: {e}")
    # 2) orphaned session folders with real segments -> best-effort weld
    for cache in _work_dirs_all():
      try:
        for name in list(os.listdir(cache)):
            d = os.path.join(cache, name)
            if not os.path.isdir(d) or name == "lost":
                continue
            if _salvage_skip(d):
                # HE THREW THIS ONE AWAY. The tombstone goes down before the
                # discard starts; welding these segments back into a video
                # would resurrect a recording he explicitly binned.
                shutil.rmtree(d, ignore_errors=True)
                continue
            # A weld that already finished is sitting right there. Re-running
            # it costs half an hour of disk, times out, holds the file open,
            # and blocks the promote that would have finished the job - every
            # single launch. Look before rebuilding.
            try:
                done = os.path.join(out, name + ".mp4.__assembling__.mp4")
                fin = os.path.join(out, name + ".mp4")
                if _already_saved(name):
                    # finished long ago and shelved - the leftovers are just
                    # leftovers. Clear them instead of rebuilding the film.
                    for junk in (done, os.path.join(out, name + ".mp4.__tmp.mp4")):
                        try:
                            if os.path.isfile(junk):
                                sz = os.path.getsize(junk)
                                os.remove(junk)
                                log(f"Cleared a duplicate rebuild of {name} "
                                    f"({sz / (1 << 30):.1f} GB) - it was saved "
                                    f"already.")
                        except OSError:
                            pass
                    shutil.rmtree(d, ignore_errors=True)
                    continue
                if os.path.isfile(done) and (_probe_duration(done) or 0) > 1.0:
                    os.replace(done, fin)
                    _record_made_file(fin)
                    log(f"Recovered an interrupted save: {name}.mp4")
                    continue
            except Exception:
                pass
            # and a folder that has already refused twice is not going to
            # start working on the third launch - leave it for the sweep
            if _SALVAGE_FAILS.get(name, 0) >= 2:
                continue
            segs = _list_segments(d)
            if not segs or _fresh(segs[-1]):
                continue
            final = os.path.join(out, name + ".mp4")
            if os.path.exists(final):
                final = os.path.join(out, name + "_recovered.mp4")
            tmp = final + ".__assembling__.mp4"
            try:
                # WAVs are tagged per RUN (system_00/mic_00, system_01/...):
                # a session that auto-paused even once has 2+ runs, and the
                # old blind sorted()[:2] then amixed mic_00 with mic_01 -
                # two mic tracks, game audio discarded. Group by KIND in run
                # order: runs are sequential in time exactly like the video
                # segments, so same-kind WAVs concat, then the kinds amix.
                allw = sorted(w for w in os.listdir(d)
                              if w.endswith(".wav")
                              and os.path.getsize(os.path.join(d, w)) > 64_000)
                sysw = [os.path.join(d, w) for w in allw if w.startswith("system")]
                micw = [os.path.join(d, w) for w in allw if w.startswith("mic")]
                if not sysw and not micw:      # unexpected names: best effort
                    sysw = [os.path.join(d, w) for w in allw[:1]]
                lst = os.path.join(d, "concat.txt")
                with open(lst, "w", encoding="utf-8") as fh:
                    for s in segs:
                        fh.write("file '" + s.replace("'", "'\\''") + "'\n")
                cmd = [ff, "-y", "-hide_banner", "-loglevel", "error",
                       "-f", "concat", "-safe", "0", "-i", lst]
                for w in sysw + micw:
                    cmd += ["-i", w]
                cmd += ["-map", "0:v", "-c:v", "copy"]
                if sysw or micw:
                    fg, k = [], 1
                    if len(sysw) > 1:
                        fg.append("".join(f"[{k + i}:a]" for i in range(len(sysw)))
                                  + f"concat=n={len(sysw)}:v=0:a=1[sa]")
                    elif sysw:
                        fg.append(f"[{k}:a]anull[sa]")
                    k += len(sysw)
                    if len(micw) > 1:
                        fg.append("".join(f"[{k + i}:a]" for i in range(len(micw)))
                                  + f"concat=n={len(micw)}:v=0:a=1[ma]")
                    elif micw:
                        fg.append(f"[{k}:a]anull[ma]")
                    if sysw and micw:
                        fg.append("[sa][ma]amix=inputs=2:duration=longest[a]")
                        out_lbl = "[a]"
                    else:
                        out_lbl = "[sa]" if sysw else "[ma]"
                    cmd += ["-filter_complex", ";".join(fg), "-map", out_lbl]
                    cmd += ["-c:a", "aac", "-b:a", "192k"]
                cmd += ["-movflags", "+faststart", tmp]
                flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
                r = subprocess.run(cmd, stdout=subprocess.DEVNULL,
                                   stderr=subprocess.PIPE, creationflags=flags,
                                   timeout=1800)
                if r.returncode == 0 and os.path.isfile(tmp) \
                        and os.path.getsize(tmp) > 100_000:
                    os.replace(tmp, final)
                    _record_made_file(final)
                    log("Recovered an interrupted recording: "
                        + os.path.basename(final))
                    shutil.rmtree(d, ignore_errors=True)
                else:
                    for ln in (r.stderr or b"").decode("utf-8", "ignore") \
                            .splitlines()[-2:]:
                        log("  ffmpeg(salvage): " + ln)
                    os.makedirs(lost, exist_ok=True)
                    os.replace(d, os.path.join(lost, name))
                    log("Couldn't re-weld a leftover session; parked in "
                        ".lore_cache\\lost: " + name)
            except Exception as e:
                log(f"Salvage failed for {name}: {e}")
                try:
                    if os.path.isfile(tmp):
                        os.remove(tmp)
                except Exception:
                    pass
      except Exception as e:
        # one unreadable cache dir (AV lock, degraded volume) used to abort
        # the WHOLE walk in silence, deferring every remaining rescue
        log(f"Salvage stopped early in {cache}: {e} - its remaining "
            "leftovers wait for the next launch.")


def _migrate_library_layout():
    """One-time (and self-healing) shelving: move flat legacy recordings into
    per-game folders - <Game>/Videos and <Game>/Clips - and keep the storage
    manifest, finish queue and cached thumbnails pointing at the moved files.
    Skips anything younger than 3 minutes (it may still be being written)."""
    out = SETTINGS.get("output_dir", "")
    if not out or not os.path.isdir(out):
        return
    remap = {}

    def _shelve(src_dir, kind):
        if not os.path.isdir(src_dir):
            return
        for f in list(os.listdir(src_dir)):
            p = os.path.join(src_dir, f)
            try:
                if (not os.path.isfile(p) or not f.lower().endswith(".mp4")
                        or ".__" in f or f.startswith(".")):
                    continue
                if time.time() - os.path.getmtime(p) < 180:
                    continue
                base = _parse_clip_name(f)
                nd = _game_shelf(base, kind)
                np = os.path.join(nd, f)
                if os.path.abspath(np) == os.path.abspath(p) or os.path.exists(np):
                    continue
                os.rename(p, np)
                remap[os.path.normcase(os.path.abspath(p))] = np
                # thumbnails already live in ONE root cache keyed by the
                # (unique) filename, so a moved recording keeps its thumb -
                # nothing to relocate.
            except Exception as e:
                log(f"shelving skipped {f}: {e}")
    _shelve(out, "session")
    _shelve(os.path.join(out, "Clips"), "clip")
    # SELF-HEAL stale records: if something else moved files onto their
    # shelves (a helper, a hand), manifest/queue entries still pointing at
    # the old flat spots are re-aimed at wherever the file actually lives.
    try:
        with _MANIFEST_LOCK:
            paths, _ = _load_manifest()
            if paths is None:
                raise OSError("manifest unreadable")
            healed = set()
            changed = False
            for p in paths:
                if os.path.isfile(p):
                    healed.add(p)
                    continue
                bn = os.path.basename(p)
                kind = "clip" if ("_clip_" in bn or "_cut_" in bn) else "session"
                cand = os.path.join(_game_shelf(_parse_clip_name(bn), kind,
                                                make=False), bn)
                if os.path.isfile(cand):
                    healed.add(os.path.normcase(os.path.abspath(cand)))
                    changed = True
                else:
                    healed.add(p)
            if changed:
                _save_manifest(healed)
                log("Re-aimed ownership records at the shelved files.")
    except Exception:
        pass
    try:
        q = _load_finish_queue(strict=True)
        qchanged = False
        for it in q:
            fp = it.get("path", "")
            if fp and not os.path.isfile(fp):
                bn = os.path.basename(fp)
                cand = os.path.join(_game_shelf(_parse_clip_name(bn),
                                                "session", make=False), bn)
                if os.path.isfile(cand):
                    it["path"] = os.path.abspath(cand)
                    qchanged = True
        if qchanged:
            _save_finish_queue(q)
    except Exception:
        pass
    if not remap:
        return
    log(f"Shelved {len(remap)} recordings into per-game folders.")
    # ownership manifest follows the files
    try:
        with _MANIFEST_LOCK:
            paths, _ = _load_manifest()
            if paths is None:
                raise OSError("manifest unreadable")
            changed = False
            for old_p, new_p in remap.items():
                if old_p in paths:
                    paths.discard(old_p)
                    paths.add(os.path.normcase(os.path.abspath(new_p)))
                    changed = True
            if changed:
                _save_manifest(paths)
    except Exception:
        pass
    # pending HDR restorations follow too
    try:
        q = _load_finish_queue(strict=True)
        changed = False
        for it in q:
            k = os.path.normcase(os.path.abspath(it.get("path", "")))
            if k in remap:
                it["path"] = os.path.abspath(remap[k])
                changed = True
        if changed:
            _save_finish_queue(q)
    except Exception:
        pass


def _sweep_orphan_temp():
    """Tidy TRUE leftovers from previous runs - but salvage runs FIRST, and
    on its OWN thread: a rescue weld can take minutes of ffmpeg, and the
    watcher must never wait on it (a recorder that boots late records
    late). What's swept here synchronously is only empty scratch, legacy
    '.tmp_*' litter and half-written SDR conversions (whose HDR originals
    still exist untouched)."""
    def _salvage_guarded():
        try:
            _salvage_interrupted()
        except Exception as e:
            log(f"Salvage crashed: {e} - leftovers wait for the next launch.")
    threading.Thread(target=_salvage_guarded, daemon=True).start()
    removed = 0
    try:
      now0 = time.time()
      for cache in _work_dirs_all():
        for name in os.listdir(cache):
            if name == "lost":
                continue          # parked salvage evidence - never touch
            p = os.path.join(cache, name)
            if os.path.isdir(p) and not _list_segments(p):
                shutil.rmtree(p, ignore_errors=True)
                removed += 1
            # transcription scratch is written HERE, not in the library - the
            # old sweep looked for it beside the videos and never found it
            # the reader's output is '<wav>.json', i.e. 'stt_..._....wav.json'
            # - it does not end '_out.json', so the old test never matched it
            # and a kill between the reader finishing and the cleanup running
            # left one behind for good. Any stt_ scratch, either extension.
            elif (os.path.isfile(p)
                    and (name.startswith("stt_")
                         or name.startswith("laugh_"))
                    and name.rsplit(".", 1)[-1] in
                    ("wav", "json", "ctl", "prog", "tmp")):
                try:
                    if now0 - os.path.getmtime(p) > 600:
                        os.remove(p)
                        removed += 1
                except OSError:
                    pass
    except Exception:
        pass
    # legacy location: '.tmp_<game>_<stamp>' folders directly in the output dir
    try:
        out = SETTINGS.get("output_dir", "")
        if out and os.path.isdir(out):
            for name in os.listdir(out):
                if name.startswith(".tmp_"):
                    p = os.path.join(out, name)
                    if os.path.isdir(p):
                        shutil.rmtree(p, ignore_errors=True)
                        removed += 1
    except Exception:
        pass
    # half-written work temps from a crash/kill: '<name>.mp4.__sdr__.mp4'
    # (conversion) and '<base>_cut_<stamp>.__tmp.mp4' (trim). The temps live on
    # the per-game SHELVES now, not just the flat legacy dirs - sweep every
    # folder a recording can live in (the same single source of truth the
    # scanner uses), and only LORE's own '.__' work names, nothing else.
    # Age-gate 10 minutes so a temp a LIVE worker is writing right now survives.
    try:
        out = SETTINGS.get("output_dir", "")
        dirs = [d for d, _k in _library_dirs(out)] if out else []
        now = time.time()
        for d in dirs:
            if os.path.isdir(d):
                for name in os.listdir(d):
                    if ".__sdr__." in name or ".__tmp" in name \
                            or (name.startswith("stt_")
                                and (name.endswith(".wav")
                                     or name.endswith("_out.json"))):
                        p = os.path.join(d, name)
                        try:
                            if now - os.path.getmtime(p) > 600:
                                os.remove(p)
                                removed += 1
                        except Exception:
                            pass
    except Exception:
        pass
    if removed:
        log(f"Cleaned up {removed} leftover temp folder(s) from a previous run.")


def _clip_in_flight(session):
    """Is a 'save the last minute' clip being assembled right now?

    save_replay holds this lock for the whole build, and every intermediate it
    writes lives in the folder discard() deletes."""
    lk = getattr(session, "_replay_lock", None)
    if lk is None:
        return False
    if lk.acquire(blocking=False):
        lk.release()
        return False
    return True


def _discard_soon(session):
    """Throw the recording away - but not while a clip is still being written
    into the same folder. Off the watch loop, which must keep detecting
    games while we wait.

    The tombstone goes down FIRST: if the app dies before the discard
    finishes, the boot salvage would otherwise re-weld the surviving
    segments into a finished video - resurrecting a recording that was
    explicitly thrown away."""
    try:
        with open(os.path.join(session.tmp, "_discarded.flag"), "w") as fh:
            fh.write("1")
    except Exception:
        pass

    def work():
        for _ in range(900):                 # up to ~90s, then give up waiting
            if not _clip_in_flight(session):
                break
            time.sleep(0.1)
        try:
            session.discard()
        except Exception as e:
            log(f"Could not discard the recording: {e}")
    threading.Thread(target=work, daemon=True).start()


def _fmt_secs(n):
    n = int(n or 0)
    if n < 60:
        return f"{n} second" + ("" if n == 1 else "s")
    m, sec = divmod(n, 60)
    return f"{m}m {sec:02d}s"


def _captured_seconds(session):
    """Seconds of footage actually on disk for this session.

    Counted from the segments, not the clock: a session paused for an hour has
    an hour of wall time and none of it is footage."""
    try:
        seg = max(2, int(SETTINGS.get("segment_seconds", 4)))
        return len(_list_segments(session.tmp)) * seg
    except Exception:
        return 0


def _not_worth_keeping(session, manual):
    """A game opened and closed again straight away.

    Only ever asked about a recording that ended BY ITSELF. If you pressed
    record, or pressed stop, you meant it - length is none of our business."""
    if manual:
        return False
    lim = int(SETTINGS.get("min_keep_seconds", 45) or 0)
    if lim <= 0:
        return False
    if _clip_in_flight(session) or getattr(session, "_clip_saved", False):
        return False          # you asked for something out of this one
    return _captured_seconds(session) < lim


def _list_segments(seg_dir):
    """All finished+current capture segments in order (oldest -> newest)."""
    try:
        names = [f for f in os.listdir(seg_dir)
                 if f.startswith("seg_") and f.endswith(".mp4")]
    except Exception:
        return []
    return [os.path.join(seg_dir, f) for f in sorted(names)]


def _watch_concat_progress(out_path, want_bytes):
    """Publish a stream-copy's progress by watching the output file grow.
    ffmpeg's -progress needs a decode pipeline to report against; a pure
    `-c copy` concat has none, but the file size IS the progress."""
    _CONCAT_WATCH["stop"] = True          # retire any previous watcher
    if want_bytes <= 0:
        return
    stop = threading.Event()
    _CONCAT_WATCH["stop"] = False
    _CONCAT_WATCH["ev"] = stop
    name = os.path.basename(out_path).replace(".__assembling__.mp4", "")
    _BIND_TOK[0] += 1
    tok = _BIND_TOK[0]
    _BINDING.update({"name": name, "pct": 0, "eta": None, "mbps": None,
                     "t0": time.time(), "total": want_bytes / 1e6,
                     "tok": tok})

    def _run():
        last_sz, last_t = 0, time.time()
        while not stop.is_set():
            stop.wait(1.0)
            if stop.is_set():
                break
            try:
                sz = os.path.getsize(out_path)
            except OSError:
                continue
            if _BINDING.get("tok") != tok:
                break              # a newer bind owns the card now
            now = time.time()
            pct = max(0, min(99, int(sz * 100 / want_bytes)))
            spent = now - _BINDING["t0"]
            _BINDING["pct"] = pct
            if pct > 0 and spent > 2:
                _BINDING["eta"] = max(0, int(spent * (100 - pct) / pct))
            if now > last_t:
                _BINDING["mbps"] = max(0.0, (sz - last_sz) / 1e6 / (now - last_t))
            last_sz, last_t = sz, now
            try:
                if _TRAY_ICON[0] is not None:
                    _TRAY_ICON[0].title = f"Lore - saving {name} ({pct}%)"
            except Exception:
                pass

    threading.Thread(target=_run, daemon=True).start()


def _stop_concat_progress():
    ev = _CONCAT_WATCH.get("ev")
    _CONCAT_WATCH["stop"] = True
    if ev is not None:
        ev.set()
    _CONCAT_WATCH["ev"] = None


def _edit_watch(proc):
    """Remember a child of the export so a Stop can actually reach it. The
    stitch used to spawn ffmpeg through a helper nothing tracked, so cancelling
    left five of them grinding the disk against a file nobody wanted."""
    try:
        _EDIT_JOB.setdefault("procs", []).append(proc)
    except Exception:
        pass
    return proc


def _edit_kill_children():
    """Stop everything this export started, and say how many there were."""
    procs = _EDIT_JOB.get("procs") or []
    killed = 0
    for pr in list(procs):
        try:
            if pr.poll() is None:
                pr.kill()
                killed += 1
        except Exception:
            pass
    try:
        for pr in list(procs):
            try:
                pr.wait(timeout=5)
            except Exception:
                pass
    except Exception:
        pass
    _EDIT_JOB["procs"] = []
    return killed


_DRIFT = {"busy": False, "cancel": False, "done": 0, "total": 0,
          "fixed": 0, "name": "", "scanned": False, "hits": [],
          # scan or repair. The tome used to GUESS this from a flag it set on
          # the click, and lost the guess in the gap between the call
          # returning and the worker thread setting busy - so a repair came
          # out labelled 'checking'. The engine knows; it says.
          "mode": ""}


def _av_durations(path):
    """(video seconds, audio seconds) or None."""
    try:
        d = os.path.dirname(SETTINGS["ffmpeg_path"])
        probe = os.path.join(d, "ffprobe.exe" if os.name == "nt" else "ffprobe")
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        r = subprocess.run([probe, "-v", "error", "-show_entries",
                            "stream=codec_type,duration", "-of", "json", path],
                           capture_output=True, text=True, timeout=40,
                           creationflags=flags)
        v = a = None
        for st in (json.loads(r.stdout or "{}").get("streams") or []):
            if st.get("codec_type") == "video" and v is None:
                v = float(st.get("duration") or 0)
            elif st.get("codec_type") == "audio" and a is None:
                a = float(st.get("duration") or 0)
        if v and a and v > 1 and a > 1:
            return v, a
    except Exception:
        pass
    return None


def _drift_repair_one(path):
    """Stretch the picture's clock onto the sound's. Nothing is re-encoded, so
    a two-gigabyte recording takes about half a minute and loses nothing."""
    got = _av_durations(path)
    if not got:
        return False
    vd, ad = got
    if abs(ad - vd) < 0.5:
        return False                      # already in step
    ratio = ad / vd
    if not (0.9 < ratio < 1.1):
        return False                      # not drift; leave it well alone
    tmp = path + ".__sync__.mp4"
    flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
    try:
        # input 0 carries the picture with its timestamps stretched; input 1 is
        # the same file untouched and carries the sound.
        pr = _popen(
            [SETTINGS["ffmpeg_path"], "-y", "-hide_banner", "-loglevel", "error",
             "-itsscale", f"{ratio:.9f}", "-i", path, "-i", path,
             "-map", "0:v:0", "-map", "1:a:0", "-c", "copy",
             "-movflags", "+faststart", tmp],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            creationflags=flags)
        _DRIFT["proc"] = pr
        try:
            pr.wait(timeout=3600)
        except subprocess.TimeoutExpired:
            # the generic except below cannot kill it - it must die HERE or
            # it grinds the library disk for another hour and holds the tmp
            pr.kill()
            pr.wait(timeout=30)
            raise RuntimeError("re-sync took over an hour; stopped")
        if pr.returncode != 0 or not os.path.isfile(tmp):
            raise RuntimeError("ffmpeg refused")
        # NEVER replace the original until the new one is checked
        if os.path.getsize(tmp) < os.path.getsize(path) * 0.9:
            raise RuntimeError("the repaired copy came out too small")
        chk = _av_durations(tmp)
        if not chk or abs(chk[1] - chk[0]) > 0.5:
            raise RuntimeError("still adrift")
        try:
            st = os.stat(path)
        except OSError:
            st = None
        os.replace(tmp, path)
        if st is not None:
            try:
                # keep the original mtime: the transcript, marks and review
                # still describe this same content, and a bumped clock made
                # one drift repair silently queue HOURS of AI redo
                os.utime(path, (st.st_atime, st.st_mtime))
            except OSError:
                pass
        log(f"Re-synced {os.path.basename(path)}: was {ad - vd:+.2f}s adrift.")
        return True
    except Exception as e:
        log(f"Could not re-sync {os.path.basename(path)}: {e}")
        try:
            os.remove(tmp)
        except OSError:
            pass
        return False
    finally:
        _DRIFT["proc"] = None


# which sidecars a job owns. 'listening' owns TWO - the gold moments and the
# sound curve underneath them - and redoing the moments without the curve
# would leave the graph drawn from the old measurements.
_JOB_SIDES = {"listening": ("hl", "lvl"), "hearing": ("stt",),
              "thinking": ("ins", "aud"),
              # the audit alone: corrections live on the transcript lines
              # (was/pin), so forgetting the .aud loses no history
              "auditing": ("aud",)}


def _redo_sweep(kinds):
    """Delete the sidecars for these jobs so the ordinary queue redoes them.
    Nothing is recomputed here - this only forgets."""
    sides = []
    for k in kinds:
        sides.extend(_JOB_SIDES.get(k, ()))
    if not sides:
        return 0
    gone = 0
    try:
        for d, kind in _library_dirs(SETTINGS.get("output_dir", "")):
            for v in _scan_dir_mp4s(d, kind):
                for side in sides:
                    p = _ai_sidecar(v["path"], side)
                    try:
                        if os.path.isfile(p):
                            os.remove(p)
                            gone += 1
                    except OSError:
                        pass
    except Exception:
        pass
    _AI.pop("_tally", None)          # the counts are stale the moment we start
    return gone


# window CLASS names and engine furniture. None of these is ever a game.
_NOT_A_GAME = {"d3dproxywindow", "unrealwindow", "ue4window", "ue5window",
               "sdlapp", "glfw30", "winclass", "mainwindow", "gamewindow",
               "directx", "renderwindow", "splashscreen", "launcher"}
_BUILD_TAG_RE = (r"^(?:\d+[- ]?bit|x64|x86|dx\d+|d3d\d*|vulkan|opengl|cooked|"
                 r"shipping|release|debug|development|final|retail|steam|epic|"
                 r"demo|beta|alpha|win(?:64|32)?|64|32)$")


def _clean_stored_name(name, raw):
    """What survives of a stored name once you actually look at it. None means
    nothing did - go and ask properly."""
    import re
    n = str(name or "").strip()
    if not n:
        return None
    if _norm_game_key(n) in _NOT_A_GAME:
        return None                       # a window class, not a game
    tag = re.compile(_BUILD_TAG_RE, re.I)

    def _debracket(m):
        parts = [p.strip() for p in re.split(r"[,;/]| - ", m.group(1))
                 if p.strip()]
        return "" if parts and all(tag.match(p) for p in parts) else m.group(0)

    n = re.sub(r"\s*\(([^()]*)\)", _debracket, n).strip()
    n = re.sub(r"\s+\d{3,6}$", "", n).strip()      # 'yuzu 1734'
    if len(n) < 3:
        return None
    # STRIP THE BUILD TAGS OFF THE EXECUTABLE FIRST. Comparing against the raw
    # stem rejected every good name too: 'theinvincible-win64-shipping' starts
    # with 'theinvincible', so The Invincible looked like a truncation of
    # itself. Against the de-tagged stem the test does what it is meant to.
    # peel the build tags off the executable one at a time. The regex that
    # was here kept silently not matching; a loop is duller and it is obvious
    # what it does, which is worth more than the cleverness was.
    parts = [p for p in re.split(r"[-_ ]+", str(raw or "")) if p]
    while parts and parts[-1].lower() in (
            "win64", "win32", "shipping", "cooked", "release", "debug",
            "final", "retail", "x64", "x86", "64", "32", "exe"):
        parts.pop()
    key, rk = _norm_game_key(n), _norm_game_key("".join(parts))
    # 'Pal' for palworld: a strict truncation of its own executable is the
    # title bar being lazy, not the game's name
    if rk and key and key != rk and rk.startswith(key) and len(key) < len(rk):
        return None
    return n


def _game_names_sweep(force=False):
    """Re-derive every game's name. Free sources first; the paid last resort
    only fires for the ones that still come back as their own executable."""
    changed, dropped, looked = [], [], 0
    if force:
        _AI["named"] = set()         # ask again about ones already asked
    try:
        seen = set()
        for d, kind in _library_dirs(SETTINGS.get("output_dir", "")):
            for v in _scan_dir_mp4s(d, kind):
                raw = _parse_clip_name(os.path.basename(v["path"]))
                key = _norm_game_key(raw)
                if not key or key in seen:
                    continue
                seen.add(key)
                looked += 1
                if looked > 150:     # a check, not an audit
                    break
                stored = None
                try:
                    stored = _auto_name_for_raw(raw)
                except Exception:
                    pass
                kept = _clean_stored_name(stored, raw) if stored else None
                if stored and not kept:
                    # the stored answer did not survive being looked at
                    auto = _load_auto_game_names()
                    for kk in (key, _norm_game_key(raw + ".exe")):
                        auto.pop(kk, None)
                    _save_auto_game_names(auto)
                    dropped.append((raw, stored))
                    kept = _claude_game_name("", "", raw) if force else None
                if kept and _norm_game_key(kept) != _norm_game_key(stored or ""):
                    auto = _load_auto_game_names()
                    auto[key] = {"name": kept, "source": "checked"}
                    _save_auto_game_names(auto)
                if kept and _norm_game_key(kept) != key:
                    changed.append((raw, kept))
    except Exception:
        pass
    _persist_setting("names_last_sweep", int(time.time()))
    if dropped:
        log("Game names: threw out " + str(len(dropped)) + " bad title(s) - "
            + ", ".join(f"{a} was '{b}'" for a, b in dropped[:6]))
    if changed:
        log("Game names: " + ", ".join(f"{a} -> {b}" for a, b in changed[:12])
            + (f" (+{len(changed) - 12} more)" if len(changed) > 12 else ""))
    if not changed and not dropped:
        log(f"Game names: checked {looked}, nothing to correct.")
    return {"looked": looked, "changed": changed, "dropped": dropped}


