_USER_GAME_NAMES = None   # lazy cache: {current-title.lower(): user's new title}
_AUTO_GAME_NAMES = None   # lazy cache: {normalised exe/title key: {name, source, confidence, ...}}
_RELEARN_PENDING = set()  # stems with a steam re-learn timer already ticking - one shot, never a chain


def _user_names_path():
    return os.path.join(_data_dir(), "user_game_names.json")


def _auto_names_path():
    return os.path.join(_data_dir(), "auto_game_names.json")


def _load_user_game_names():
    global _USER_GAME_NAMES
    if _USER_GAME_NAMES is not None:
        return _USER_GAME_NAMES
    d = {}
    try:
        with open(_user_names_path(), encoding="utf-8") as fh:
            raw = json.load(fh)
        if isinstance(raw, dict):
            d = {str(k).strip().lower(): str(v).strip()
                 for k, v in raw.items() if str(v).strip()}
    except Exception:
        d = {}
    _USER_GAME_NAMES = d
    return d


def _save_user_game_names(d):
    global _USER_GAME_NAMES
    _USER_GAME_NAMES = d
    try:
        _atomic_write_json(_user_names_path(), d)
    except Exception:
        pass


def _load_auto_game_names():
    global _AUTO_GAME_NAMES
    if _AUTO_GAME_NAMES is not None:
        return _AUTO_GAME_NAMES
    d = {}
    try:
        with open(_auto_names_path(), encoding="utf-8") as fh:
            raw = json.load(fh)
        if isinstance(raw, dict):
            # self-heal: an older learner could persist engine internals
            # (TAGame et al.) - drop them on load so the filename-derived
            # title takes over again and the next launch re-learns properly
            junk = {"tagame", "ue4game", "ue5game", "unrealwindow", "cryengine",
                    "unityplayer", "godot engine", "gameapp",
                    "bootstrappackagedgame", "d3d11", "dx11", "main",
                    "battle.net", "battlenet", "blizzard battle.net",
                    "blizzard entertainment", "steam", "valve", "epic games",
                    "epic games launcher", "uplay", "ubisoft connect",
                    "origin", "ea app", "ea desktop", "gog galaxy",
                    "rockstar games", "riot client", "xbox", "game pass",
                    "microsoft store"}
            healed = False
            for k, v in raw.items():
                kk = _norm_game_key(k)
                if not kk:
                    continue
                nm = v if isinstance(v, str) else str((v or {}).get("name", ""))
                if nm.strip().lower() in junk:
                    healed = True
                    continue
                if isinstance(v, str):
                    d[kk] = {"name": v, "source": "legacy", "confidence": 50}
                elif isinstance(v, dict) and str(v.get("name", "")).strip():
                    d[kk] = v
            if healed:
                try:
                    _atomic_write_json(_auto_names_path(), d)
                    log("Purged engine-junk game titles from the learned names.")
                except Exception:
                    pass
    except Exception:
        d = {}
    _AUTO_GAME_NAMES = d
    return d


def _save_auto_game_names(d):
    global _AUTO_GAME_NAMES
    _AUTO_GAME_NAMES = d
    try:
        _atomic_write_json(_auto_names_path(), d)
    except Exception:
        pass


def _norm_game_key(s):
    import re
    return re.sub(r"[^a-z0-9]+", "", str(s or "").lower())


_GAME_NAME_TOOL = {
    "name": "name_the_game",
    "description": "Identify a PC game from its executable and window title.",
    "input_schema": {"type": "object", "properties": {
        "name": {"type": "string",
                 "description": "The game's proper title as players know it, "
                                "or an empty string if you are not sure."},
        "sure": {"type": "boolean",
                 "description": "true only if you actually recognise it"}},
        "required": ["name", "sure"]}}


def _claude_game_name(exe, title, raw):
    """The last resort, and only ever the last resort - everything free has
    already failed by the time this is called."""
    if not os.path.isfile(_key_path()):
        return None
    key = _norm_game_key(raw or exe or "")
    if not key:
        return None
    asked = _AI.setdefault("named", set())
    if key in asked:
        return None                    # one question per game, ever
    asked.add(key)
    data, why = _claude(
        "You identify PC games from the name of their executable and the title "
        "of their window. Answer with the title players actually use - "
        "'Palworld', not 'palworld-win64-shipping'. Strip engine and build "
        "tags. If you do not genuinely recognise it, say so with sure=false "
        "and an empty name rather than guessing.",
        f"Executable: {exe or '(unknown)'}\n"
        f"Window title: {title or '(none)'}\n"
        f"Folder name LORE derived: {raw or '(none)'}",
        _GAME_NAME_TOOL, max_tokens=200, model=CLAUDE_MODELS["fast"])
    if not data or not data.get("sure"):
        return None
    name = str(data.get("name") or "").strip()
    if not name or len(name) > 60:
        return None
    if _norm_game_key(name) == _norm_game_key(raw or ""):
        return None                    # it agreed with the filename: no news
    log(f"Claude named a game: {raw} -> {name}")
    return name


def _auto_name_for_raw(raw):
    """Automatic exe/title/appmanifest alias for an old or future recording.
    This is what makes a newly discovered real title apply to all existing files
    without renaming or moving them."""
    try:
        auto = _load_auto_game_names()
        keys = {_norm_game_key(raw), _norm_game_key(os.path.splitext(str(raw))[0])}
        for k in keys:
            it = auto.get(k)
            if isinstance(it, dict) and str(it.get("name", "")).strip():
                return str(it["name"]).strip()
            if isinstance(it, str) and it.strip():
                return it.strip()
    except Exception:
        pass
    return None


def _clean_game_display_title(title, raw_base=""):
    """Turn a taskbar/window title or metadata string into a stable game title,
    rejecting scene names, device/API suffixes and obvious launcher junk."""
    import re
    s = str(title or "").replace("™", "").replace("®", "").replace("©", "")
    s = re.sub(r"[\r\n\t]+", " ", s).strip(" -_|—–")
    if not s or len(s) < 3 or len(s) > 96:
        return None
    if re.search(r"[A-Za-z]:\\|/|https?://", s):
        return None
    # Drop pure technical tags but keep real subtitles such as ': Wings of Ruin'.
    # A bracket is junk only when EVERY comma-separated part of it is a build
    # tag - Rocket League titles its window "Rocket League (64-bit, DX11,
    # Cooked)", and matching single-token brackets left all of that in place.
    _TECH = {"dx11", "dx12", "dx 11", "dx 12", "directx11", "directx12",
             "directx 11", "directx 12", "vulkan", "opengl", "win64", "win32",
             "x64", "x86", "64-bit", "32-bit", "64 bit", "32 bit", "shipping",
             "cooked", "development", "debug", "release", "retail", "final",
             "test", "steam", "epic", "egs", "uwp"}

    def _drop_tech(m):
        parts = [x.strip().lower() for x in m.group(1).split(",")]
        return " " if parts and all(x in _TECH for x in parts) else m.group(0)

    s = re.sub(r"\s*[\[(]([^\[\]()]{1,60})[\])]\s*", _drop_tech, s)
    s = re.sub(r"\s+[-–—]\s+(?:dx\s*1[12]|directx\s*1[12]|vulkan|opengl|win64|x64|shipping|steam|epic)$", "", s, flags=re.I)
    s = re.sub(r"\s+", " ", s).strip(" -_|—–")
    low = s.lower()
    bad_exact = {"unity", "unreal engine", "game", "launcher", "bootstrapper",
                 "loading", "not responding", "application", "windows",
                 # engine INTERNALS that leak through EXE version metadata -
                 # Rocket League's FileDescription is literally "TAGame"
                 "tagame", "ue4game", "ue5game", "unrealwindow", "cryengine",
                 "unityplayer", "godot engine", "gameapp",
                 "bootstrappackagedgame", "d3d11", "dx11", "main",
                 # STOREFRONT BRANDS. These reach us through exe version
                 # metadata - Blizzard stamps Hearthstone.exe "Battle.net" -
                 # and would file every game of theirs under the shop's name.
                 "battle.net", "battlenet", "blizzard battle.net",
                 "blizzard entertainment", "steam", "valve",
                 "epic games", "epic games launcher", "uplay",
                 "ubisoft connect", "origin", "ea app", "ea desktop",
                 "gog galaxy", "rockstar games", "riot client",
                 "xbox", "game pass", "microsoft store"}
    # only the ENGINE's splash strings are junk - a bare "unreal " prefix
    # used to eat the actual Unreal Tournament titles
    if low in bad_exact or low.endswith(" launcher") or low.startswith(("unreal engine", "unreal editor")):
        return None
    # NOTE: a name that merely EQUALS the exe stem is kept - it is the CORRECT
    # title and must be able to OUTRANK engine junk. (Rejecting it here once
    # left "TAGame" as the only exe-version candidate, which then won.) The
    # learner skips STORING a pointless same-as-stem alias instead.
    if raw_base and _norm_game_key(s) in {"", "win64shipping", "shipping"}:
        return None
    # Avoid volatile titles that are probably just level/server/editor state.
    if re.search(r"\b(level|map|server|lobby|match|profile|settings|options)\b", low) and len(s.split()) <= 3:
        return None
    return s


def _game_exe_path(pname):
    try:
        for pr in psutil.process_iter(["pid", "name", "exe"]):
            if (pr.info.get("name") or "").lower() == str(pname or "").lower():
                ex = pr.info.get("exe") or ""
                if ex and os.path.isfile(ex):
                    return ex
    except Exception:
        pass
    return None


def _file_version_strings(exe_path):
    """ProductName/FileDescription from the EXE version resource, no internet."""
    if os.name != "nt" or not exe_path or not os.path.isfile(exe_path):
        return []
    try:
        import ctypes
        from ctypes import wintypes
        ver = ctypes.windll.version
        size = ver.GetFileVersionInfoSizeW(exe_path, None)
        if not size:
            return []
        buf = ctypes.create_string_buffer(size)
        if not ver.GetFileVersionInfoW(exe_path, 0, size, buf):
            return []
        trans_ptr = ctypes.c_void_p()
        trans_len = wintypes.UINT()
        langs = [(0x0409, 0x04B0)]
        if ver.VerQueryValueW(buf, "\\VarFileInfo\\Translation",
                              ctypes.byref(trans_ptr), ctypes.byref(trans_len)) and trans_len.value >= 4:
            arr = (ctypes.c_ushort * (trans_len.value // 2)).from_address(trans_ptr.value)
            langs = [(arr[i], arr[i + 1]) for i in range(0, min(len(arr) - 1, 8), 2)]
        out = []
        for lang, cp in langs:
            for key in ("ProductName", "FileDescription", "InternalName"):
                ptr = ctypes.c_void_p(); ln = wintypes.UINT()
                sub = f"\\StringFileInfo\\{lang:04x}{cp:04x}\\{key}"
                if ver.VerQueryValueW(buf, sub, ctypes.byref(ptr), ctypes.byref(ln)) and ptr.value:
                    txt = ctypes.wstring_at(ptr.value, max(0, ln.value - 1)).strip()
                    if txt and txt not in out:
                        out.append(txt)
        return out
    except Exception:
        return []


def _steam_name_for_exe(exe_path):
    """Steam appmanifest DisplayName by matching steamapps/common/<installdir>."""
    if not exe_path:
        return None
    try:
        import glob, re
        p = os.path.abspath(exe_path)
        parts = p.split(os.sep)
        steamapps = None
        installdir = None
        for i, part in enumerate(parts):
            if part.lower() == "steamapps":
                steamapps = os.sep.join(parts[:i + 1])
                if i + 2 < len(parts) and parts[i + 1].lower() == "common":
                    installdir = parts[i + 2]
                break
        if not steamapps or not installdir:
            return None
        for mf in glob.glob(os.path.join(steamapps, "appmanifest_*.acf")):
            try:
                txt = open(mf, encoding="utf-8", errors="ignore").read()
            except Exception:
                continue
            mdir = re.search(r'"installdir"\s+"([^"]+)"', txt, re.I)
            mname = re.search(r'"name"\s+"([^"]+)"', txt, re.I)
            if mdir and mname and mdir.group(1).strip().lower() == installdir.lower():
                return mname.group(1).strip()
    except Exception:
        pass
    return None


def _registry_name_for_exe(exe_path):
    """Installed-app DisplayName by matching Uninstall InstallLocation/DisplayIcon."""
    if os.name != "nt" or not exe_path:
        return None
    try:
        import winreg, re
        p = os.path.normcase(os.path.abspath(exe_path))
        roots = [(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Uninstall"),
                 (winreg.HKEY_LOCAL_MACHINE, r"Software\Microsoft\Windows\CurrentVersion\Uninstall"),
                 (winreg.HKEY_LOCAL_MACHINE, r"Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall")]
        for root, sub in roots:
            try:
                key = winreg.OpenKey(root, sub)
            except OSError:
                continue
            with key:
                for i in range(winreg.QueryInfoKey(key)[0]):
                    try:
                        sk = winreg.OpenKey(key, winreg.EnumKey(key, i))
                    except OSError:
                        continue
                    with sk:
                        def q(name):
                            try: return str(winreg.QueryValueEx(sk, name)[0]).strip()
                            except Exception: return ""
                        name = q("DisplayName")
                        if not name:
                            continue
                        loc = q("InstallLocation")
                        icon = q("DisplayIcon")
                        icon = re.sub(r'^"|",?\d*$|,\d+$', "", icon).strip('"')
                        hit = False
                        for cand in (loc, icon):
                            if not cand:
                                continue
                            c = os.path.normcase(os.path.abspath(os.path.expandvars(cand)))
                            if c and (p == c or p.startswith(c.rstrip(os.sep) + os.sep)):
                                hit = True; break
                        if hit:
                            return name
    except Exception:
        pass
    return None


def _folder_name_for_exe(exe_path):
    if not exe_path:
        return None
    try:
        skip = {"binaries", "win64", "win32", "x64", "x86", "shipping", "retail",
                "content", "engine", "bin"}
        d = os.path.dirname(os.path.abspath(exe_path))
        for _ in range(5):
            name = os.path.basename(d)
            if name and name.lower() not in skip:
                return name
            nd = os.path.dirname(d)
            if nd == d:
                break
            d = nd
    except Exception:
        pass
    return None


def _learn_game_display_name(pname, retry=True):
    """Discover and persist the best no-internet display name for a running game.
    Priority: taskbar/window title -> Steam manifest -> registry -> EXE metadata -> folder.
    The alias key is the raw EXE stem, so old recordings and future recordings both
    show the corrected title without renaming files."""
    try:
        raw_base = os.path.splitext(os.path.basename(str(pname or "")))[0]
        if not raw_base or raw_base.lower() in ("screen", "desktop", "test"):
            return None
        exe = _game_exe_path(pname)
        candidates = []
        title = _game_window_title(pname)
        ct = _clean_game_display_title(title, raw_base)
        if ct:
            candidates.append((95, "window-title", ct))
        sn = _clean_game_display_title(_steam_name_for_exe(exe), raw_base)
        if sn:
            candidates.append((94, "steam-manifest", sn))
        rn = _clean_game_display_title(_registry_name_for_exe(exe), raw_base)
        if rn:
            candidates.append((86, "registry", rn))
        for txt in _file_version_strings(exe):
            vn = _clean_game_display_title(txt, raw_base)
            if vn:
                candidates.append((78, "exe-version", vn))
        fn = _clean_game_display_title(_folder_name_for_exe(exe), raw_base)
        if fn:
            candidates.append((62, "install-folder", fn))
        if not candidates:
            return None
        score, source, name = sorted(candidates, key=lambda x: (-x[0], -len(x[2])))[0]
        # a Steam miss at record start is usually Steam rewriting the manifest
        # at that exact second (LastPlayed) - re-learn ONCE shortly after, when
        # the acf is whole again. gated on steam actually MISSING: window-title
        # outranks steam 95>94, so testing the winner's source was true on
        # every run and chained a 20s full-rescan timer all session long.
        # sits ABOVE the same-as-stem return so a stem-titled winner can't
        # swallow the retry; one-shot (retry flag + pending set) so parallel
        # record starts can't stack timers either.
        if retry and sn is None and exe and "steamapps" in exe.lower() \
                and raw_base not in _RELEARN_PENDING:
            try:
                _RELEARN_PENDING.add(raw_base)
                def _relearn(p=pname, b=raw_base):
                    _RELEARN_PENDING.discard(b)
                    _learn_game_display_name(p, retry=False)
                threading.Timer(20.0, _relearn).start()
            except Exception:
                _RELEARN_PENDING.discard(raw_base)
        if _norm_game_key(name) == _norm_game_key(raw_base):
            # NOTHING FREE COULD NAME IT. Steam, Windows' own game list and the
            # window title all came back with the executable. This is the case
            # that produced 'dsclient-win64-shipping' - so if there is a key,
            # ask, and treat the answer as a middling-confidence source that a
            # real Steam match would still beat later.
            asked = _claude_game_name(exe, title, raw_base)
            if asked:
                name, source, score = asked, "claude", 55
            else:
                # the winner just confirms the filename-derived title: nothing
                # worth persisting, and nothing WRONG got stored either
                return name
        auto = dict(_load_auto_game_names())
        keys = {_norm_game_key(raw_base), _norm_game_key(pname)}
        if exe:
            keys.add(_norm_game_key(os.path.splitext(os.path.basename(exe))[0]))
        changed = False
        for k in {x for x in keys if x}:
            old = auto.get(k, {}) if isinstance(auto.get(k), dict) else {}
            old_score = int(old.get("confidence", 0) or 0)
            old_name = str(old.get("name", "")).strip()
            if not old_name or score >= old_score - 3:
                auto[k] = {"name": name, "source": source, "confidence": score,
                           "exe": exe or "", "window_title": title or "", "seen": time.time()}
                changed = True
        if changed:
            _save_auto_game_names(auto)
            if _norm_game_key(name) != _norm_game_key(raw_base):
                log(f"Game title learned: {raw_base} -> {name} ({source})")
        return name
    except Exception as e:
        log(f"Game title learn failed: {e}")
        return None


def _apply_user_name(name):
    """A user rename overrides the computed title AND every future recording of
    that game (same exe -> same computed title -> same override). Resolves a
    short A->B->C chain so repeated renames still land on the latest name."""
    try:
        ov = _load_user_game_names()
        if not ov:
            return name
        cur, seen = name, set()
        for _ in range(6):
            k = cur.strip().lower()
            if k in ov and ov[k] and ov[k] != cur and k not in seen:
                seen.add(k)
                cur = ov[k]
            else:
                break
        return cur
    except Exception:
        return name


def _display_name(raw):
    """Best-effort pretty title for a chapter heading: known games get their
    real names; the rest get their engine's build suffix stripped, then
    CamelCase / letter-digit splitting and title-casing. The filename is the
    only truth we have, so this is cosmetic and never fails."""
    import re
    try:
        s = str(raw)
        # strip Unreal/Unity/GDK shipping-build tails: 'Foo-Win64-Shipping',
        # 'Foo-WinGDK-Shipping', 'FooClient-Win64-Test', 'Foo-Shipping', etc.
        s = re.sub(r"[-_\s]*(Win(?:64|32|GDK|Client)?|Shipping|Client|Server|Test|"
                   r"Final|Development|Cmd|EGS|Steam)+([-_\s].*)?$", "", s,
                   flags=re.IGNORECASE).strip(" -_") or str(raw)
        # strip a leaked capture-date that got glued onto the name, e.g.
        # 'Game_20251216' or 'Game 20251216 143022' - a bare run of 8 digits is
        # never part of a real title, so it can only be a stray timestamp that
        # otherwise spawns a phantom one-off "game" split from its real folder.
        s2 = re.sub(r"[\s_\-]+\d{8}(?:[\s_\-]+\d{6})?$", "", s).strip(" -_")
        if s2:
            s = s2
        key = re.sub(r"[\s_\-]+", "", s).lower()
        auto = _auto_name_for_raw(s)
        if auto:
            return _apply_user_name(auto)
        if key in _GAME_NAMES:
            return _apply_user_name(_GAME_NAMES[key])
        s = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", s)
        s = re.sub(r"(?<=[A-Za-z])(?=\d)", " ", s).strip()
        if s.islower():
            s = s.title()
        return _apply_user_name(s or str(raw))
    except Exception:
        return str(raw)


def _safe_folder(name):
    """A filesystem-safe folder name for a game's shelf on the disk."""
    bad = set('<>:"/|?*') | {chr(92)}
    sname = "".join(c for c in str(name) if c not in bad)
    sname = sname.strip().rstrip(".")
    return sname or "Unsorted"


def _game_shelf(base, kind, make=True):
    """Where a recording belongs now: output_dir/<Game>/Videos for full
    sessions, output_dir/<Game>/Clips for clips - one tidy shelf per game
    (the user's library-organisation ask)."""
    sub = ("Videos" if kind == "session"
           # clips YOU cut in the player get their own shelf: a long session
           # can spawn a dozen of them and they would bury the recording they
           # came from. Hotkey clips are untouched - they stay in Clips.
           else "Edits" if kind == "edit" else "Clips")
    d = os.path.join(SETTINGS.get("output_dir", ""),
                     _safe_folder(_display_name(base)), sub)
    if make:
        os.makedirs(d, exist_ok=True)
    return d


def _library_dirs(out):
    """Every folder a recording can live in, as (dir, kind) pairs: the
    per-game shelves (<Game>/Videos + <Game>/Clips) AND the flat legacy
    spots. ONE source of truth so the scanner, the change-signature and the
    storage cap all look in exactly the same places (they drifted apart when
    shelves arrived, which hid new recordings and starved the cap)."""
    pairs = []
    try:
        for name in os.listdir(out):
            d = os.path.join(out, name)
            if (not os.path.isdir(d) or name.startswith(".")
                    or name in ("Clips", "Old")):
                continue
            pairs.append((os.path.join(d, "Videos"), "session"))
            pairs.append((os.path.join(d, "Clips"), "clip"))
            pairs.append((os.path.join(d, "Edits"), "edit"))
    except Exception:
        pass
    pairs.append((out, "session"))
    pairs.append((os.path.join(out, "Clips"), "clip"))
    return pairs


def _thumb_dir(out):
    # ALL thumbnails live in ONE cache at the recordings-folder root, keyed by
    # the (unique) filename - never a per-shelf dir, or the generator and the
    # readers look in different places. Survives a reinstall.
    return os.path.join(SETTINGS.get("output_dir", "") or out, ".lore_thumbs")


# ---------------------------------------------------------------------------
#  3.31 THE PER-GAME SOURCES LEDGER. Does this game carry voice chat? Does
#  the game itself talk? One file, %LOCALAPPDATA%\Lore\game_sources.json,
#  keyed exactly as scan_library keys a chapter (the display name, lower
#  case, off the video's basename) so the shelf's badges join without a
#  second lookup. It is REBUILT from the shelf - the sidecars' 'sources'
#  blocks, head-read - never incremented: a redo of a night cannot count
#  it twice, and only videos still on disk vote. A transcribe schedules
#  one debounced rebuild; a daily tick catches the rest.
# ---------------------------------------------------------------------------
_GS_VOICE_S = 120.0     # a night with this much speech on the Voice tap = voice chat
_GS_GAME_S = 60.0       # this much of the game's own speech = the game talks
_GS_MEDIA_S = 60.0      # this much of a video's speech = a video played (reported)
_GS_QUIET_NIGHTS = 3    # this many honest quiet nights = false, not unknown
_GS_DEBOUNCE_S = 30.0   # a transcribe waits this long before the rebuild
_GS_OK_VOICE = ("live", "gone")   # a Voice tap that was honest all night
_GS = {"timer": None, "lock": threading.Lock(), "daily_at": 0.0}


def _game_sources_path():
    return os.path.join(_data_dir(), "game_sources.json")


def _game_sources_lib():
    return os.path.normcase(os.path.abspath(
        SETTINGS.get("output_dir", "") or "."))


def _game_sources_empty():
    return {"v": 1, "lib": "", "at": 0, "games": {}}


def _game_sources_load():
    """The ledger, or the empty shape - also when it was built for a
    different library (a moved output_dir must not wear another shelf's
    verdicts) or cannot be read."""
    try:
        with open(_game_sources_path(), encoding="utf-8") as fh:
            got = json.load(fh) or {}
    except Exception:
        return _game_sources_empty()
    if not isinstance(got, dict) or not isinstance(got.get("games"), dict):
        return _game_sources_empty()
    if str(got.get("lib") or "") != _game_sources_lib():
        return _game_sources_empty()
    return got


def _game_sources_row():
    return {"nights": 0, "voice_seen": 0, "voice_nights": 0,
            "game_seen": 0, "game_nights": 0, "media_nights": 0,
            "voice_s": 0.0, "game_s": 0.0, "media_s": 0.0, "last": 0,
            "voice_chat": None, "voice_lines": None}


def _game_sources_add(row, sources, when=0):
    """One night's 'sources' block into a row - the increments, in ONE
    place. A night 'saw' a layer when its track existed; it counts as a
    voice / game / media night when that layer carried the threshold."""
    row["nights"] += 1
    if sources.get("voice"):
        row["voice_seen"] += 1
        vs = float(sources.get("voice_s") or 0.0)
        row["voice_s"] = round(row["voice_s"] + vs, 1)
        if vs >= _GS_VOICE_S:
            row["voice_nights"] += 1
    if sources.get("game"):
        row["game_seen"] += 1
        gs = float(sources.get("game_s") or 0.0)
        row["game_s"] = round(row["game_s"] + gs, 1)
        if gs >= _GS_GAME_S:
            row["game_nights"] += 1
    ms = float(sources.get("media_s") or 0.0)
    row["media_s"] = round(row["media_s"] + ms, 1)
    if ms >= _GS_MEDIA_S:
        row["media_nights"] += 1
    row["last"] = max(int(row.get("last") or 0), int(when or 0))


def _game_sources_verdicts(row):
    """THE VERDICTS, from the thresholds above and nowhere else (retuning
    = edit the numbers + rebuild). voice_chat: True after ONE night with
    voice-chat speech on the tap; False after three nights that carried
    a Voice track and nobody spoke on it; None until then. voice_lines
    likewise on the Game track. Media is reported (media_nights), never
    judged. Mutates the row."""
    row["voice_chat"] = (True if row["voice_nights"] >= 1 else
                         (False if (row["voice_seen"] >= _GS_QUIET_NIGHTS
                                    and row["voice_nights"] == 0)
                          else None))
    row["voice_lines"] = (True if row["game_nights"] >= 1 else
                          (False if (row["game_seen"] >= _GS_QUIET_NIGHTS
                                     and row["game_nights"] == 0)
                           else None))


def _game_sources_key(file_name):
    """scan_library's chapter key for a video, off its basename."""
    return _display_name(_parse_clip_name(file_name)).lower()


def _game_sources_night_ok(tdir, base, sources):
    """May this night vote? Not when the reader stood media detection
    down (the Voice tap was not trusted), and not when the recorder's
    .src.json says the tap died or failed - three such nights would flip
    a game to 'no voice chat' for a fault of the tap."""
    try:
        if int(sources.get("media_off") or 0):
            return False
    except (TypeError, ValueError):
        pass
    if not sources.get("voice"):
        return True
    try:
        with open(os.path.join(tdir, base + ".src.json"),
                  encoding="utf-8") as fh:
            doc = json.load(fh) or {}
    except Exception:
        return True
    for r in (doc.get("runs") or []):
        v = ((r.get("sources") or {}).get("voice") or {}) \
            if isinstance(r, dict) else {}
        if isinstance(v, dict) and v.get("state") is not None \
                and str(v.get("state") or "") not in _GS_OK_VOICE:
            return False
    return True


def _game_sources_rebuild():
    """Rebuild the ledger from the shelf: every transcript whose video is
    still on a shelf and whose 'sources' block says the night was heard
    by source. ~400 x 16 KB head-reads - under a second, on a daemon
    thread. Returns the ledger it wrote."""
    out = SETTINGS.get("output_dir", "")
    led = {"v": 1, "lib": _game_sources_lib(), "at": time.time(),
           "games": {}}
    base2key = {}
    for d, kind in _library_dirs(out):
        for v in _scan_dir_mp4s(d, kind):
            try:
                base2key[os.path.splitext(v["file"])[0]] = \
                    _game_sources_key(v["file"])
            except Exception:
                continue
    tdir = _thumb_dir(out)
    try:
        names = os.listdir(tdir)
    except OSError:
        names = []
    for fn in names:
        if not fn.endswith(".stt.json"):
            continue
        base = fn[:-len(".stt.json")]
        key = base2key.get(base)
        if not key:
            continue                 # not on any shelf: no vote
        try:
            with open(os.path.join(tdir, fn), encoding="utf-8",
                      errors="ignore") as fh:
                head = fh.read(16384)
        except OSError:
            continue
        # 'sources' is written before 'segments' (see the sidecar write)
        # - 16 KB covers v/model/engine/counters/reader/run/sources
        m = re.search(r'"sources"\s*:\s*(\{[^{}]*\})', head)
        if not m:
            continue                 # an old transcript: no vote
        try:
            sources = json.loads(m.group(1))
        except Exception:
            continue
        if not isinstance(sources, dict) \
                or not (sources.get("voice") or sources.get("game")):
            continue                 # a Mix-only night was not heard by source
        if not _game_sources_night_ok(tdir, base, sources):
            continue
        mw = re.search(r'"when"\s*:\s*(\d+)', head)
        try:
            when = int(mw.group(1)) if mw else int(
                os.path.getmtime(os.path.join(tdir, fn)))
        except Exception:
            when = 0
        _game_sources_add(led["games"].setdefault(key, _game_sources_row()),
                          sources, when)
    for row in led["games"].values():
        _game_sources_verdicts(row)
    try:
        _atomic_write_json(_game_sources_path(), led)
    except Exception as e:
        log(f"Could not write game_sources.json: {e}")
    return led


def _game_sources_rebuild_safe():
    try:
        _game_sources_rebuild()
    except Exception as e:
        log(f"The game-sources ledger could not be rebuilt: {e}")


def _game_sources_note(video_path, sources):
    """AFTER A TRANSCRIBE heard by source: schedule ONE rebuild, debounced
    (a catch-up sweep reads nights back to back; one walk after the last
    of them is enough). Never increments - a redo cannot double-count. A
    Mix-only night schedules nothing, so a game's badge never says
    'quiet' because the taps did not open."""
    if not isinstance(sources, dict) \
            or not (sources.get("voice") or sources.get("game")):
        return
    with _GS["lock"]:
        t = _GS.get("timer")
        if t is not None:
            try:
                t.cancel()
            except Exception:
                pass
        t = threading.Timer(_GS_DEBOUNCE_S, _game_sources_rebuild_safe)
        t.daemon = True
        t.name = "game-sources"
        t.start()
        _GS["timer"] = t


def _game_sources_daily():
    """Once a day, off the recorder's thread: rebuild when the ledger is
    absent, older than a day, or stamped for another library. The day is
    claimed BEFORE the thread runs, so two beats cannot walk twice."""
    try:
        led = _game_sources_load()
        if led.get("at") and time.time() - float(led.get("at") or 0) < 86400:
            return
        if time.time() - float(_GS.get("daily_at") or 0.0) < 3600:
            return
        _GS["daily_at"] = time.time()
        threading.Thread(target=_game_sources_rebuild_safe, daemon=True,
                         name="game-sources").start()
    except Exception as e:
        log(f"The game-sources ledger could not be scheduled: {e}")


# ---------------------------------------------------------------------------
#  The tome's intelligence (Lore 2.0) - all LOCAL, all idle-time:
#    * Qwen3-ASR transcribes every recording (CPU, BELOW_NORMAL,
#      realtime on this machine) -> the library is searchable by what was
#      actually SAID, and a hit jumps playback to that second.
#    * a numpy loudness pass marks the moments worth rewatching (fights,
#      shouts, explosions) as gold ticks on the player's timeline.
#  Sidecars live next to the thumbnails (.lore_thumbs/<video>.stt.json /
#  .hl.json), keyed by filename + source mtime so an edited/replaced video
#  is re-analysed and a deleted one leaves nothing behind but two tiny
#  orphan files the cache sweep can clear.
# ---------------------------------------------------------------------------
_AI = {"busy": None, "t_last": 0.0, "index": None, "index_t": 0.0,
       "proc": None, "abort": False, "failed": {},
       # what the job in hand is working on, so the UI can show a real bar
       "started": 0.0, "job_secs": 0.0,
       # HOW LONG THINGS ACTUALLY TAKE, measured rather than guessed: seconds
       # of wall clock per second of video, kept per kind as a rolling mean.
       # An estimate built from this library beats any constant.
       "rate": {"listening": [], "hearing": [], "thinking": []},
       # held PER JOB: one switch for both meant holding the sound silently
       # held transcripts too, with nothing on screen to say so
       "paused": False,
       "held": {"listening": False, "hearing": False, "thinking": False,
                "auditing": False}}

# The two things the reader does, named for what they produce.
AI_KINDS = ("listening", "hearing", "thinking")

# force/force_queue are written by the UI thread (prioritise, batches, Stop)
# and consumed by the watcher's tick. The pairs must move as one: unlocked,
# a Stop between jobs resurrected the batch from the tick's stale write-back,
# and a fresh batch was clobbered by the old remainder.
_AI_FORCE_LOCK = threading.RLock()
AI_LABEL = {"listening": "sound & gold moments", "hearing": "transcript",
            "thinking": "titles, chapters & clips"}


# Where to start before this machine has timed anything itself. Measured on
# a real 4.4 TB library: the audio pass runs about 54x real time (it is disk
# bound, not CPU bound) and the reader about 2x. Being roughly right from the
# first second beats showing nothing at all, and the moment a real job
# finishes these are replaced by what actually happened.
# Until this machine has timed one for itself. The reader's guess was 10.5x
# realtime, which is what a short quiet clip looks like - the first busy
# session it met (29% talking) really ran at 1.2x, so it promised twenty
# minutes and took two hours. Roughly 1.5x realtime is the honest middle:
# still a guess, but one that does not flatter itself by a factor of nine.
_AI_RATE_GUESS = {"listening": 1.0 / 54.0, "hearing": 1.0 / 1.5,
                  "thinking": 1.0 / 900.0}


def _game_has_focus():
    """Is a game the window he is actually looking at?

    find_active_game() answers "is a game running", which is the right
    question for deciding whether to RECORD and the wrong one for deciding
    how much processor to take: a launcher, an idle Hearthstone behind the
    tome, a game left open while he reads - none of those are being played,
    and each of them used to cost him three quarters of his machine."""
    if os.name != "nt":
        return False
    try:
        # imported HERE, as everything else in this file does - ctypes is not
        # a module-level name and reaching for one that is not there would
        # throttle him forever behind a silent except
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        hwnd = user32.GetForegroundWindow()
        if not hwnd:
            return False
        pid = wintypes.DWORD()
        user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        if not pid.value or pid.value == os.getpid():
            return False
        name = psutil.Process(pid.value).name().lower()
    except Exception:
        return False              # cannot tell -> do not throttle him
    try:
        if name in load_ignore_list():
            return False
        return bool(name in load_game_list() or name in load_builtin_games())
    except Exception:
        return False


def _reader_threads():
    """How much of the machine the reader may take, RIGHT NOW.

    A quarter of it while he is actually playing - a stuttering game is
    noticed instantly and slow reading is invisible. Otherwise nearly all of
    it, because nothing is competing for it."""
    n = os.cpu_count() or 8
    playing = False
    try:
        ctl = _AI.get("ctl")
        playing = bool(ctl is not None and ctl.session is not None)
    except Exception:
        pass
    if not playing:
        playing = _game_has_focus()
    return max(2, n // 4) if playing else max(2, n - 4)


def _write_reader_budget(ctl_path):
    """Tell a running reader what it may use. It re-reads this between
    utterances, so alt-tabbing out of a game speeds it up within seconds
    instead of at the next job."""
    try:
        n = _reader_threads()
        tmp = ctl_path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump({"threads": n}, fh)
        os.replace(tmp, ctl_path)
        return n
    except Exception:
        return None


def _ai_rate(kind):
    """Seconds of work per second of video, averaged over what this machine
    has actually done - falling back to a sensible figure until it has."""
    r = _AI["rate"].get(kind) or []
    if r:
        return sum(r) / len(r)
    return _AI_RATE_GUESS.get(kind)


def _ai_rates_load():
    """Bring back what was learned before the last restart."""
    try:
        got = SETTINGS.get("ai_rates") or {}
        # speech_cost/speech_frac ride along with the rest - they are the ones
        # the reader is actually priced by now, and leaving them out here
        # would have thrown them away on every restart, which is exactly the
        # bug that was already fixed once for the other three.
        for k in ("listening", "hearing", "thinking",
                  "speech_cost", "speech_frac"):
            v = got.get(k)
            if isinstance(v, list):
                keep = 24 if k == "speech_frac" else 12
                _AI["rate"][k] = [float(x) for x in v[-keep:] if float(x) > 0]
    except Exception:
        pass


def _ai_note_rate(kind, video_secs, took):
    if video_secs <= 0 or took <= 0:
        return
    r = _AI["rate"].setdefault(kind, [])
    r.append(took / video_secs)
    del r[:-12]                       # only the recent dozen matter
    # WRITE IT DOWN. Held only in memory, every update threw it away - and
    # with it the percentage, the time left and the speed on the Working page.
    try:
        _persist_setting("ai_rates", {k: v for k, v in _AI["rate"].items() if v})
    except Exception:
        pass


def _ai_note_speech(video_secs, speech_secs, took):
    """Remember what a second of TALKING costs, and how much of a recording
    tends to be talking. Two numbers instead of one, because they vary for
    completely different reasons: the first is this machine, the second is
    whether anybody was in Discord."""
    if video_secs <= 0 or speech_secs <= 0 or took <= 0:
        return
    sr = _AI["rate"].setdefault("speech_cost", [])
    sr.append(took / speech_secs)
    del sr[:-12]
    fr = _AI["rate"].setdefault("speech_frac", [])
    fr.append(max(0.0, min(1.0, speech_secs / video_secs)))
    del fr[:-24]                  # this one is noisier - keep more of it
    try:
        _persist_setting("ai_rates", {k: v for k, v in _AI["rate"].items() if v})
    except Exception:
        pass


def _hearing_secs_per_video_sec():
    """What one second of recording costs the reader, on this machine.

    Preferring speech x cost over the old flat per-video average, because the
    flat one is an average over whoever happened to be talking in the last
    dozen recordings, and it was wrong by 5x on the first busy session it met.
    Falls back to the old number until there is speech history to use."""
    cost = _AI["rate"].get("speech_cost") or []
    frac = _AI["rate"].get("speech_frac") or []
    if cost and frac:
        return (sum(cost) / len(cost)) * (sum(frac) / len(frac))
    return _ai_rate("hearing")


def _ask_srv_drop():
    """Stop the question box's PRIVATE server, if one is idling. A job is
    about to own the card, and with the fit now automatic that idle
    server can be holding most of it - which is how a transcribe found
    no room and fell back to the CPU road at a third of the speed. A
    BORROWED server (a describe job's own, pr is None) is never touched."""
    srv = _ASK.get("srv")
    if srv is not None and srv.pr is not None:
        try:
            srv.stop()
        except Exception:
            pass
        _ASK["srv"] = None


def _ai_want_lanes(want):
    """Which of the reader's three lanes a forced ask drives. The queue
    holds (path, want, redo); pause holds lanes; this is the bridge."""
    w = str(want or "all").lower()
    if w == "sound":
        return ("listening",)
    if w == "words":
        return ("hearing",)
    if w == "think":
        return ("thinking",)
    if w == "audit":
        return ("auditing",)
    # THREE WORKING LANES, ON PURPOSE. Widening this to four made
    # _ai_lanes_free freeze every "all" batch whenever ONLY the audit
    # lane was held - a describe queue stopped dead by a lane it does
    # not need to START. The audit-hold problem is solved where it
    # belongs instead: _ai_ask_unhold lifts the audit lane explicitly
    # for every ask whose chain ends in one, and the chain's tail logs
    # when a held audit makes it skip.
    return ("listening", "hearing", "thinking")   # "all" and anything odd


def _ai_effective_lane(kind, name):
    """The lane a busy tuple REALLY belongs to. The audit rides the
    thinking lane wearing a name prefix; three sites sniffed it three
    different ways before this."""
    if str(name or "").startswith("the audit \u00b7") \
            or _AI.get("aud_prog") is not None:
        return "auditing"
    return kind or "thinking"


# AFK CATCH-UP, live. "on" only while he is away AND the setting is
# on; "held"/"shut" are exactly how he left things, kept so they can be
# put back untouched.
_AFKAI = {"on": False, "since": 0.0, "idle": 0.0,
          "held": None, "shut": None, "woke": 0}
# _afk_ai_tick runs on the watcher thread while afk_ai_set and
# _afk_ai_forget run on the pywebview thread: arming and releasing are
# both check-then-act on the dict above. Held ONLY across the swap.
_AFKAI_LOCK = threading.Lock()


def _bg_work_allowed():
    """One question, one answer: may ANY background work run? The
    master switch is the whole answer - the finer switches and holds
    speak below it.

    ...unless he is genuinely away and asked for the catch-up, in which
    case the machine is the tome's until he comes back. Note this reads
    the OVERRIDE and never his saved preference: bg_shutdown is written
    to settings.json, so flipping it here would quietly rewrite what he
    chose and survive the restart."""
    if _AFKAI.get("on"):
        return True
    return not SETTINGS.get("bg_shutdown")


def _afk_ai_off_kinds():
    """Which parts of the suite are switched OFF in Settings, in his
    words. The catch-up lifts pauses, never these - so it says which
    ones it is going to skip rather than appearing to do less than it
    promised."""
    off = []
    if not SETTINGS.get("ai_highlights", True):
        off.append("sound & gold moments")
    if not SETTINGS.get("ai_transcribe", True):
        off.append("transcripts")
    if not SETTINGS.get("insights_auto", True):
        off.append("the review")
    try:
        if _describer_paths() is None:
            off.append("the describer is not installed")
    except Exception:
        pass
    try:
        if _reader_paths() is None and SETTINGS.get("ai_transcribe", True):
            off.append("the reader is not installed")
    except Exception:
        pass
    return off


def _afk_ai_forget(lanes=None):
    """He has just spoken about these lanes, so the catch-up's memory
    of them is void.

    The release used to compare each lane against the all-false state
    the override wrote, which notices a Stop (it ADDS a hold) but is
    blind to a Resume (it leaves the lane exactly as the override left
    it). Rather than guess, every button that sets a hold says so."""
    with _AFKAI_LOCK:
        if not _AFKAI.get("on"):
            return
        was = _AFKAI.get("held")
        mine = _AFKAI.get("set")
        for k in (lanes or ("listening", "hearing", "thinking",
                            "auditing")):
            if isinstance(was, dict):
                was.pop(k, None)
            if isinstance(mine, dict):
                mine.pop(k, None)


def _afk_ai_release(why=""):
    """Put back exactly what he had, and hand the card back."""
    with _AFKAI_LOCK:
        if not _AFKAI.get("on"):
            return False            # the other thread already has it
        was = dict(_AFKAI.get("held") or {})
        mine = dict(_AFKAI.get("set") or {})
        shut = bool(_AFKAI.get("shut"))
        _AFKAI["on"] = False
        _AFKAI["held"] = None
        _AFKAI["shut"] = None
        _AFKAI["set"] = None
    held = _AI.setdefault("held", {})
    for k in ("listening", "hearing", "thinking", "auditing"):
        # HIS PRESS OUTRANKS MY SNAPSHOT, in both directions. A Stop
        # ADDS a hold and is caught by the comparison below; a Resume
        # leaves the lane exactly as the override left it and cannot
        # be, so the buttons call _afk_ai_forget and the lane simply
        # is not in `was` any more.
        if k not in was:
            continue
        if k in mine and bool(held.get(k)) != bool(mine.get(k)):
            continue
        held[k] = bool(was.get(k))
    _AI["paused"] = all(held.get(k) for k in
                        ("listening", "hearing", "thinking", "auditing"))
    # THE CARD IS HIS AGAIN. Re-holding a lane while the describer is
    # still running on it is not handing anything back, so whatever is
    # in hand stops if its own lane is held again - or if the master
    # switch he had set is back. What it wrote is already on disk.
    busy = _AI.get("busy")
    lane = None
    if busy:
        try:
            lane = _ai_effective_lane(busy[0], busy[1])
        except Exception:
            lane = busy[0]
    quiet = bool(shut or (lane and held.get(lane)) or _AI["paused"])
    if quiet and busy:
        _ai_abort()
    log("AFK catch-up ended - " + (why or "you are back")
        + ". Everything is back exactly as you left it"
        + ("; the job in hand let go of the card." if quiet
           and _AI.get("busy") else "."))
    _ai_state_save()
    return True


def _afk_ai_tick():
    """One beat of the catch-up: are you away, and for how long?

    Runs BEFORE every other gate on purpose - the whole point is to
    speak over a master switch that would otherwise return first."""
    try:
        if not SETTINGS.get("afk_ai"):
            _AFKAI["idle"] = 0.0
            return _afk_ai_release("the setting was switched off")
        try:
            mins = max(1, int(SETTINGS.get("afk_ai_minutes") or 15))
        except Exception:
            mins = 15
        idle = _afk_idle_recent()
        _AFKAI["idle"] = idle
        if _AFKAI.get("on"):
            # BACK AT THE DESK. Five seconds, not zero: the clock is
            # polled every few seconds, so "0" would almost never be
            # the value we happen to see.
            if idle < 5:
                return _afk_ai_release("you are back")
            return False
        if idle < mins * 60:
            return False
        with _AFKAI_LOCK:
            if _AFKAI.get("on"):
                return False        # someone armed it between the two
            #                         checks: never snapshot twice, or
            #                         the second one records the state
            #                         the first already cleared
            _AFKAI["held"] = dict(_AI.get("held") or {})
            _AFKAI["shut"] = bool(SETTINGS.get("bg_shutdown"))
            # what the catch-up itself is about to write, so release can
            # tell "still as I left it" from "he has since changed this"
            _AFKAI["set"] = {k: False for k in
                             ("listening", "hearing", "thinking",
                              "auditing")}
            _AFKAI["on"] = True
            _AFKAI["since"] = time.time()
            _AFKAI["woke"] = int(_AFKAI.get("woke") or 0) + 1
            held = _AI.setdefault("held", {})
            for k in ("listening", "hearing", "thinking", "auditing"):
                held[k] = False
        _AI["paused"] = False
        _AI["t_last"] = 0                # start on this very beat
        skip = _afk_ai_off_kinds()
        log("AFK catch-up: no keyboard, mouse or controller for %d "
            "minutes, so the tome is taking the whole suite - sound, "
            "transcripts, the review and the audit. Anything you had "
            "paused is remembered and comes straight back the moment "
            "you touch something." % mins
            + ("" if not skip else
               "  NOT included, because it is switched off in Settings "
               "rather than paused: " + ", ".join(skip) + "."))
        return True
    except Exception:
        return False


def _ai_next_sweep():
    """What the sweep would take next, by NAME - the queue stops being
    a mystery. Read-only, 8-second cache, same selection the real walk
    makes; drift between the two is a review item, not a crash."""
    now = time.time()
    c = _AI.get("next_pick")
    if c and now - c[0] < 8:
        return c[1]
    val = None
    try:
        held = _AI.get("held") or {}
        if _bg_work_allowed() and not (held and all(held.values())):
            out = SETTINGS.get("output_dir", "")
            vids = []
            for d, kind in _library_dirs(out):
                for v in _scan_dir_mp4s(d, kind):
                    vids.append((v["path"], v.get("mtime") or 0))
            vids.sort(key=lambda pm: -pm[1])
            do_stt = (SETTINGS.get("ai_transcribe", True)
                      and _reader_paths() is not None
                      and not held.get("hearing"))
            do_hl = (SETTINGS.get("ai_highlights", True)
                     and not held.get("listening"))
            do_ins = (SETTINGS.get("insights_auto", True)
                      and not held.get("thinking")
                      and _describer_paths() is not None)
            for p, mt in vids:
                if _queued_finish_badge(p):
                    continue
                # THE SAME ANSWER THE REAL WALK GIVES. The sweep skips
                # a recording he has just skipped; this preview did
                # not, so the plate went on announcing it as "next
                # from the shelf" for the full fifteen minutes - which
                # reads exactly like the skip having failed.
                if _ai_skipped_recently(p):
                    continue
                if (_AI.get("failed") or {}).get(p) == mt:
                    continue
                if do_hl and (not _ai_sidecar_fresh(p, "hl")
                              or not _ai_sidecar_fresh(p, "lvl")):
                    val = {"name": os.path.basename(p),
                           "kind": "listening"}
                    break
                if do_stt and (not _ai_sidecar_fresh(p, "stt")
                               or (SETTINGS.get("reread_old")
                                   and _stt_stale_reader(p))):
                    val = {"name": os.path.basename(p),
                           "kind": "hearing"}
                    break
                if (do_ins and (_ins_owing(p) or _sns_owing(p))
                        and _ai_sidecar_fresh(p, "hl")
                        and _ai_sidecar_fresh(p, "stt")):
                    val = {"name": os.path.basename(p),
                           "kind": "thinking"}
                    break
                if (SETTINGS.get("insights_auto", True)
                        and not held.get("auditing")
                        and _aud_owing_swept(p)
                        and _ai_sidecar_fresh(p, "hl")
                        and _ai_sidecar_fresh(p, "stt")):
                    val = {"name": os.path.basename(p),
                           "kind": "auditing"}
                    break
    except Exception:
        val = None
    _AI["next_pick"] = (now, val)
    return val


def _ai_state_path():
    return os.path.join(_data_dir(), "ai_state.json")


def _afk_ai_true_held():
    """His holds, not the catch-up's. While the override is running the
    live dict is all-false by design; writing that to ai_state.json
    would suppress the "lanes that were standing down are awake again"
    notice at the next boot - and silent holds already cost him a week
    of asks once."""
    if _AFKAI.get("on") and isinstance(_AFKAI.get("held"), dict):
        out = dict(_AI.get("held") or {})
        out.update(_AFKAI["held"])
        return out
    return dict(_AI.get("held") or {})


def _ai_state_save():
    """The line, the holds and the master switch, written down - so
    closing LORE and opening it continues the SAME work. The job in
    hand is saved as the head of the line: its banked pieces are on
    disk, so re-asking is a resume, not a restart."""
    try:
        with _AI_FORCE_LOCK:
            q = list(_AI.get("force_queue") or [])
            f = _AI.get("force")
            if f:
                q = [(f, _AI.get("force_want") or "all",
                      bool(_AI.get("force_redo")),
                      sorted(_AI.get("force_ran") or set()))] + q
        doc = {"queue": [[it[0], it[1] if len(it) > 1 else "all",
                          bool(it[2]) if len(it) > 2 else False,
                          list(it[3]) if len(it) > 3 else []]
                         for it in q],
               # HIS holds, not the catch-up's - see
               # _afk_ai_true_held
               "held": _afk_ai_true_held()}
        tmp = _ai_state_path() + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(doc, fh)
        os.replace(tmp, _ai_state_path())
    except Exception:
        pass


def _ai_state_merge():
    """An update's repair rows fold in BEHIND whatever he has queued.

    The 3.17 installer copied its rows OVER ai_state.json, which is
    where his queued work went - two hundred asks, clobbered by eight
    of mine. An update may suggest work; it may never replace his."""
    mp = os.path.join(_data_dir(), "ai_state.merge.json")
    if not os.path.isfile(mp):
        return
    try:
        with open(mp, encoding="utf-8") as fh:
            doc = json.load(fh) or {}
        rows = []
        with _AI_FORCE_LOCK:
            have = {(it[0], str(it[1] if len(it) > 1 else "all"))
                    for it in (_AI.get("force_queue") or [])}
        for it in (doc.get("queue") or []):
            if (isinstance(it, list) and it
                    and isinstance(it[0], str)
                    and os.path.isfile(it[0])
                    and (it[0], str(it[1] if len(it) > 1
                                    else "all")) not in have):
                rows.append((it[0],
                             str(it[1]) if len(it) > 1 else "all",
                             bool(it[2]) if len(it) > 2 else False,
                             [str(x) for x in it[3]]
                             if len(it) > 3 else []))
        if rows:
            with _AI_FORCE_LOCK:
                _AI["force_queue"] = list(_AI.get("force_queue")
                                          or []) + rows
            _ai_state_save()
            log("The update suggested " + str(len(rows)) + " job(s) - "
                "added BEHIND everything you queued yourself.")
    except Exception:
        pass
    try:
        os.remove(mp)
    except OSError:
        pass


def _ai_state_load():
    """Boot: the line and the holds come back exactly as they were
    left. Paths that no longer exist fall out quietly."""
    try:
        with open(_ai_state_path(), encoding="utf-8") as fh:
            doc = json.load(fh) or {}
    except Exception:
        return
    try:
        q = []
        for it in (doc.get("queue") or []):
            if (isinstance(it, list) and it
                    and isinstance(it[0], str) and os.path.isfile(it[0])):
                q.append((it[0],
                          str(it[1]) if len(it) > 1 else "all",
                          bool(it[2]) if len(it) > 2 else False,
                          [str(x) for x in it[3]] if len(it) > 3 else []))
        # A HOLD IS "NOT RIGHT NOW", AND IT DIES WITH THE TOME.
        # Restoring it made a single Stop press - pressed to free the
        # card for one game - silence every lane for ever, across every
        # restart, with nothing on screen to say why. Measured on his
        # own machine: all four held, queue empty, nothing run in days.
        # The MASTER SWITCH is the persistent one; it has its own
        # button and its own banner, and it still persists below.
        held = _AI.setdefault("held", {"listening": False,
                                       "hearing": False})
        for k in ("listening", "hearing", "thinking", "auditing"):
            held[k] = False
        _AI["paused"] = False
        if any((doc.get("held") or {}).values()):
            log("The lanes that were standing down are awake again - a "
                "hold means 'not right now', and the tome has restarted "
                "since. (To stop background work until you say "
                "otherwise, use Pause it all on the Working page.)")
        with _AI_FORCE_LOCK:
            _AI["force_queue"] = q
        if q:
            log("The waiting line came back with " + str(len(q))
                + " item(s) - closing the tome loses nothing.")
    except Exception:
        pass


def _ai_skipped_recently(path, within=900):
    """Was this recording skipped by hand in the last quarter hour?
    A skip is 'not this one, now' - it expires, it is never a refusal,
    and it never reaches the shelf of things the tome gave up on."""
    try:
        t = (_AI.get("skipped") or {}).get(path)
        return bool(t) and (time.time() - t) < within
    except Exception:
        return False


def _ai_lanes_free(want):
    """May a forced ask with this want start right now, or is a lane it
    needs held? Held lanes make queued work WAIT - never disappear."""
    held = _AI.get("held") or {}
    return not any(held.get(k) for k in _ai_want_lanes(want))


def _ai_ask_unhold(want):
    """A thing he asked for BY NAME is never held.

    _ai_want_lanes("all") returns the three working lanes and never
    "auditing" - so an "All of it" ask would describe a night and then
    sit behind a held audit lane for ever. An ask lifts every lane its
    chain can reach."""
    lanes = set(_ai_want_lanes(want))
    if want in ("all", "think", "audit"):
        lanes.add("auditing")      # the chain ends in an audit
    held = _AI.setdefault("held", {"listening": False, "hearing": False})
    woke = [k for k in lanes if held.get(k)]
    for k in lanes:
        held[k] = False
    # HE HAS SPOKEN ABOUT THESE LANES. Without this the AFK catch-up
    # would put back, on his return, the very holds this ask lifted -
    # the ask silently re-paused behind him.
    _afk_ai_forget(lanes)
    _AI["paused"] = all(held.get(x) for x in
                        ("listening", "hearing", "thinking", "auditing"))
    if woke:
        log("Asked for by name, so " + ", ".join(sorted(woke))
            + " woke up for it.")
    return woke


def _ai_unhold_for(want):
    """Asking by name lifts the hold on the lanes that ask needs. The
    press is him saying "this one, now", and that outranks the earlier
    "wait" - without this, a name-ask made while held would sit in the
    queue in silence, which is the pause bug wearing a new hat."""
    held = _AI.get("held") or {}
    lifted = [k for k in _ai_want_lanes(want) if held.get(k)]
    for k in lifted:
        held[k] = False
    if lifted:
        _AI["paused"] = all(held.values()) if held else False
        log("You asked by name, so the hold is lifted on: "
            + ", ".join(AI_LABEL.get(k, k) for k in lifted) + ".")


def _ai_abort(force_too=True):
    """A game just appeared: stop the current AI job NOW (the reader /
    ffmpeg child is terminated; the sidecar stays missing and the job
    simply re-runs at the next idle stretch).

    force_too=False spares a job you ASKED for by name - a game starting is
    not a reason to abandon the one recording you pointed at."""
    pr = _AI.get("proc")           # the JOB's child, captured before any
    #                                 other stop() can touch the slot
    srv = _ASK.get("srv")
    if srv is not None and srv.pr is not None:
        try:
            srv.stop()             # the sage's 10 GB yields to the game,
        except Exception:          # spared job or not
            pass
        _ASK["srv"] = None
    _desc_keep_drop()              # a parked warm describer yields too
    try:
        _aud_keep_drop()               # and the parked thinker with it
    except NameError:
        pass                           # import order; defined below
    # spare ONLY the job he pointed at by name - always_read used to give
    # EVERY background job this pass, which let a 10 GB describer sit on
    # the card straight through a game launch
    if not force_too and _AI.get("busy_path") \
            and _AI.get("busy_path") == _AI.get("force"):
        return
    _AI["abort"] = True
    _AI["wind"] = False                # stop outranks a pending wind-down
    _AI["wind_src"] = None
    if pr is not None:
        try:
            pr.terminate()
        except Exception:
            pass


def _ai_run(cmd, timeout, flags, env=None):
    """subprocess.run, but abortable via _ai_abort() - the handle is
    published so a starting game can kill the child instantly."""
    pr = _popen(cmd, stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE, creationflags=flags,
                          env=env)
    _AI["proc"] = pr
    if _AI["abort"]:
        try:                       # abort landed between gate and spawn -
            pr.terminate()         # close that window immediately
        except Exception:
            pass
    try:
        out, err = pr.communicate(timeout=timeout)
        return pr.returncode, out, err
    except subprocess.TimeoutExpired:
        # communicate() does NOT kill on timeout - without this the child
        # runs orphaned (even through the next game session) while holding
        # the temp files other jobs want
        try:
            pr.kill()
            pr.communicate()
        except Exception:
            pass
        return -1, b"", b"timeout"
    finally:
        _AI["proc"] = None


_Layer = collections.namedtuple("_Layer", "path how")


def _extract_layers(video_path, names, base_wav, want, rate, timeout,
                    flags):
    """ONE ffmpeg read of the recording writes every layer a pass needs,
    mono pcm_s16le at `rate`. want[0] lands at base_wav itself (the
    worker's first argument, and what the .ctl/.prog files are keyed
    on); the rest at base_wav + '.<layer>.wav'. Layers that resolve to
    the same source - an old file's room IS its mix - are ALIASED to one
    file and decoded once. Returns {layer: _Layer(path, how)} with path
    '' for a layer the file does not have or that failed to land, plus
    'rc' (ffmpeg's return code; the caller owns the failure ladder). A
    single source produces exactly today's one-output command, so an
    old night's arguments do not move."""
    plan = {}
    for L in want:
        pre, maps, how = _layer_args(video_path, L, names, fan=1)
        if not maps:
            plan[L] = None
            continue
        plan[L] = (pre[2] if len(pre) > 1 else None,
                   maps[0][1] if maps[0] else "a", how)
    groups = {}                      # (graph, target) -> [layers], want order
    for L in want:
        if plan[L]:
            groups.setdefault(plan[L][:2], []).append(L)
    single = len(groups) == 1
    graph_parts, outs, paths = [], [], {}
    for k, ((graph, target), Ls) in enumerate(groups.items()):
        if graph is None:
            pad = None if target == "a" else target
        elif single:
            pad = target
            graph_parts.append(graph)
        else:
            pad = "[G%d]" % k
            graph_parts.append(graph[:graph.rfind(target)] + pad)
        p = base_wav if Ls[0] == want[0] else base_wav + "." + Ls[0] + ".wav"
        for L in Ls:
            paths[L] = p
        outs.append((pad, p))
    cmd = [SETTINGS["ffmpeg_path"], "-y", "-loglevel", "error",
           "-i", video_path]
    if graph_parts and not single:
        cmd += ["-filter_complex", ";".join(graph_parts)]
    for pad, p in outs:
        cmd += ["-vn"]
        if single and graph_parts:
            cmd += ["-filter_complex", graph_parts[0]]
        if pad is None:
            cmd += ["-map", "0:a:0"] if graph_parts else []
        else:
            cmd += ["-map", pad]
        cmd += ["-ac", "1", "-ar", str(rate), "-c:a", "pcm_s16le", p]
    rc = 0
    if outs:
        rc, _o, _e = _ai_run(cmd, timeout, flags)
    out = {}
    for L in want:
        pl = plan[L]
        if pl is None:
            out[L] = _Layer("", None)
        else:
            out[L] = _Layer(paths[L] if rc == 0 and os.path.isfile(paths[L])
                            else "", pl[2])
    out["rc"] = rc
    return out


#  Two models ship. base.en is small and quick but it is ENGLISH-ONLY and
#  weak on accents: on this library it produced one usable line per two
#  minutes of speech and fell into repetition loops ("...the same sentence
#  forty times"). large-v3-turbo is multilingual, far more accurate on
#  accented English, and measured only ~1.7x slower here (10.5x realtime
#  against 17.6x) - worth every second.
def _ai_sidecar(video_path, kind):
    """Path of a video's transcript ('stt') or highlights ('hl') sidecar."""
    name = os.path.splitext(os.path.basename(video_path))[0]
    return os.path.join(_thumb_dir(SETTINGS.get("output_dir", "")),
                        f"{name}.{kind}.json")


# WHICH SIDECARS EACH LANE OWNS. A fresh pass rebuilds these, so a
# fresh pass is what archives them.
_ATTIC_OF = {"listening": ("hl", "lvl"),
             "hearing": ("stt",),
             "thinking": ("ins", "sns", "vis"),
             "auditing": ("aud",)}


def _attic_dir():
    return os.path.join(_thumb_dir(SETTINGS.get("output_dir", "")),
                        ".attic")


def _ai_attic(video_path, lanes, older_than=None):
    """Move aside the sidecars a fresh pass is about to rewrite.

    "if i press do all.. it should delete all previous version of
    everything.. or not delete.. just archive older version and start
    from scratch". Deleting is easy and wrong: a description is hours
    of model time and the only copy of what the tome once thought. The
    old reading moves to the .attic folder beside the thumbnails,
    stamped with the hour it was replaced,
    and the new pass starts on genuinely empty ground - which is also
    the only way a redo can rebuild a layer that already looked
    fresh."""
    moved = []
    try:
        base = os.path.splitext(os.path.basename(video_path))[0]
        att = _attic_dir()
        os.makedirs(att, exist_ok=True)
        stamp = _dt.datetime.now().strftime("%Y%m%d-%H%M%S")
        for lane in lanes:
            for kind in _ATTIC_OF.get(lane, ()):
                src = _ai_sidecar(video_path, kind)
                if not os.path.isfile(src):
                    continue
                # NEVER THIS ASK'S OWN WORK. A lane that finished while
                # a game was starting is never recorded as run (abort
                # clears the bookkeeping), so the drain comes back for
                # it - and without this test it would file away the
                # very curve it had just written and do it all again.
                if older_than is not None:
                    try:
                        if os.path.getmtime(src) >= older_than:
                            continue
                    except OSError:
                        pass
                dst = os.path.join(att, "%s.%s.%s.json"
                                        % (base, kind, stamp))
                try:
                    # A COPY. NEVER A MOVE. Taking the file away broke
                    # every guard that reads the previous reading at
                    # write time - the .v1/.v2/.v3 bank, his typed
                    # voice names, the eye's better-pass test, the
                    # review's carry-forward, the .ins staging - and
                    # it was never what made a redo fresh anyway:
                    # redo=True is, and the passes already honour it.
                    # The writers do their own banking, so this does
                    # not bank as well; doing both would rotate a real
                    # generation off the end of the chain for nothing.
                    import shutil as _sh
                    _sh.copy2(src, dst)
                    moved.append(kind)
                except OSError:
                    pass
    except Exception:
        pass
    return moved


def _read_sidecar(video_path, kind):
    """ONE reader for every sidecar shape this app has ever written.

    Returns a dict in today's shape, or None when absent or unreadable:
      hl  -> {"events": [...]}       (v1 wrote the events as a bare list)
      ins -> "windows" always a dict; each window {"segments", "moments"}
             (2.66 wrote a bare list per window); every moment carries a
             "kind" key ("" where the old writer had none)
      stt/lvl -> the dict as stored
    Normalisation only - nothing is ever written back."""
    try:
        with open(_ai_sidecar(video_path, kind), encoding="utf-8") as fh:
            d = json.load(fh)
    except Exception:
        return None
    if isinstance(d, list):
        d = {"events": d} if kind == "hl" else {"segments": d}
    if not isinstance(d, dict):
        return None
    if kind == "vis":
        # a half-written or ancient sighting file must not crash a caller
        # that only ever wanted to draw a list
        for k2 in ("looks", "places", "creatures"):
            if not isinstance(d.get(k2), list):
                d[k2] = []
    if kind == "ins":
        w = d.get("windows")
        if not isinstance(w, dict):
            d["windows"] = {}
        else:
            d["windows"] = {k: (v if isinstance(v, dict)
                                else {"segments": v or [], "moments": []})
                            for k, v in w.items()}
        for m in (d.get("moments") or []):
            if isinstance(m, dict) and "kind" not in m:
                m["kind"] = ""
    return d

# THE PICTURE FACT (3.32): <base>.pic.json beside the sidecars, written
# once per recording at bind (or by a lane / the boot walk for a file
# already on the shelf). Like .src it is a recording FACT, not a lane
# product - it is not in _ATTIC_OF, so a 'Describe it' redo never
# archives it and a black night is never re-owed to the eye.
_PIC_CACHE = {}


def _write_black_tag(video_path, secs, lumas, maxes, black):
    """Write the pic.json fact; when the picture is black, also settle the
    vis.json (complete, black, no looks) so the eye lane stops asking.
    The vis is left alone when it already says black - a sidecar is
    never rewritten just to be rewritten (the mtime-is-lineage law)."""
    try:
        pp = _ai_sidecar(video_path, "pic")
        os.makedirs(os.path.dirname(pp), exist_ok=True)
        _atomic_write_json(pp, {"v": 1, "black": bool(black),
                                "sampled": list(secs), "luma": list(lumas),
                                "max": list(maxes), "at": time.time()})
        _PIC_CACHE.pop(pp, None)
        if not black:
            return
        vp = _ai_sidecar(video_path, "vis")
        try:
            with open(vp, encoding="utf-8") as fh:
                was = json.load(fh) or {}
            if (isinstance(was, dict) and was.get("black")
                    and was.get("complete") and not was.get("failed")):
                return              # already settled as black: not a write
        except Exception:
            pass
        try:
            _bank_sidecar(video_path, "vis")
        except Exception:
            pass
        _atomic_write_json(vp, {"v": 1, "looks": [], "places": [],
                                "creatures": [], "complete": True,
                                "tries": 0, "black": True,
                                "counters": {"black": len(secs)}})
    except Exception:
        pass


def _pic_black(video_path):
    """Does pic.json say this recording's picture is black? READ ONLY:
    absent means False, and it never probes - the sweep asks this about
    every recording every beat, so it is cached on the fact's clock and
    size like _hud_owing (the ONE JOB SLOT law: an owing test must never
    open a video or spawn ffmpeg)."""
    pp = _ai_sidecar(video_path, "pic")
    try:
        st = os.stat(pp)
    except OSError:
        return False
    key = (round(st.st_mtime, 1), st.st_size)
    hit = _PIC_CACHE.get(pp)
    if hit and hit[0] == key:
        return hit[1]
    blk = False
    try:
        with open(pp, encoding="utf-8") as fh:
            d = json.load(fh)
        blk = bool(isinstance(d, dict) and d.get("black"))
    except Exception:
        blk = False
    _PIC_CACHE[pp] = (key, blk)
    return blk


def _pic_settle(video_path):
    """The LANE-side reader: a file with no pic.json yet is probed here
    (1-8 s of CPU on a lane thread, never the watcher's) and tagged
    either way, so it is asked once per file. An unanswered probe (a
    cold platter, a seek that failed) writes nothing and fails open."""
    if os.path.isfile(_ai_sidecar(video_path, "pic")):
        return _pic_black(video_path)
    try:
        black, lumas, maxes, secs = _picture_probe(video_path)
    except Exception:
        return False
    if black is None:
        return False
    _write_black_tag(video_path, secs, lumas, maxes, black)
    if black:
        log(f"The picture of {os.path.basename(video_path)} is black - the "
            f"capture gave no frames that night. The eye will not look.")
    return bool(black)


def _hype_bar(vals):
    """Where the night's own flow counts as HOT, and whether it ever
    does -> (bar, flat). Night-relative - p90, or three MADs over the
    median, whichever is higher - with a FLOOR: a calm night whose whole
    spread is the model's noise gets a bar above its own maximum, so
    every consumer reads it flat and retones nothing. Fed SPOKEN windows
    only (the zeros a gated room writes are not readings)."""
    sv = sorted(float(x) for x in vals)
    n = len(sv)
    if n < 8:
        return 1.0, True
    med = sv[n // 2]
    p90 = sv[int(n * 0.9)]
    mad = sorted(abs(x - med) for x in sv)[n // 2] or 0.005
    bar = max(p90, med + max(HYPE_MIN_RISE, 3.0 * mad))
    flat = (sv[-1] - med) < HYPE_MIN_RISE
    return round(bar, 4), flat


def _ins_retone(moments, sns, hl=None):
    """The senses cross-examine the review's feelings. A moment filed
    funny or scary is re-read against the arousal curve at that second
    (scored against the night's own spread) and against whether anyone
    actually laughed or screamed nearby. High arousal with neither is
    EXCITEMENT - the kind he kept asking for by name. Returns how many
    were retoned; mutates in place, keeps the original under kind0.

    3.31: a curve fed by the ROOM (hype.src 'room') is judged against
    _hype_bar over its spoken windows - hot means the room really rose,
    a flat night retones nothing, and a window nobody spoke in (0) is
    never hot. A mix-fed curve (every older sidecar) keeps the p85 rule
    it was audited under: the shelf's reviews carry 186 promotions and
    308 blanked tones from it (measured), and re-judging them under a
    rule they were not built with would re-owe every one."""
    try:
        h = (sns or {}).get("hype") or {}
        v = [float(x) for x in (h.get("v") or [])]
        hop = float(h.get("hop") or 3.0)
        if len(v) < 20 or not moments:
            return 0
        src = str(h.get("src") or "mix")
        if src == "room":
            spoken = [x for x in v if x > 0]
            if len(spoken) < 20:
                return 0
            bar, flat = _hype_bar(spoken)
            if flat:
                return 0
            p85 = None
        else:
            sv = sorted(v)
            p85 = sv[int(len(sv) * 0.85)]
        # LAUGHTER LIVES IN THE .hl, NOT THE .sns - the old lookup
        # searched a sidecar that has never carried a laugh, so the
        # stand-test could not pass and only the p85 bypass saved any
        # label. Measured: 1287 of 1444 funny moments had no laugh
        # within ten seconds of them.
        evs = [(float(e.get("t") or 0), str(e.get("kind") or ""))
               for e in ((hl or {}).get("events") or [])]
        n = 0
        for m in moments:
            k = str(m.get("kind") or "")
            if k not in ("funny", "scary"):
                continue
            try:
                t = float(m.get("t") or 0)
            except (TypeError, ValueError):
                continue
            near = [kk for tt, kk in evs if abs(tt - t) <= 10]
            if k == "funny" and "laugh" in near:
                continue              # someone really laughed - it stands
            if k == "scary" and "scream" in near:
                continue              # someone really screamed - it stands
            x = v[max(0, min(len(v) - 1, int(t / hop)))]
            m["kind0"] = k
            # hot with no laugh is EXCITEMENT; cold with no laugh is
            # just a moment - a tone word needs its evidence
            hot = (x > 0 and x >= bar) if p85 is None else (x >= p85)
            m["kind"] = "excited" if hot else ""
            n += 1
        return n
    except Exception:
        return 0


def _merge_sns_into_hl(video_path, sns=None):
    """Fold the senses' sound events + HUD reads into the gold marks.

    Lives apart from _senses_one because a REDONE sound pass rebuilds hl
    from nothing - without this re-fold, redoing the sound silently
    dropped every sense mark (cheer, scare, VICTORY...) the ears had
    already earned. Near-duplicate-guarded, so calling it twice is safe.
    Returns (added, error_or_None)."""
    try:
        # A PASS THAT JUST RAN MAY ALSO TAKE MARKS BACK. Nothing here ever
        # removed a kind-carrying mark, so the three music ticks his
        # backrooms night earned from a fluorescent hum sat on the bar for
        # good - re-running the ears could not clear them, and a fix he
        # cannot see on his own library is not a fix. Only a fresh pass
        # prunes, and only the kind it just re-judged.
        fresh = sns is not None
        if sns is None:
            sp = _ai_sidecar(video_path, "sns")
            # FRESH OR NOTHING. A .sns older than the video describes
            # footage that may have been cut - folding it plants ghost
            # marks at times that no longer exist, and nothing downstream
            # ever removes a kind-carrying mark.
            try:
                if not os.path.isfile(sp) or \
                        os.path.getmtime(sp) < os.path.getmtime(video_path):
                    return 0, None
            except OSError:
                return 0, None
            with open(sp, encoding="utf-8") as fh:
                sns = json.load(fh) or {}
        # 3.31 WHOSE EARS. A sound event heard on the GAME tap may sit
        # on a game mark or an old untagged mark, never on a room shout
        # - it would label his shout "cheer" off the game's crowd. A
        # mix-fed answer (an older worker, an older night) heard the
        # room too and sits where it always did; the screen is not a
        # sound source and names whatever it lands on, as today.
        csrc = ((sns.get("src") or {}).get("clap")) or "mix"
        newev = [dict(e2, src=csrc) for e2 in (sns.get("events") or [])] \
            + [{"t": e2["t"], "kind": e2["kind"], "p": 0.2, "src": "screen"}
               for e2 in (sns.get("ocr") or [])]
        if not newev and not fresh:
            return 0, None
        with open(_ai_sidecar(video_path, "hl"), encoding="utf-8") as fh:
            hl = json.load(fh) or {}
        gold = hl.get("events") or []
        ceil = max([g.get("z") or 0 for g in gold] + [10.0])
        added, changed = 0, False
        # music only: it is the kind the ears just re-judged against the
        # room. A missing "music" key means they had no opinion at all
        # (the pack asks for no music, or the pass fell over) - a pass
        # that failed must never delete anything.
        pruned = 0
        if fresh and sns.get("music") is not None:
            heard = [e2["t"] for e2 in newev if e2.get("kind") == "music"]
            for g in gold:
                if g.get("kind") == "music" and not [
                        1 for t2 in heard
                        if abs((g.get("t") or 0) - t2) <= 8.0]:
                    # TAKE THE LABEL, NEVER THE MARK. An older fold stamped
                    # "music" onto whatever loud peak was already sitting
                    # there, so deleting the event would delete a real
                    # moment he heard for a mistake the ears made about it.
                    # The lie goes; the mark stays and answers to Loud.
                    g.pop("kind", None)
                    pruned += 1
        for e2 in newev:
            z2 = round(ceil + 1.0 + float(e2.get("p") or 0.1), 2)
            esrc = e2.get("src") or csrc
            near = [g for g in gold
                    if abs((g.get("t") or 0) - e2["t"]) <= 8.0
                    and not (esrc == "game" and g.get("src") == "room")]
            if not near:
                # a repick can WALK a kept mark up to 8s per pass; two
                # passes put it outside the 8s window and this fold then
                # planted a twin. A same-kind mark within 20s IS this
                # event, moved - never a second one.
                near = [g for g in gold
                        if g.get("kind") == e2["kind"]
                        and abs((g.get("t") or 0) - e2["t"]) <= 20.0
                        and not (esrc == "game" and g.get("src") == "room")]
            if near:
                # a near mark borrows the kind - that alone is worth
                # writing back, or the label vanishes on the next redo
                if "kind" not in near[0]:
                    near[0]["kind"] = e2["kind"]
                    changed = True
                elif near[0]["kind"] != e2["kind"]:
                    # TWO THINGS HAPPENED IN THAT SECOND. The seat was
                    # taken - by laughter, usually, because it rides
                    # the gold pass and lands first - and the second
                    # signal used to be dropped on the floor. It rides
                    # along now: same mark, same tick, both named.
                    _al = list(near[0].get("also") or [])
                    if e2["kind"] not in _al:
                        _al.append(e2["kind"])
                        near[0]["also"] = _al
                        changed = True
            else:
                gold.append({"t": round(float(e2["t"]), 1),
                             "z": z2, "kind": e2["kind"], "src": esrc})
                added += 1
        if added or changed or pruned:
            gold.sort(key=lambda g: g.get("t") or 0)
            hl["events"] = gold
            _atomic_write_json(_ai_sidecar(video_path, "hl"), hl)
        if added or pruned:
            _AI["done_rev"] = int(_AI.get("done_rev") or 0) + 1
        if pruned:
            log(f"The ears took back {pruned} music mark(s) on "
                f"{os.path.basename(video_path)} - they do not hear it "
                f"any more.")
        return added, None
    except Exception as e:
        return 0, str(e)[:120]


def _ins_failed(video_path):
    """A review that FAILED wrote a sidecar saying so - and a sidecar that
    exists used to mean "described", so the recording was finished forever
    and the lightning button could never retry it. It is not a result."""
    try:
        with open(_ai_sidecar(video_path, "ins"), encoding="utf-8") as fh:
            return bool(json.load(fh).get("failed"))
    except Exception:
        return False


def _ai_sidecar_fresh(video_path, kind):
    # A FAILED REVIEW COUNTS AS DONE HERE, on purpose. 2.56 made it count as
    # unfinished so the button could retry it - but this function is also what
    # the automatic sweep asks, and the sweep's memo of a refusal lives only in
    # memory. Every restart forgot it and began the identical doomed review
    # again: three times over on his machine, forever if left. Asking BY NAME
    # still retries - the force path checks _ins_failed() itself.
    sp = _ai_sidecar(video_path, kind)
    try:
        return (os.path.isfile(sp)
                and os.path.getmtime(sp) >= os.path.getmtime(video_path))
    except OSError:
        return False

def _ai_pending_counts():
    """(transcripts pending, highlights pending) - cheap enough for state()
    consumers to poll occasionally; cached 30s."""
    now = time.time()
    c = _AI.get("_counts")
    if c and now - c[2] < 30:
        return c[0], c[1]
    out = SETTINGS.get("output_dir", "")
    stt = hl = 0
    try:
        for d, kind in _library_dirs(out):
            for v in _scan_dir_mp4s(d, kind):
                if not _ai_sidecar_fresh(v["path"], "stt") \
                        or (SETTINGS.get("reread_old")
                            and _stt_stale_reader(v["path"])):
                    stt += 1
                if not _ai_sidecar_fresh(v["path"], "hl"):
                    hl += 1
    except Exception:
        pass
    _AI["_counts"] = (stt, hl, now)
    return stt, hl

def _lvl_is_coarse(video_path):
    """True when the sound curve was drawn by the old, blocky measurement.

    v1 curves used a fixed handful of points however long the recording was,
    so an hour-long session came out as a few dozen steps. v2 scales the
    detail with the length. A coarse one is worth re-doing; it costs seconds
    and it is what the editor draws its shape from."""
    try:
        with open(_ai_sidecar(video_path, "lvl"), encoding="utf-8") as fh:
            d = json.load(fh) or {}
    except Exception:
        # NO CURVE AT ALL counts as work still to do. This is the question
        # "does the sound pass still owe this recording anything", and the
        # answer for a missing curve is obviously yes.
        return True
    if int(d.get("v") or 1) >= 2:
        return False
    return True


